-- DIHASILKAN OTOMATIS oleh scripts/build-seed.mjs — jangan diedit manual.
-- Sumber: supabase/seed/data.mjs
-- Aman diulang: kategori di-upsert, soal dengan seed_key yang sudah ada dilewati.
do $seed$
declare
  g jsonb; c jsonb; q jsonb;
  v_parent uuid; v_q uuid; v_correct uuid;
  i integer; v_added integer := 0;
begin
  for g in select * from jsonb_array_elements($j$[{"arena":"mufrodat","slug":"mufrodat-kosakata","name":"Kosakata","name_ar":"الْمُفْرَدَاتُ","sort":0,"children":[{"slug":"dasar","name":"Kosakata dasar","name_ar":"مُفْرَدَاتٌ أَسَاسِيَّةٌ","sort":0},{"slug":"sekolah","name":"Sekolah dan kelas","name_ar":"الْمَدْرَسَةُ وَالْفَصْلُ","sort":1},{"slug":"rumah","name":"Rumah dan keluarga","name_ar":"الْبَيْتُ وَالْأُسْرَةُ","sort":2},{"slug":"makanan","name":"Makanan dan minuman","name_ar":"الطَّعَامُ وَالشَّرَابُ","sort":3},{"slug":"aktivitas","name":"Aktivitas sehari-hari","name_ar":"الْأَنْشِطَةُ الْيَوْمِيَّةُ","sort":4},{"slug":"perjalanan","name":"Perjalanan","name_ar":"السَّفَرُ","sort":5},{"slug":"kampus","name":"Kampus","name_ar":"الْجَامِعَةُ","sort":6}]},{"arena":"mufrodat","slug":"mufrodat-percakapan","name":"Ungkapan & Percakapan","name_ar":"الْمُحَادَثَةُ","sort":1,"children":[{"slug":"salam","name":"Perkenalan dan salam","name_ar":"التَّعَارُفُ وَالتَّحِيَّةُ","sort":0},{"slug":"pasar","name":"Pasar dan restoran","name_ar":"السُّوقُ وَالْمَطْعَمُ","sort":1},{"slug":"ungkapan","name":"Ungkapan sehari-hari","name_ar":"تَعْبِيرَاتٌ يَوْمِيَّةٌ","sort":2},{"slug":"fusha","name":"Percakapan Fusha","name_ar":"مُحَادَثَةٌ بِالْفُصْحَى","sort":3},{"slug":"amiyah","name":"Percakapan Amiyah Mesir","name_ar":"مُحَادَثَةٌ بِالْعَامِّيَّةِ الْمِصْرِيَّةِ","sort":4}]},{"arena":"qowaid","slug":"qowaid-nahwu","name":"Nahwu","name_ar":"النَّحْوُ","sort":2,"children":[{"slug":"mubtada-khabar","name":"Mubtada' & Khabar","name_ar":"الْمُبْتَدَأُ وَالْخَبَرُ","sort":0},{"slug":"fail","name":"Fa'il","name_ar":"الْفَاعِلُ","sort":1},{"slug":"maful-bih","name":"Maf'ul bih","name_ar":"الْمَفْعُولُ بِهِ","sort":2},{"slug":"naat","name":"Na'at","name_ar":"النَّعْتُ","sort":3},{"slug":"idhafah","name":"Idhafah","name_ar":"الْإِضَافَةُ","sort":4},{"slug":"hal","name":"Hal","name_ar":"الْحَالُ","sort":5},{"slug":"tamyiz","name":"Tamyiz","name_ar":"التَّمْيِيزُ","sort":6},{"slug":"nawasikh","name":"Nawasikh","name_ar":"النَّوَاسِخُ","sort":7},{"slug":"majrurat","name":"Majrurat","name_ar":"الْمَجْرُورَاتُ","sort":8},{"slug":"tawabi","name":"Tawabi'","name_ar":"التَّوَابِعُ","sort":9},{"slug":"anwa-jumal","name":"Macam-macam jumlah","name_ar":"أَنْوَاعُ الْجُمَلِ","sort":10}]},{"arena":"qowaid","slug":"qowaid-shorof","name":"Shorof","name_ar":"الصَّرْفُ","sort":3,"children":[{"slug":"madhi","name":"Fi'il Madhi","name_ar":"الْفِعْلُ الْمَاضِي","sort":0},{"slug":"mudhari","name":"Fi'il Mudhari'","name_ar":"الْفِعْلُ الْمُضَارِعُ","sort":1},{"slug":"amr","name":"Fi'il Amr","name_ar":"فِعْلُ الْأَمْرِ","sort":2},{"slug":"mashdar","name":"Mashdar","name_ar":"الْمَصْدَرُ","sort":3},{"slug":"isim-fail","name":"Isim Fa'il","name_ar":"اسْمُ الْفَاعِلِ","sort":4},{"slug":"isim-maful","name":"Isim Maf'ul","name_ar":"اسْمُ الْمَفْعُولِ","sort":5},{"slug":"tashrif","name":"Tashrif al-Af'al","name_ar":"تَصْرِيفُ الْأَفْعَالِ","sort":6},{"slug":"mizan","name":"Mizan Sharfi","name_ar":"الْمِيزَانُ الصَّرْفِيُّ","sort":7},{"slug":"mujarrad-mazid","name":"Mujarrad & Mazid","name_ar":"الْمُجَرَّدُ وَالْمَزِيدُ","sort":8},{"slug":"shahih-mutal","name":"Shahih & Mu'tal","name_ar":"الصَّحِيحُ وَالْمُعْتَلُّ","sort":9}]},{"arena":"qowaid","slug":"qowaid-irab","name":"I'rab","name_ar":"الْإِعْرَابُ","sort":4,"children":[{"slug":"rafa","name":"Rafa'","name_ar":"الرَّفْعُ","sort":0},{"slug":"nashab","name":"Nashab","name_ar":"النَّصْبُ","sort":1},{"slug":"jarr","name":"Jarr","name_ar":"الْجَرُّ","sort":2},{"slug":"jazm","name":"Jazm","name_ar":"الْجَزْمُ","sort":3},{"slug":"alamat-irab","name":"Tanda i'rab asli & cabang","name_ar":"عَلَامَاتُ الْإِعْرَابِ الْأَصْلِيَّةُ وَالْفَرْعِيَّةُ","sort":4},{"slug":"irab-jumlah","name":"I'rab kata dalam kalimat","name_ar":"إِعْرَابُ الْكَلِمَاتِ دَاخِلَ الْجُمَلِ","sort":5}]}]$j$::jsonb) loop
    insert into categories (arena, slug, name, name_ar, sort_order)
    values ((g->>'arena')::arena_type, g->>'slug', g->>'name', g->>'name_ar', (g->>'sort')::int)
    on conflict (slug) do update set name = excluded.name, name_ar = excluded.name_ar, sort_order = excluded.sort_order
    returning id into v_parent;
    for c in select * from jsonb_array_elements(g->'children') loop
      insert into categories (arena, parent_id, slug, name, name_ar, sort_order)
      values ((g->>'arena')::arena_type, v_parent, c->>'slug', c->>'name', c->>'name_ar', (c->>'sort')::int)
      on conflict (slug) do update set parent_id = excluded.parent_id, name = excluded.name,
        name_ar = excluded.name_ar, sort_order = excluded.sort_order;
    end loop;
  end loop;

  for q in select * from jsonb_array_elements($j$[{"key":"b5f630c4622e5a108cf6af33c0f6fe7e","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"بَابٌ","explanation":"بَابٌ artinya pintu. Bentuk jamaknya أَبْوَابٌ.","time":20,"options":["Pintu","Jendela","Dinding","Lantai"],"correct":1,"accepted":[]},{"key":"0931093249dc129d94bd63eed8151813","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"نَافِذَةٌ","explanation":"نَافِذَةٌ artinya jendela. Bentuk jamaknya نَوَافِذُ.","time":20,"options":["Jendela","Pintu","Atap","Kursi"],"correct":1,"accepted":[]},{"key":"efd5688a0aa9b3c084c066e6580e144a","cat":"dasar","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? شَمْسٌ artinya \"bulan\".","ar":"شَمْسٌ","explanation":"Salah. شَمْسٌ artinya matahari, sedangkan bulan adalah قَمَرٌ.","time":20,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"f3b915e2b05f4a35bf51644ab233497b","cat":"dasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"air\"?","ar":null,"explanation":"مَاءٌ = air. Pilihan lain: نَارٌ = api, هَوَاءٌ = udara, تُرَابٌ = tanah/debu.","time":20,"options":["مَاءٌ","نَارٌ","هَوَاءٌ","تُرَابٌ"],"correct":1,"accepted":[]},{"key":"7fa4bcdd92f66c1ce4a850983bfcfeab","cat":"dasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa lawan kata (ضِدّ) dari kata berikut?","ar":"قَرِيبٌ","explanation":"قَرِيبٌ (dekat) lawannya بَعِيدٌ (jauh). كَبِيرٌ = besar, طَوِيلٌ = panjang/tinggi, سَرِيعٌ = cepat.","time":25,"options":["بَعِيدٌ","كَبِيرٌ","طَوِيلٌ","سَرِيعٌ"],"correct":1,"accepted":[]},{"key":"dab34dd2f14fbc14e32c37302297b7a9","cat":"dasar","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa bentuk jamak dari kata berikut?","ar":"كِتَابٌ","explanation":"Jamak كِتَابٌ adalah كُتُبٌ (jamak taksir). كِتَابَاتٌ jamak dari كِتَابَةٌ (tulisan), كَتَبَةٌ jamak dari كَاتِبٌ (penulis), مَكَاتِبُ jamak dari مَكْتَبٌ (meja/kantor).","time":30,"options":["كُتُبٌ","كِتَابَاتٌ","كَتَبَةٌ","مَكَاتِبُ"],"correct":1,"accepted":[]},{"key":"7c9637dfec821b155b3f1af434eb386a","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سَبُّورَةٌ","explanation":"سَبُّورَةٌ artinya papan tulis.","time":20,"options":["Papan tulis","Buku tulis","Penghapus","Tas"],"correct":1,"accepted":[]},{"key":"7509d97b301e517496d6fb506cf35172","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مُدَرِّسٌ","explanation":"مُدَرِّسٌ adalah isim fa'il dari دَرَّسَ (mengajar), artinya pengajar/guru. Murid = طَالِبٌ atau تِلْمِيذٌ.","time":20,"options":["Guru","Murid","Kepala sekolah","Penjaga sekolah"],"correct":1,"accepted":[]},{"key":"278d68d03f0736ad823c34bf274347e0","cat":"sekolah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"buku tulis\"?","ar":null,"explanation":"كُرَّاسَةٌ = buku tulis. كِتَابٌ = buku (bacaan), مِمْسَحَةٌ = penghapus, مِسْطَرَةٌ = penggaris.","time":20,"options":["كُرَّاسَةٌ","كِتَابٌ","مِمْسَحَةٌ","مِسْطَرَةٌ"],"correct":1,"accepted":[]},{"key":"4564eb949c8802eaa05612dfc15ab05b","cat":"sekolah","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu ingin meminjam pena temanmu. Kalimat yang tepat adalah …","ar":null,"explanation":"أَسْتَعِيرُ = saya meminjam; هَلْ يُمْكِنُ أَنْ ... = bolehkah .... Pilihan lain berarti: \"Di mana penamu?\", \"Ini penaku.\", \"Aku membeli pena.\"","time":25,"options":["هَلْ يُمْكِنُ أَنْ أَسْتَعِيرَ قَلَمَكَ؟","أَيْنَ قَلَمُكَ؟","هَذَا قَلَمِي.","اِشْتَرَيْتُ قَلَمًا."],"correct":1,"accepted":[]},{"key":"90f3c136ee133fe09eaf34a78f31d627","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَطْبَخٌ","explanation":"مَطْبَخٌ berwazan مَفْعَلٌ (isim makan) dari طَبَخَ (memasak): tempat memasak = dapur.","time":20,"options":["Dapur","Kamar tidur","Kamar mandi","Ruang tamu"],"correct":1,"accepted":[]},{"key":"b07de8cddd4fd81db349b9f419270a7a","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"جَدَّةٌ","explanation":"جَدَّةٌ = nenek, جَدٌّ = kakek. Ibu = أُمٌّ, bibi = عَمَّةٌ (saudari ayah) atau خَالَةٌ (saudari ibu).","time":20,"options":["Nenek","Bibi","Kakek","Ibu"],"correct":1,"accepted":[]},{"key":"c13cbb77e4d593d56bf4b0dfb32a32b8","cat":"rumah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"saudara laki-laki\"?","ar":null,"explanation":"أَخٌ = saudara laki-laki. أُخْتٌ = saudara perempuan, اِبْنٌ = anak laki-laki, أَبٌ = ayah.","time":20,"options":["أَخٌ","أُخْتٌ","اِبْنٌ","أَبٌ"],"correct":1,"accepted":[]},{"key":"b72142060aec8394ec89b4c1f35b381c","cat":"rumah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"عَمٌّ","explanation":"عَمٌّ = saudara laki-laki ayah. Saudara laki-laki ibu disebut خَالٌ.","time":25,"options":["Paman (saudara ayah)","Paman (saudara ibu)","Kakek","Sepupu"],"correct":1,"accepted":[]},{"key":"7dcaaea49f3e82dd4dccaec92f53b11f","cat":"makanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"خُبْزٌ","explanation":"خُبْزٌ = roti. Nasi = أَرُزٌّ, daging = لَحْمٌ, keju = جُبْنٌ.","time":20,"options":["Roti","Nasi","Daging","Keju"],"correct":1,"accepted":[]},{"key":"b87ea3b1a1f31e11ac7aad4aaec00221","cat":"makanan","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"susu\"?","ar":null,"explanation":"حَلِيبٌ = susu. عَصِيرٌ = jus, شَايٌ = teh, قَهْوَةٌ = kopi.","time":20,"options":["حَلِيبٌ","عَصِيرٌ","شَايٌ","قَهْوَةٌ"],"correct":1,"accepted":[]},{"key":"f413a4429380421cd94c560edcf4a468","cat":"makanan","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama buah pada gambar dalam bahasa Arab?","ar":"🍎","explanation":"تُفَّاحٌ = apel. مَوْزٌ = pisang, بُرْتُقَالٌ = jeruk, عِنَبٌ = anggur.","time":20,"options":["تُفَّاحٌ","مَوْزٌ","بُرْتُقَالٌ","عِنَبٌ"],"correct":1,"accepted":[]},{"key":"57db8b5dcc33d8c2a65012a676b3aac0","cat":"makanan","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama buah pada gambar dalam bahasa Arab?","ar":"🍌","explanation":"مَوْزٌ = pisang. تُفَّاحٌ = apel, رُمَّانٌ = delima, تَمْرٌ = kurma.","time":20,"options":["مَوْزٌ","تُفَّاحٌ","رُمَّانٌ","تَمْرٌ"],"correct":1,"accepted":[]},{"key":"c9b9be24cc57abaebcb0874eb6d477eb","cat":"aktivitas","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَنَامُ","explanation":"نَامَ – يَنَامُ = tidur.","time":20,"options":["Tidur","Makan","Mandi","Bangun"],"correct":1,"accepted":[]},{"key":"7ba07a202dbae2d2dcdd09957b64e8ab","cat":"aktivitas","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَسْتَيْقِظُ","explanation":"اِسْتَيْقَظَ – يَسْتَيْقِظُ = bangun (dari tidur).","time":25,"options":["Bangun tidur","Berwudu","Berangkat","Beristirahat"],"correct":1,"accepted":[]},{"key":"f47041cca5645ef701c86e2cb67ea554","cat":"aktivitas","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? أَتَوَضَّأُ artinya \"saya berwudu\".","ar":"أَتَوَضَّأُ","explanation":"Benar. تَوَضَّأَ – يَتَوَضَّأُ = berwudu; huruf أَ di awal fi'il mudhari' menunjukkan \"saya\".","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"65fd7b81239b7ff4e6acb9a1cc9bb019","cat":"aktivitas","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi kalimat: \"Saya pergi ke sekolah setiap hari.\"","ar":null,"explanation":"أَذْهَبُ إِلَى الْمَدْرَسَةِ كُلَّ يَوْمٍ. Keterangan waktu كُلَّ يَوْمٍ juga boleh diletakkan di awal kalimat.","time":45,"options":["أَذْهَبُ","إِلَى","الْمَدْرَسَةِ","كُلَّ","يَوْمٍ"],"correct":null,"accepted":["أَذْهَبُ إِلَى الْمَدْرَسَةِ كُلَّ يَوْمٍ","كُلَّ يَوْمٍ أَذْهَبُ إِلَى الْمَدْرَسَةِ"]},{"key":"c9d7392db7265cd494a76788f1f2cf97","cat":"perjalanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَطَارٌ","explanation":"مَطَارٌ (dari طَارَ = terbang) = bandara. Stasiun = مَحَطَّةٌ, pelabuhan = مِينَاءٌ.","time":20,"options":["Bandara","Stasiun","Pelabuhan","Terminal"],"correct":1,"accepted":[]},{"key":"6162afe91fe135f4cabd94851c5ba3e9","cat":"perjalanan","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"tiket\"?","ar":null,"explanation":"تَذْكِرَةٌ = tiket. حَقِيبَةٌ = tas/koper, جَوَازُ السَّفَرِ = paspor, طَائِرَةٌ = pesawat.","time":25,"options":["تَذْكِرَةٌ","حَقِيبَةٌ","جَوَازُ السَّفَرِ","طَائِرَةٌ"],"correct":1,"accepted":[]},{"key":"a70083e2479b5594dd9737fe69ea88b5","cat":"perjalanan","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu ingin bertanya di mana stasiun kereta. Kalimat yang tepat adalah …","ar":null,"explanation":"أَيْنَ = di mana; مَحَطَّةُ الْقِطَارِ = stasiun kereta. Pilihan lain: \"Kapan kereta tiba?\", \"Berapa harga tiketnya?\", \"Apakah ini kursimu?\"","time":25,"options":["أَيْنَ مَحَطَّةُ الْقِطَارِ؟","مَتَى يَصِلُ الْقِطَارُ؟","كَمْ ثَمَنُ التَّذْكِرَةِ؟","هَلْ هَذَا مَقْعَدُكَ؟"],"correct":1,"accepted":[]},{"key":"e21f1cbf4a4a9390901ad9ae99b44aea","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مُحَاضَرَةٌ","explanation":"مُحَاضَرَةٌ = kuliah/ceramah ilmiah. Ujian = اِمْتِحَانٌ, perpustakaan = مَكْتَبَةٌ.","time":25,"options":["Kuliah (perkuliahan)","Ujian","Asrama","Perpustakaan"],"correct":1,"accepted":[]},{"key":"b72f7918609981ad0db6a6d855250fd0","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"كُلِّيَّةٌ","explanation":"كُلِّيَّةٌ = fakultas. Jurusan = قِسْمٌ, universitas = جَامِعَةٌ, kelas = فَصْلٌ.","time":25,"options":["Fakultas","Jurusan","Universitas","Kelas"],"correct":1,"accepted":[]},{"key":"9ca5f1469503017462cc623a4c81aceb","cat":"kampus","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَرْجِعٌ","explanation":"مَرْجِعٌ (jamak: مَرَاجِعُ) = referensi/rujukan. Ringkasan = مُلَخَّصٌ, daftar isi = فِهْرِسٌ, catatan kaki = هَامِشٌ.","time":30,"options":["Referensi (rujukan)","Ringkasan","Daftar isi","Catatan kaki"],"correct":1,"accepted":[]},{"key":"6a641860704e77b5d2ee29030e720fd8","cat":"kampus","type":"arabic_translation","level":"advanced","variety":"fusha","prompt":"Apa bahasa Arabnya \"pengumuman\"?","ar":null,"explanation":"إِعْلَانٌ = pengumuman. Kata lain berakar mirip: إِعْلَامٌ = media/pemberitahuan, اِسْتِعْلَامٌ = bagian informasi, تَعْلِيمٌ = pengajaran.","time":30,"options":["إِعْلَانٌ","إِعْلَامٌ","اِسْتِعْلَامٌ","تَعْلِيمٌ"],"correct":1,"accepted":[]},{"key":"d6328650020969695f28d1af4f9e45a4","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Temanmu berkata: السَّلَامُ عَلَيْكُمْ. Pilih respons yang paling tepat.","ar":"السَّلَامُ عَلَيْكُمْ","explanation":"Jawaban salam adalah وَعَلَيْكُمُ السَّلَامُ. مَعَ السَّلَامَةِ diucapkan saat berpisah.","time":20,"options":["وَعَلَيْكُمُ السَّلَامُ","صَبَاحَ النُّورِ","مَعَ السَّلَامَةِ","شُكْرًا"],"correct":1,"accepted":[]},{"key":"77f3287970d93a9bc162f0a693c2ee3b","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Ustadz menyapa: صَبَاحَ الْخَيْرِ. Pilih respons yang paling tepat.","ar":"صَبَاحَ الْخَيْرِ","explanation":"صَبَاحَ الْخَيْرِ (selamat pagi) dijawab صَبَاحَ النُّورِ. مَسَاءَ النُّورِ untuk sore/malam.","time":20,"options":["صَبَاحَ النُّورِ","مَسَاءَ النُّورِ","عَفْوًا","إِلَى اللِّقَاءِ"],"correct":1,"accepted":[]},{"key":"caa3a509df7c57d6f59ed9b8a60d932a","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Seseorang bertanya: مَا اسْمُكَ؟ Pilih respons yang paling tepat.","ar":"مَا اسْمُكَ؟","explanation":"مَا اسْمُكَ؟ = Siapa namamu? Jawabannya اِسْمِي ... (namaku ...).","time":20,"options":["اِسْمِي أَحْمَدُ.","أَنَا مِنْ إِنْدُونِيسِيَا.","عُمْرِي عِشْرُونَ سَنَةً.","أَنَا بِخَيْرٍ."],"correct":1,"accepted":[]},{"key":"b240efae126b427b6fd7f1267c342b22","cat":"salam","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Seseorang bertanya: مِنْ أَيْنَ أَنْتَ؟ Pilih respons yang paling tepat.","ar":"مِنْ أَيْنَ أَنْتَ؟","explanation":"مِنْ أَيْنَ أَنْتَ؟ = Dari mana asalmu? Jawabannya أَنَا مِنْ ... . \"أَسْكُنُ فِي الْقَاهِرَةِ\" menjawab tempat tinggal, bukan asal.","time":25,"options":["أَنَا مِنْ إِنْدُونِيسِيَا.","اِسْمِي أَحْمَدُ.","أَسْكُنُ فِي الْقَاهِرَةِ مُنْذُ سَنَةٍ.","أَنَا طَالِبٌ."],"correct":1,"accepted":[]},{"key":"18c7bff49eac7277aa224ed130c62c2d","cat":"salam","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Lengkapi ungkapan \"Apa kabarmu?\"","ar":"كَيْفَ ـــــ ؟","explanation":"كَيْفَ حَالُكَ؟ = Bagaimana keadaanmu/apa kabarmu? Untuk perempuan: كَيْفَ حَالُكِ؟","time":20,"options":["حَالُكَ","اسْمُكَ","بَيْتُكَ","عُمْرُكَ"],"correct":1,"accepted":[]},{"key":"e3c02297cd8767539bf9aa1143b66d79","cat":"pasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سُوقٌ","explanation":"سُوقٌ = pasar (jamak: أَسْوَاقٌ). Toko = دُكَّانٌ atau مَحَلٌّ, jalan = شَارِعٌ.","time":20,"options":["Pasar","Toko","Masjid","Jalan"],"correct":1,"accepted":[]},{"key":"0c95471b4a01e6b2d06e0fc82b2bb176","cat":"pasar","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Di pasar kamu mendengar: بِكَمْ هَذَا؟ Artinya …","ar":"بِكَمْ هَذَا؟","explanation":"بِكَمْ = dengan (harga) berapa. Di mana = أَيْنَ, apa = مَا, milik siapa = لِمَنْ.","time":20,"options":["Berapa harga ini?","Di mana ini?","Apa ini?","Milik siapa ini?"],"correct":1,"accepted":[]},{"key":"3428adcb8739b323957390c4741f41eb","cat":"pasar","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Di restoran kamu ingin meminta daftar menu. Kalimat yang tepat adalah …","ar":null,"explanation":"قَائِمَةُ الطَّعَامِ = daftar menu. أَنَا شَبْعَانُ = saya kenyang, الْحِسَابُ = tagihan, لَذِيذٌ = lezat.","time":25,"options":["مِنْ فَضْلِكَ، أَعْطِنِي قَائِمَةَ الطَّعَامِ.","أَنَا شَبْعَانُ.","الْحِسَابُ مِنْ فَضْلِكَ.","الطَّعَامُ لَذِيذٌ."],"correct":1,"accepted":[]},{"key":"62e7f2fcd32b6b02b923ff3440e7783c","cat":"ungkapan","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Ketika bersin, kita disunnahkan mengucapkan …","ar":"ـــــ لِلّٰهِ","explanation":"Sunnah ketika bersin adalah mengucapkan الْحَمْدُ لِلّٰهِ.","time":20,"options":["الْحَمْدُ","الشُّكْرُ","السَّلَامُ","الْعَفْوُ"],"correct":1,"accepted":[]},{"key":"1bada28c1112d68c5425c35d292b7e09","cat":"ungkapan","type":"complete_expression","level":"intermediate","variety":"fusha","prompt":"Temanmu bersin lalu mengucap الْحَمْدُ لِلّٰهِ. Kamu menjawab …","ar":"ـــــ اللّٰهُ","explanation":"Pendengar menjawab يَرْحَمُكَ اللّٰهُ. Lalu yang bersin membalas يَهْدِيكُمُ اللّٰهُ وَيُصْلِحُ بَالَكُمْ.","time":25,"options":["يَرْحَمُكَ","يَهْدِيكُمُ","يَحْفَظُكَ","يُبَارِكُ"],"correct":1,"accepted":[]},{"key":"962aa7cf0389d9e736a0490525dad380","cat":"ungkapan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti ungkapan berikut ketika menjawab شُكْرًا?","ar":"عَفْوًا","explanation":"عَفْوًا sebagai jawaban شُكْرًا berarti \"sama-sama\". Dalam konteks lain ia juga berarti \"maaf/permisi\".","time":20,"options":["Sama-sama","Terima kasih","Selamat tinggal","Silakan masuk"],"correct":1,"accepted":[]},{"key":"c7ee800c530103b491dd1b77c6fcc3be","cat":"ungkapan","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? إِنْ شَاءَ اللّٰهُ diucapkan untuk sesuatu yang sudah terjadi.","ar":"إِنْ شَاءَ اللّٰهُ","explanation":"Salah. إِنْ شَاءَ اللّٰهُ diucapkan untuk rencana di masa depan. Untuk kekaguman atas sesuatu yang ada diucapkan مَا شَاءَ اللّٰهُ.","time":25,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"8d86629ff8deb777d53a707d83471cfd","cat":"fusha","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"هَلْ تَتَكَلَّمُ اللُّغَةَ الْعَرَبِيَّةَ؟","explanation":"Pertanyaan: \"Apakah kamu berbicara bahasa Arab?\" Jawaban yang sesuai: \"Ya, saya berbicara sedikit.\" (أَتَكَلَّمُهَا = saya berbicara dengannya).","time":25,"options":["نَعَمْ، أَتَكَلَّمُهَا قَلِيلًا.","نَعَمْ، أَنَا طَالِبٌ.","لَا، أَنَا جَائِعٌ.","نَعَمْ، الْكِتَابُ جَدِيدٌ."],"correct":1,"accepted":[]},{"key":"80db5d09499c279b3f6c49da1b55f385","cat":"fusha","type":"daily_conversation","level":"advanced","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"مَاذَا تَدْرُسُ فِي الْجَامِعَةِ؟","explanation":"Pertanyaan: \"Apa yang kamu pelajari di universitas?\" Jawaban yang tepat menyebut bidang studi. دَرَسْتُ أَمْسِ menjawab waktu belajar (fi'il madhi), bukan bidang studi.","time":30,"options":["أَدْرُسُ فِي كُلِّيَّةِ أُصُولِ الدِّينِ.","أَسْكُنُ قَرِيبًا مِنَ الْجَامِعَةِ.","دَرَسْتُ أَمْسِ مَعَ صَدِيقِي.","الْجَامِعَةُ كَبِيرَةٌ جِدًّا."],"correct":1,"accepted":[]},{"key":"c52ff9405efa85e18ae40b500bbf231f","cat":"fusha","type":"sentence_builder","level":"advanced","variety":"fusha","prompt":"Susun menjadi jumlah fi'liyyah (diawali fi'il): \"Mahasiswa itu telah membaca buku di perpustakaan.\"","ar":null,"explanation":"Urutan dasar jumlah fi'liyyah: fi'il (قَرَأَ) – fa'il marfu' (الطَّالِبُ) – maf'ul bih manshub (الْكِتَابَ) – keterangan tempat (فِي الْمَكْتَبَةِ).","time":45,"options":["قَرَأَ","الطَّالِبُ","الْكِتَابَ","فِي","الْمَكْتَبَةِ"],"correct":null,"accepted":["قَرَأَ الطَّالِبُ الْكِتَابَ فِي الْمَكْتَبَةِ","قَرَأَ الطَّالِبُ فِي الْمَكْتَبَةِ الْكِتَابَ"]},{"key":"1f3781372b8ee6a5e2a49e00c5668b38","cat":"fusha","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu terlambat masuk kelas. Kalimat yang sopan kepada ustadz adalah …","ar":null,"explanation":"تَأَخَّرْتُ = saya terlambat; diawali عَفْوًا (maaf). Pilihan lain: \"Di mana ustadz?\", \"Saya terburu-buru.\", \"Sampai jumpa, ustadz.\"","time":25,"options":["عَفْوًا يَا أُسْتَاذُ، تَأَخَّرْتُ.","أَيْنَ الْأُسْتَاذُ؟","أَنَا مُسْتَعْجِلٌ.","إِلَى اللِّقَاءِ يَا أُسْتَاذُ."],"correct":1,"accepted":[]},{"key":"64473d48ed931632518fb6fee8d48086","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"إِزَّيَّك؟","explanation":"إِزَّيَّك = apa kabar? (Fusha: كَيْفَ حَالُكَ؟). Untuk perempuan diucapkan إِزَّيِّك.","time":20,"options":["Apa kabar?","Di mana kamu?","Siapa namamu?","Mau ke mana?"],"correct":1,"accepted":[]},{"key":"b7867cbb067f5f8eae83b57795d759b8","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"عَايِز","explanation":"عَايِز (laki-laki) / عَايْزَة (perempuan) = mau/ingin. Padanan Fusha: أُرِيدُ.","time":20,"options":["Mau / ingin","Tahu","Bisa","Punya"],"correct":1,"accepted":[]},{"key":"652bdfbdf3edf2300a9c375cb48809a1","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa padanan Fusha dari kata Amiyah ini?","ar":"دِلْوَقْتِي","explanation":"دِلْوَقْتِي = sekarang, padanan Fusha الْآنَ. غَدًا = besok, أَمْسِ = kemarin, بَعْدَ قَلِيلٍ = sebentar lagi.","time":25,"options":["الْآنَ","غَدًا","أَمْسِ","بَعْدَ قَلِيلٍ"],"correct":1,"accepted":[]},{"key":"389ea93aba12de05508a53f8c22a96d4","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"مِشْ عَارِف","explanation":"مِشْ = tidak (negasi Amiyah), عَارِف = tahu. Padanan Fusha: لَا أَعْرِفُ.","time":25,"options":["Saya tidak tahu","Saya tidak mau","Saya belum makan","Saya tidak bisa"],"correct":1,"accepted":[]},{"key":"fe11478d0cafb7d587d69bbad0f4c731","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Sopir taksi di Kairo bertanya kepadamu. Maksudnya …","ar":"رَايِح فِين؟","explanation":"رَايِح = pergi/menuju (Fusha: ذَاهِبٌ), فِين = di mana/ke mana (Fusha: أَيْنَ). Jadi: إِلَى أَيْنَ أَنْتَ ذَاهِبٌ؟","time":30,"options":["Mau ke mana?","Dari mana?","Kapan berangkat?","Berapa orang?"],"correct":1,"accepted":[]},{"key":"5d6d2b09d16ccf0f088a032f5135f849","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Ungkapan Amiyah Mesir ini biasanya dipakai untuk …","ar":"مَعْلِش","explanation":"مَعْلِش (dari مَا عَلَيْهِ شَيْءٌ) = tidak apa-apa / maaf ya. Sangat sering dipakai di Mesir.","time":30,"options":["Menenangkan/memaafkan: \"tidak apa-apa\"","Menolak dengan tegas","Memuji makanan","Memanggil pelayan"],"correct":1,"accepted":[]},{"key":"99b138147a909bf6e2342a1e87b55267","cat":"mubtada-khabar","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"[[الْكِتَابُ]] جَدِيدٌ","explanation":"الْكِتَابُ adalah mubtada': isim marfu' di awal jumlah ismiyyah yang menjadi pokok pembicaraan. Tanda rafa'-nya dhammah. جَدِيدٌ adalah khabarnya.","time":20,"options":["Mubtada' marfu' dengan dhammah","Khabar marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"544ebaf6af8db2e60b2f92ba1605b8b5","cat":"mubtada-khabar","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"الْمَسْجِدُ [[كَبِيرٌ]]","explanation":"كَبِيرٌ adalah khabar: bagian yang menyempurnakan makna mubtada' الْمَسْجِدُ. Khabar selalu marfu', tandanya dhammah (tanwin).","time":20,"options":["Khabar marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Na'at marfu' dengan dhammah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"1321ecb9d91e4f961d28c181bec30bdd","cat":"mubtada-khabar","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"فِي الْفَصْلِ [[طُلَّابٌ]]","explanation":"طُلَّابٌ adalah mubtada' muakhkhar (diakhirkan). Karena mubtada'-nya nakirah dan khabarnya syibhu jumlah (فِي الْفَصْلِ), khabar wajib didahulukan (khabar muqaddam).","time":25,"options":["Mubtada' muakhkhar marfu' dengan dhammah","Khabar marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Na'at marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"1bcd03585008a42a9bbab1ef4839f4fa","cat":"mubtada-khabar","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Khabar pada kalimat berikut berbentuk …","ar":"الطَّالِبُ يَقْرَأُ الْقُرْآنَ","explanation":"Khabar dari الطَّالِبُ adalah يَقْرَأُ الْقُرْآنَ, yaitu jumlah fi'liyyah (fi'il + fa'il dhamir mustatir + maf'ul bih). Jumlah ini berkedudukan rafa' sebagai khabar (fi mahalli raf'in).","time":30,"options":["Jumlah fi'liyyah","Mufrad","Syibhu jumlah","Jumlah ismiyyah"],"correct":1,"accepted":[]},{"key":"fb2c9d9413630e8991c786c3619e7271","cat":"fail","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ [[الْمُدَرِّسُ]]","explanation":"الْمُدَرِّسُ adalah fa'il: isim marfu' setelah fi'il ma'lum yang menunjukkan pelaku. Tanda rafa'-nya dhammah.","time":20,"options":["Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Maf'ul bih manshub dengan fathah","Khabar marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"8c74e0ea2272893c99aad89613d768ce","cat":"fail","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"نَجَحَ [[الْمُهَنْدِسُونَ]]","explanation":"الْمُهَنْدِسُونَ adalah fa'il. Jamak mudzakkar salim di-rafa'-kan dengan wawu sebagai pengganti dhammah (tanda i'rab far'i).","time":25,"options":["Fa'il marfu' dengan wawu karena jamak mudzakkar salim","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan wawu","Fa'il manshub dengan ya'"],"correct":1,"accepted":[]},{"key":"621827d6085e8370f588d5eb7b711edb","cat":"fail","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH?","ar":null,"explanation":"Jika fa'il-nya muannats haqiqi (perempuan sungguhan) dan langsung setelah fi'il, fi'il wajib diberi ta' ta'nits: قَامَتْ فَاطِمَةُ. Maka قَامَ فَاطِمَةُ salah.","time":25,"options":["قَامَ فَاطِمَةُ","قَامَتْ فَاطِمَةُ","جَلَسَ الطُّلَّابُ","نَجَحَ مُحَمَّدٌ"],"correct":1,"accepted":[]},{"key":"428f94918b3badbf82006780d88d9ba9","cat":"maful-bih","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"كَتَبَ الطَّالِبُ [[الدَّرْسَ]]","explanation":"الدَّرْسَ adalah maf'ul bih: isim manshub yang dikenai pekerjaan. Tanda nashab-nya fathah.","time":20,"options":["Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan dhammah","Mudhaf ilaih majrur dengan kasrah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"f7922d6f8871c3843c6446ed4f5d56a9","cat":"maful-bih","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"رَأَيْتُ [[الْمُعَلِّمِينَ]]","explanation":"الْمُعَلِّمِينَ adalah maf'ul bih. Jamak mudzakkar salim di-nashab-kan dengan ya' sebagai pengganti fathah.","time":25,"options":["Maf'ul bih manshub dengan ya' karena jamak mudzakkar salim","Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan wawu","Isim majrur dengan ya'"],"correct":1,"accepted":[]},{"key":"b2a305e5869407dc7ec5f476617cf28e","cat":"maful-bih","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"شَاهَدْتُ [[الطَّالِبَاتِ]]","explanation":"الطَّالِبَاتِ adalah maf'ul bih. Jamak muannats salim di-nashab-kan dengan kasrah sebagai pengganti fathah. Jadi kasrah di sini bukan tanda jarr.","time":25,"options":["Maf'ul bih manshub dengan kasrah karena jamak muannats salim","Maf'ul bih manshub dengan fathah","Isim majrur dengan kasrah","Mudhaf ilaih majrur dengan kasrah"],"correct":1,"accepted":[]},{"key":"75807726fefc7a1c70bbde06b6a49c53","cat":"maful-bih","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"قَرَأَ [[الْقُرْآنَ]] أَحْمَدُ","explanation":"الْقُرْآنَ tetap maf'ul bih meskipun disebut sebelum fa'il أَحْمَدُ (maf'ul bih muqaddam). Tandanya fathah. أَحْمَدُ adalah fa'il marfu' (mamnu' min ash-sharf, tanpa tanwin).","time":30,"options":["Maf'ul bih manshub dengan fathah (didahulukan dari fa'il)","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"b0a11607e762151721b7a7b84aabe0ab","cat":"naat","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"هَذَا بَيْتٌ [[جَمِيلٌ]]","explanation":"جَمِيلٌ adalah na'at (sifat) bagi بَيْتٌ. Na'at mengikuti man'ut-nya dalam i'rab: بَيْتٌ marfu' (khabar), maka جَمِيلٌ juga marfu'.","time":20,"options":["Na'at marfu' dengan dhammah, mengikuti man'ut-nya","Khabar marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"6b79054ceb0a5a02fabc24fd26d32e03","cat":"naat","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih na'at yang tepat untuk melengkapi kalimat.","ar":"رَأَيْتُ بِنْتًا ـــــ","explanation":"Na'at mengikuti man'ut dalam i'rab (manshub), jenis (muannats), dan nakirah/ma'rifah. بِنْتًا manshub, muannats, nakirah, maka na'at-nya صَغِيرَةً.","time":25,"options":["صَغِيرَةً","صَغِيرٌ","صَغِيرَةٌ","الصَّغِيرَةَ"],"correct":1,"accepted":[]},{"key":"de3ad6c5697e54cd24bd13c0be74c91c","cat":"naat","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"مَرَرْتُ بِالطُّلَّابِ [[الْمُجْتَهِدِينَ]]","explanation":"الْمُجْتَهِدِينَ adalah na'at bagi الطُّلَّابِ yang majrur oleh بِـ. Na'at ikut majrur; karena berbentuk jamak mudzakkar salim, tanda jarr-nya ya'. Bukan hal, karena hal harus nakirah.","time":30,"options":["Na'at majrur dengan ya' karena jamak mudzakkar salim","Na'at majrur dengan kasrah","Maf'ul bih manshub dengan ya'","Hal manshub dengan ya'"],"correct":1,"accepted":[]},{"key":"0a1f1c2b213ea8ed8bba6ad575da53b2","cat":"idhafah","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"هَذَا كِتَابُ [[الطَّالِبِ]]","explanation":"الطَّالِبِ adalah mudhaf ilaih. Mudhaf ilaih selalu majrur; tandanya kasrah. كِتَابُ adalah mudhaf (tanpa ال dan tanpa tanwin).","time":20,"options":["Mudhaf ilaih majrur dengan kasrah","Na'at majrur dengan kasrah","Isim majrur oleh huruf jar","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"a26f984e03ef9badd78c8441bf960f4b","cat":"idhafah","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH?","ar":null,"explanation":"Dalam idhafah, mudhaf tidak boleh diberi ال dan tidak bertanwin. Yang benar: هَذَا كِتَابُ الطَّالِبِ.","time":25,"options":["هَذَا الْكِتَابُ الطَّالِبِ","هَذَا كِتَابُ الطَّالِبِ","هَذَا كِتَابٌ جَدِيدٌ","هَذَا بَابُ الْفَصْلِ"],"correct":1,"accepted":[]},{"key":"7117b3c655b965b81176301467bc93a5","cat":"idhafah","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ [[مُعَلِّمُو]] الْمَدْرَسَةِ","explanation":"مُعَلِّمُو asalnya مُعَلِّمُونَ (jamak mudzakkar salim), fa'il marfu' dengan wawu. Nun-nya dibuang karena menjadi mudhaf bagi الْمَدْرَسَةِ.","time":30,"options":["Fa'il marfu' dengan wawu; nun jamak dibuang karena idhafah","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan wawu","Mudhaf ilaih majrur"],"correct":1,"accepted":[]},{"key":"c3730b3620f6f3188d35b7e37f0175da","cat":"hal","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ الطَّالِبُ [[مُبْتَسِمًا]]","explanation":"مُبْتَسِمًا adalah hal: isim nakirah manshub yang menjelaskan keadaan shahibul hal (الطَّالِبُ) saat terjadinya pekerjaan.","time":25,"options":["Hal manshub dengan fathah","Maf'ul bih manshub dengan fathah","Na'at manshub dengan fathah","Tamyiz manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"68739e7ee819dfba1af32b82c6c45aad","cat":"hal","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih hal yang tepat untuk melengkapi kalimat.","ar":"رَجَعَ الْجُنُودُ ـــــ","explanation":"Hal harus nakirah dan manshub, serta sesuai dengan shahibul hal. الْجُنُودُ jamak, maka hal-nya jamak mudzakkar salim manshub dengan ya': مُنْتَصِرِينَ.","time":30,"options":["مُنْتَصِرِينَ","مُنْتَصِرُونَ","الْمُنْتَصِرِينَ","مُنْتَصِرًا"],"correct":1,"accepted":[]},{"key":"3adfd49d62ef201e747882acbca6564b","cat":"tamyiz","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"اِشْتَرَيْتُ عِشْرِينَ [[كِتَابًا]]","explanation":"كِتَابًا adalah tamyiz bilangan (tamyiz 'adad): menjelaskan apa yang dihitung. Tamyiz bilangan 11–99 berupa isim mufrad manshub.","time":25,"options":["Tamyiz manshub dengan fathah","Maf'ul bih manshub dengan fathah","Hal manshub dengan fathah","Mudhaf ilaih majrur"],"correct":1,"accepted":[]},{"key":"455ea25213731e28de0aee36ae658bd1","cat":"tamyiz","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih tamyiz yang tepat untuk melengkapi kalimat.","ar":"عِنْدِي ثَلَاثَةُ ـــــ","explanation":"Tamyiz bilangan 3–10 berupa isim jamak yang majrur sebagai mudhaf ilaih: ثَلَاثَةُ كُتُبٍ.","time":30,"options":["كُتُبٍ","كُتُبًا","كِتَابٍ","كِتَابًا"],"correct":1,"accepted":[]},{"key":"ce9a158472200f0a9a7490ff90d4bba0","cat":"nawasikh","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"كَانَ الْجَوُّ [[بَارِدًا]]","explanation":"كَانَ me-rafa'-kan isimnya (الْجَوُّ) dan me-nashab-kan khabarnya. بَارِدًا adalah khabar kana, manshub dengan fathah.","time":25,"options":["Khabar kana manshub dengan fathah","Isim kana marfu' dengan dhammah","Hal manshub dengan fathah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"d0fcaa6cb672e1c03223ed193853abaa","cat":"nawasikh","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"إِنَّ [[اللّٰهَ]] غَفُورٌ","explanation":"إِنَّ me-nashab-kan isimnya dan me-rafa'-kan khabarnya (kebalikan dari كَانَ). اللّٰهَ adalah isim inna, manshub dengan fathah; غَفُورٌ khabar inna.","time":25,"options":["Isim inna manshub dengan fathah","Khabar inna marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"7d5cbd4e604c859c27f42d75b357247c","cat":"nawasikh","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"إِنَّ الطُّلَّابَ ـــــ","explanation":"Kata yang kosong adalah khabar inna, maka marfu'. Karena jamak mudzakkar salim, tanda rafa'-nya wawu: مُجْتَهِدُونَ.","time":30,"options":["مُجْتَهِدُونَ","مُجْتَهِدِينَ","مُجْتَهِدًا","مُجْتَهِدُوا"],"correct":1,"accepted":[]},{"key":"b3f5ce3b7e40ebd4c644db6b83bf1115","cat":"majrurat","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"ذَهَبْتُ إِلَى [[الْمَسْجِدِ]]","explanation":"الْمَسْجِدِ didahului huruf jar إِلَى, maka majrur dengan kasrah.","time":20,"options":["Isim majrur oleh huruf jar dengan kasrah","Mudhaf ilaih majrur dengan kasrah","Maf'ul bih manshub dengan fathah","Na'at majrur dengan kasrah"],"correct":1,"accepted":[]},{"key":"8f809ba971e779db69d11a77a91473cc","cat":"majrurat","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"صَلَّيْتُ فِي [[مَسَاجِدَ]] كَثِيرَةٍ","explanation":"مَسَاجِدَ majrur oleh فِي, tetapi tandanya fathah karena isim ghairu munsharif (shighat muntahal jumu': wazan مَفَاعِلُ) yang tidak ber-ال dan tidak di-idhafah-kan.","time":30,"options":["Isim majrur dengan fathah karena mamnu' min ash-sharf","Isim majrur dengan kasrah","Maf'ul bih manshub dengan fathah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"f199aeb3de77239976fdf0bc3230c146","cat":"tawabi","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ مُحَمَّدٌ وَ[[عَلِيٌّ]]","explanation":"عَلِيٌّ di-'athaf-kan (disambung) kepada مُحَمَّدٌ dengan huruf وَ. Ma'thuf mengikuti ma'thuf 'alaih dalam i'rab, maka marfu'.","time":25,"options":["Ma'thuf marfu' dengan dhammah, mengikuti مُحَمَّدٌ","Badal marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Khabar marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"fa027be6a70c8c47752b0586283ca692","cat":"tawabi","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ الطُّلَّابُ [[كُلُّهُمْ]]","explanation":"كُلُّ yang bersambung dengan dhamir kembali ke kata sebelumnya adalah taukid ma'nawi. Ia mengikuti الطُّلَّابُ (fa'il) sehingga marfu'.","time":30,"options":["Taukid ma'nawi marfu' dengan dhammah","Na'at marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"ccc7c35fd4913309b85e48448a9f8d89","cat":"anwa-jumal","type":"sentence_analysis","level":"beginner","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"الْعِلْمُ نُورٌ","explanation":"Diawali isim (الْعِلْمُ) sebagai mubtada' dan diikuti khabar, maka jumlah ismiyyah.","time":20,"options":["Jumlah ismiyyah","Jumlah fi'liyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"02708f8a8af58614143e86dcae072722","cat":"anwa-jumal","type":"sentence_analysis","level":"beginner","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"يَدْرُسُ الطَّالِبُ","explanation":"Diawali fi'il (يَدْرُسُ) lalu fa'il (الطَّالِبُ), maka jumlah fi'liyyah.","time":20,"options":["Jumlah fi'liyyah","Jumlah ismiyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"b8766b2b83210e8e7c86b8f461982b0e","cat":"anwa-jumal","type":"identify_word","level":"beginner","variety":"fusha","prompt":"Kata yang ditandai termasuk jenis kalimah apa?","ar":"[[فِي]] الْبَيْتِ","explanation":"فِي adalah huruf (huruf jar): tidak bermakna sempurna kecuali bersama kata lain, dan tidak menerima tanda isim maupun fi'il.","time":20,"options":["Huruf","Isim","Fi'il"],"correct":1,"accepted":[]},{"key":"511c30305c98e54c21aaa6ac3637e257","cat":"anwa-jumal","type":"identify_word","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk jenis kalimah apa?","ar":"الْمَدْرَسَةُ","explanation":"الْمَدْرَسَةُ adalah isim. Tandanya: menerima ال dan bisa bertanwin.","time":20,"options":["Isim","Fi'il","Huruf"],"correct":1,"accepted":[]},{"key":"3a8fab8977ce453d698704e36aefcde0","cat":"anwa-jumal","type":"identify_word","level":"advanced","variety":"fusha","prompt":"Kata ini termasuk jenis kalimah apa?","ar":"لَيْسَ","explanation":"لَيْسَ adalah fi'il madhi jamid (tidak bisa di-tashrif penuh). Buktinya ia menerima ta' fa'il: لَسْتُ، لَسْنَا.","time":30,"options":["Fi'il","Huruf","Isim"],"correct":1,"accepted":[]},{"key":"44291d626e88867db39635eab9b55776","cat":"anwa-jumal","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi jumlah ismiyyah yang diawali mubtada': \"Guru itu berada di kelas.\"","ar":null,"explanation":"Mubtada' (الْمُدَرِّسُ) di awal, lalu khabar berupa syibhu jumlah (jar-majrur) فِي الْفَصْلِ.","time":45,"options":["الْمُدَرِّسُ","فِي","الْفَصْلِ"],"correct":null,"accepted":["الْمُدَرِّسُ فِي الْفَصْلِ"]},{"key":"c3ecbd699ca956188c5e9155ae1dd5d4","cat":"madhi","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk fi'il apa?","ar":"كَتَبَ","explanation":"كَتَبَ adalah fi'il madhi (lampau): tiga huruf dengan harakat fathah di akhir, tanpa huruf mudhara'ah.","time":20,"options":["Fi'il madhi","Fi'il mudhari'","Fi'il amr"],"correct":1,"accepted":[]},{"key":"5cd683b39ec3af964b72682540132b0e","cat":"madhi","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Ubah كَتَبَ untuk dhamir هُمْ (mereka laki-laki).","ar":null,"explanation":"Untuk هُمْ ditambahkan wawu jama'ah (dan alif fariqah): كَتَبُوا. كَتَبْنَ untuk هُنَّ, كَتَبْتُمْ untuk أَنْتُمْ, كَتَبَا untuk هُمَا.","time":25,"options":["كَتَبُوا","كَتَبْنَ","كَتَبْتُمْ","كَتَبَا"],"correct":1,"accepted":[]},{"key":"d89d89f5f9a6f4d1c3890b3a9885148b","cat":"madhi","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Ubah كَتَبَ untuk dhamir أَنْتِ (kamu perempuan).","ar":null,"explanation":"أَنْتِ → ta' fa'il berharakat kasrah: كَتَبْتِ. كَتَبْتَ untuk أَنْتَ, كَتَبَتْ untuk هِيَ, كَتَبْتُ untuk أَنَا.","time":25,"options":["كَتَبْتِ","كَتَبْتَ","كَتَبَتْ","كَتَبْتُ"],"correct":1,"accepted":[]},{"key":"8c6805487beb1707a52477174d43c29f","cat":"madhi","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Ubah قَالَ untuk dhamir أَنَا.","ar":null,"explanation":"قَالَ asalnya قَوَلَ (ajwaf wawi). Saat bertemu ta' fa'il yang membuat lam fi'il sukun, alif dibuang (iltiqa' sakinain) dan fa' fi'il didhammah sebagai tanda asal wawu: قُلْتُ.","time":30,"options":["قُلْتُ","قَالْتُ","قِلْتُ","قَوَلْتُ"],"correct":1,"accepted":[]},{"key":"bb323c9af8e049eaf8115d7e196431e9","cat":"mudhari","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa fi'il mudhari' dari كَتَبَ untuk dhamir هُوَ?","ar":null,"explanation":"كَتَبَ – يَكْتُبُ (bab نَصَرَ – يَنْصُرُ: 'ain mudhari' berharakat dhammah). Untuk هُوَ huruf mudhara'ah-nya يَـ.","time":20,"options":["يَكْتُبُ","يَكْتِبُ","يَكْتَبُ","تَكْتُبُ"],"correct":1,"accepted":[]},{"key":"4e33127818c09b12cad74761458a1793","cat":"mudhari","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il mudhari' dari ذَهَبَ untuk dhamir هُنَّ?","ar":null,"explanation":"هُنَّ → يَذْهَبْنَ (nun niswah). يَذْهَبُونَ untuk هُمْ, تَذْهَبْنَ untuk أَنْتُنَّ, يَذْهَبَانِ untuk هُمَا.","time":25,"options":["يَذْهَبْنَ","يَذْهَبُونَ","تَذْهَبْنَ","يَذْهَبَانِ"],"correct":1,"accepted":[]},{"key":"91280b27db508414c5c1df895dc6b7c7","cat":"mudhari","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il mudhari' dari أَكْرَمَ untuk dhamir هُوَ?","ar":null,"explanation":"أَكْرَمَ berwazan أَفْعَلَ, mudhari'-nya يُفْعِلُ: يُكْرِمُ. Huruf mudhara'ah fi'il ruba'i didhammah dan hamzah أَفْعَلَ dibuang.","time":30,"options":["يُكْرِمُ","يَكْرُمُ","يُكَرِّمُ","يَتَكَرَّمُ"],"correct":1,"accepted":[]},{"key":"8f497476bbd0c959e85ae370a0dd7049","cat":"amr","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa fi'il amr dari يَكْتُبُ (untuk أَنْتَ)?","ar":null,"explanation":"Buang huruf mudhara'ah dan sukunkan akhirnya: كْتُبْ. Karena huruf pertama sukun, ditambah hamzah washl; hamzahnya didhammah karena 'ain fi'il-nya dhammah: اُكْتُبْ.","time":20,"options":["اُكْتُبْ","اِكْتِبْ","كْتُبْ","تَكْتُبْ"],"correct":1,"accepted":[]},{"key":"8951a35121d0970907d39f5927b6e1c4","cat":"amr","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il amr dari يَجْلِسُ untuk dhamir أَنْتُمْ?","ar":null,"explanation":"Amr untuk أَنْتُمْ: اِجْلِسُوا. Hamzah washl dikasrah karena 'ain fi'il-nya kasrah; nun dibuang seperti pada af'al khamsah yang majzum.","time":25,"options":["اِجْلِسُوا","اُجْلُسُوا","اِجْلِسُونَ","تَجْلِسُوا"],"correct":1,"accepted":[]},{"key":"928a4686f5055e40709473aa485f1c81","cat":"amr","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il amr dari يَقُومُ (untuk أَنْتَ)?","ar":null,"explanation":"Buang huruf mudhara'ah: قُومُ → disukunkan menjadi قُومْ. Terjadi iltiqa' sakinain (wawu dan mim), maka wawu dibuang: قُمْ. Tidak perlu hamzah washl karena huruf pertama berharakat.","time":30,"options":["قُمْ","قُومْ","اُقُمْ","قَامْ"],"correct":1,"accepted":[]},{"key":"5757eb51c32804812f3a2c9b48064299","cat":"mashdar","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa mashdar dari عَلَّمَ?","ar":null,"explanation":"عَلَّمَ berwazan فَعَّلَ, mashdarnya تَفْعِيلٌ: تَعْلِيمٌ. عِلْمٌ mashdar عَلِمَ, إِعْلَامٌ mashdar أَعْلَمَ, تَعَلُّمٌ mashdar تَعَلَّمَ.","time":25,"options":["تَعْلِيمٌ","عِلْمٌ","إِعْلَامٌ","تَعَلُّمٌ"],"correct":1,"accepted":[]},{"key":"fa49f9eb6e19b791d6c13dbd88dd5001","cat":"mashdar","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa mashdar dari اِسْتَغْفَرَ?","ar":null,"explanation":"اِسْتَغْفَرَ berwazan اِسْتَفْعَلَ, mashdarnya اِسْتِفْعَالٌ: اِسْتِغْفَارٌ (ta' berharakat kasrah). مُسْتَغْفِرٌ adalah isim fa'il.","time":30,"options":["اِسْتِغْفَارٌ","اِسْتَغْفَارٌ","مُسْتَغْفِرٌ","غُفْرَانٌ"],"correct":1,"accepted":[]},{"key":"8636fcd2cd59fbcf05c55c1f19603298","cat":"isim-fail","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim fa'il dari كَتَبَ?","ar":null,"explanation":"Isim fa'il fi'il tsulatsi berwazan فَاعِلٌ: كَاتِبٌ (penulis). مَكْتُوبٌ isim maf'ul, مَكْتَبٌ isim makan.","time":20,"options":["كَاتِبٌ","مَكْتُوبٌ","كِتَابٌ","مَكْتَبٌ"],"correct":1,"accepted":[]},{"key":"654f7f2ae436ef523a4e521e8575716b","cat":"isim-fail","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa isim fa'il dari اِجْتَهَدَ?","ar":null,"explanation":"Isim fa'il dari fi'il lebih dari tiga huruf: ganti huruf mudhara'ah (يَجْتَهِدُ) dengan mim berdhammah dan kasrahkan huruf sebelum akhir: مُجْتَهِدٌ. Jika difathah (مُجْتَهَدٌ) menjadi isim maf'ul.","time":25,"options":["مُجْتَهِدٌ","مُجْتَهَدٌ","جَاهِدٌ","اِجْتِهَادٌ"],"correct":1,"accepted":[]},{"key":"b03eec4b06ba0f1881669adf1b2c235d","cat":"isim-maful","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim maf'ul dari كَتَبَ?","ar":null,"explanation":"Isim maf'ul fi'il tsulatsi berwazan مَفْعُولٌ: مَكْتُوبٌ (yang ditulis).","time":20,"options":["مَكْتُوبٌ","كَاتِبٌ","مَكْتَبٌ","كِتَابَةٌ"],"correct":1,"accepted":[]},{"key":"bd4b705aaf34dd5bc9cfeb52b108b65e","cat":"isim-maful","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa isim maf'ul dari أَرْسَلَ?","ar":null,"explanation":"Dari mudhari' يُرْسِلُ: ganti huruf mudhara'ah dengan mim berdhammah dan fathahkan huruf sebelum akhir: مُرْسَلٌ (yang diutus). مُرْسِلٌ isim fa'il, إِرْسَالٌ mashdar.","time":30,"options":["مُرْسَلٌ","مُرْسِلٌ","إِرْسَالٌ","رَسُولٌ"],"correct":1,"accepted":[]},{"key":"3fab3251dc05b65b652724758f4af3d0","cat":"tashrif","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa bentuk fi'il madhi majhul dari كَتَبَ?","ar":null,"explanation":"Madhi majhul: huruf pertama didhammah dan huruf sebelum akhir dikasrah: كُتِبَ (telah ditulis). يُكْتَبُ adalah mudhari' majhul.","time":30,"options":["كُتِبَ","كَتِبَ","كُتُبَ","يُكْتَبُ"],"correct":1,"accepted":[]},{"key":"775e9471ed7205ca7ebd643def5b502f","cat":"tashrif","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa bentuk fi'il mudhari' majhul dari نَصَرَ untuk dhamir هُوَ?","ar":null,"explanation":"Mudhari' majhul: huruf mudhara'ah didhammah dan huruf sebelum akhir difathah: يُنْصَرُ (ditolong). يَنْصُرُ adalah bentuk ma'lum.","time":25,"options":["يُنْصَرُ","يَنْصُرُ","نُصِرَ","يُنْصِرُ"],"correct":1,"accepted":[]},{"key":"d5cfb472a45eaae614839ea215bc0e4c","cat":"mizan","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"كَاتِبٌ","explanation":"Huruf asli ك–ت–ب ditimbang dengan ف–ع–ل; alif tambahan setelah huruf pertama tetap ditulis: فَاعِلٌ.","time":20,"options":["فَاعِلٌ","فَعِيلٌ","مَفْعُولٌ","فِعَالٌ"],"correct":1,"accepted":[]},{"key":"b3ed97f6578bd5006c00423598f68ab4","cat":"mizan","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"اِسْتَخْرَجَ","explanation":"Huruf aslinya خ–ر–ج; tambahan اِسْتَـ di depan tetap ditulis: اِسْتَفْعَلَ.","time":25,"options":["اِسْتَفْعَلَ","اِفْتَعَلَ","اِنْفَعَلَ","تَفَاعَلَ"],"correct":1,"accepted":[]},{"key":"db84c05f4886bade80386b2833a7358b","cat":"mizan","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"قَالَ","explanation":"قَالَ asalnya قَوَلَ (alif adalah wawu yang berubah, bukan huruf tambahan). Mizan mengikuti huruf asli: فَعَلَ.","time":30,"options":["فَعَلَ","فَاعَلَ","فَالَ","فَعَّلَ"],"correct":1,"accepted":[]},{"key":"3b5961fde5a1ba93fafa023a52738bd8","cat":"mujarrad-mazid","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Apa huruf asli (akar kata) dari kata berikut?","ar":"مَدْرَسَةٌ","explanation":"مَدْرَسَةٌ berasal dari دَرَسَ (belajar). Mim di awal dan ta' marbuthah di akhir adalah huruf tambahan (isim makan berwazan مَفْعَلَةٌ).","time":20,"options":["د – ر – س","م – د – ر","ر – س – ة","م – د – س"],"correct":1,"accepted":[]},{"key":"c4c6c3fda03647256393b1151fe75b62","cat":"mujarrad-mazid","type":"fiil_challenge","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk …","ar":"تَعَلَّمَ","explanation":"تَعَلَّمَ berwazan تَفَعَّلَ: akar ع–ل–م ditambah dua huruf (ta' di awal dan pengulangan lam/tasydid).","time":25,"options":["Tsulatsi mazid dua huruf","Tsulatsi mujarrad","Tsulatsi mazid satu huruf","Ruba'i mujarrad"],"correct":1,"accepted":[]},{"key":"c00209a127545e070c9bbd5d80ca1e79","cat":"shahih-mutal","type":"fiil_challenge","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk jenis …","ar":"وَعَدَ","explanation":"Mitsal: fi'il yang huruf pertamanya (fa' fi'il) huruf illat. وَعَدَ diawali wawu.","time":25,"options":["Mu'tal mitsal","Mu'tal ajwaf","Mu'tal naqish","Shahih salim"],"correct":1,"accepted":[]},{"key":"bc89b4cfb32f8c71e24b4e1f9bafe48e","cat":"shahih-mutal","type":"fiil_challenge","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk jenis …","ar":"رَمَى","explanation":"Naqish: fi'il yang huruf terakhirnya (lam fi'il) huruf illat. رَمَى asalnya رَمَيَ (akhiran ya').","time":25,"options":["Mu'tal naqish","Mu'tal mitsal","Mu'tal ajwaf","Shahih mudha'af"],"correct":1,"accepted":[]},{"key":"fec99521dab3c8abef64bee0c75c8fde","cat":"shahih-mutal","type":"fiil_challenge","level":"advanced","variety":"fusha","prompt":"Fi'il berikut termasuk jenis …","ar":"مَدَّ","explanation":"مَدَّ asalnya مَدَدَ: 'ain dan lam fi'il-nya huruf yang sama, maka disebut mudha'af. Tidak ada huruf illat maupun hamzah, sehingga termasuk shahih.","time":30,"options":["Shahih mudha'af","Mu'tal ajwaf","Shahih mahmuz","Mu'tal lafif"],"correct":1,"accepted":[]},{"key":"9c86d01c9147ad3bcb7f6c12a9341948","cat":"rafa","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Tanda rafa' yang asli (ashliyyah) adalah …","ar":null,"explanation":"Tanda asli: rafa' = dhammah, nashab = fathah, jarr = kasrah, jazm = sukun. Tanda lain (wawu, alif, ya', dll.) disebut tanda far'iyyah (cabang).","time":20,"options":["Dhammah","Fathah","Kasrah","Sukun"],"correct":1,"accepted":[]},{"key":"6a763906975b4eb0fcde5237a2c7c7d0","cat":"rafa","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ [[الطَّالِبَانِ]]","explanation":"Isim mutsanna di-rafa'-kan dengan alif sebagai pengganti dhammah: الطَّالِبَانِ. Saat manshub/majrur menjadi الطَّالِبَيْنِ.","time":25,"options":["Fa'il marfu' dengan alif karena isim mutsanna","Fa'il marfu' dengan dhammah","Maf'ul bih manshub dengan ya'","Isim majrur dengan ya'"],"correct":1,"accepted":[]},{"key":"42127a0bb9b1a455006c709550316317","cat":"nashab","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"رَأَيْتُ [[أَخَاكَ]]","explanation":"أَخٌ termasuk asma'ul khamsah (أَبٌ، أَخٌ، حَمٌ، فُو، ذُو). Jika di-idhafah-kan kepada selain ya' mutakallim, ia di-nashab-kan dengan alif: أَخَاكَ.","time":25,"options":["Maf'ul bih manshub dengan alif karena asma'ul khamsah","Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan wawu","Isim majrur dengan ya'"],"correct":1,"accepted":[]},{"key":"a53cf31532d4e34871dc2d3b5fbc5539","cat":"nashab","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَنْ [[يَذْهَبُوا]]","explanation":"لَنْ me-nashab-kan fi'il mudhari'. يَذْهَبُونَ termasuk af'al khamsah, sehingga tanda nashab-nya membuang nun: لَنْ يَذْهَبُوا.","time":30,"options":["Fi'il mudhari' manshub dengan membuang nun","Fi'il mudhari' majzum dengan membuang nun","Fi'il mudhari' manshub dengan fathah","Fi'il mudhari' marfu' dengan tetapnya nun"],"correct":1,"accepted":[]},{"key":"e41eb41a1094fa8cc516edbe2d8429d4","cat":"jarr","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Tanda jarr yang asli (ashliyyah) adalah …","ar":null,"explanation":"Tanda jarr yang asli adalah kasrah. Tanda gantinya: ya' (mutsanna, jamak mudzakkar salim, asma'ul khamsah) dan fathah (isim ghairu munsharif).","time":20,"options":["Kasrah","Fathah","Dhammah","Sukun"],"correct":1,"accepted":[]},{"key":"479281bb162e57188ed01aa85f99af14","cat":"jarr","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"سَلَّمْتُ عَلَى [[أَبِيكَ]]","explanation":"أَبٌ termasuk asma'ul khamsah. Setelah huruf jar عَلَى ia majrur, dan tanda jarr-nya ya': أَبِيكَ.","time":25,"options":["Isim majrur dengan ya' karena asma'ul khamsah","Isim majrur dengan kasrah","Maf'ul bih manshub dengan alif","Fa'il marfu' dengan wawu"],"correct":1,"accepted":[]},{"key":"6e8122ffbc2f465124d4cffae30e7220","cat":"jazm","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَمْ [[يَكْتُبْ]]","explanation":"لَمْ men-jazm-kan fi'il mudhari'. يَكْتُبُ berakhiran huruf shahih, sehingga tanda jazm-nya sukun: لَمْ يَكْتُبْ.","time":25,"options":["Fi'il mudhari' majzum dengan sukun","Fi'il mudhari' manshub dengan fathah","Fi'il mudhari' marfu' dengan dhammah","Fi'il mudhari' majzum dengan membuang nun"],"correct":1,"accepted":[]},{"key":"5b50ad0e9cf4aee69148248764329db8","cat":"jazm","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَمْ [[يَدْعُ]]","explanation":"يَدْعُو berakhiran huruf illat wawu. Fi'il mudhari' mu'tal akhir di-jazm-kan dengan membuang huruf illat-nya: لَمْ يَدْعُ.","time":30,"options":["Fi'il mudhari' majzum dengan membuang huruf illat (wawu)","Fi'il mudhari' majzum dengan sukun","Fi'il mudhari' marfu' dengan dhammah muqaddarah","Fi'il mudhari' manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"77d9835db934031a912c4693d48155d3","cat":"alamat-irab","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Jamak muannats salim ketika manshub ditandai dengan …","ar":null,"explanation":"Jamak muannats salim di-nashab-kan dengan kasrah sebagai pengganti fathah, contoh: رَأَيْتُ الطَّالِبَاتِ.","time":25,"options":["Kasrah","Fathah","Ya'","Alif"],"correct":1,"accepted":[]},{"key":"fc4aae8da0c57029119772cccb26f41b","cat":"alamat-irab","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Isim ghairu munsharif ketika majrur (tanpa ال dan tidak di-idhafah-kan) ditandai dengan …","ar":null,"explanation":"Isim ghairu munsharif (mamnu' min ash-sharf) di-jarr-kan dengan fathah sebagai pengganti kasrah, contoh: مَرَرْتُ بِأَحْمَدَ. Jika ber-ال atau di-idhafah-kan, kembali memakai kasrah.","time":30,"options":["Fathah","Kasrah","Ya'","Sukun"],"correct":1,"accepted":[]},{"key":"a94a1c190a13a52a2637ba9da0f376c7","cat":"irab-jumlah","type":"sentence_analysis","level":"advanced","variety":"fusha","prompt":"Apa i'rab kata yang ditandai?","ar":"كَانَ الطَّالِبُ [[يَقْرَأُ]] الْكِتَابَ","explanation":"يَقْرَأُ tetap marfu' (tidak didahului 'amil nashab/jazm). Jumlah fi'liyyah يَقْرَأُ الْكِتَابَ berkedudukan nashab sebagai khabar كَانَ (fi mahalli nashbin).","time":30,"options":["Fi'il mudhari' marfu'; jumlahnya menjadi khabar kana (mahall nashab)","Fi'il mudhari' manshub karena كَانَ","Isim kana marfu'","Fi'il madhi mabni 'ala al-fath"],"correct":1,"accepted":[]},{"key":"099e1b573e10a38185fed06e2a706a6d","cat":"irab-jumlah","type":"sentence_analysis","level":"advanced","variety":"fusha","prompt":"Apa i'rab kata yang ditandai?","ar":"[[الطُّلَّابُ]] حَضَرُوا","explanation":"Fa'il tidak didahulukan atas fi'il-nya (pendapat jumhur). Fa'il dari حَضَرُوا adalah wawu jama'ah, sehingga الطُّلَّابُ adalah mubtada', dan jumlah حَضَرُوا menjadi khabarnya.","time":30,"options":["Mubtada' marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Maf'ul bih muqaddam","Khabar muqaddam"],"correct":1,"accepted":[]},{"key":"c1d00af5f3a1fba536abf6120d56c05d","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"قَمَرٌ","explanation":"قَمَرٌ = bulan. Matahari = شَمْسٌ, bintang = نَجْمٌ, langit = سَمَاءٌ.","time":20,"options":["Bulan","Matahari","Bintang","Langit"],"correct":1,"accepted":[]},{"key":"ced2c667cfb4efed0d163fe186d372f1","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"شَجَرَةٌ","explanation":"شَجَرَةٌ = pohon (jamak: أَشْجَارٌ). Bunga = زَهْرَةٌ, daun = وَرَقَةٌ, rumput = عُشْبٌ.","time":20,"options":["Pohon","Bunga","Daun","Rumput"],"correct":1,"accepted":[]},{"key":"c909b7c8c8465c3d2511383be62b9cde","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"بَحْرٌ","explanation":"بَحْرٌ = laut (jamak: بِحَارٌ). Sungai = نَهْرٌ, gunung = جَبَلٌ, danau = بُحَيْرَةٌ.","time":20,"options":["Laut","Sungai","Gunung","Danau"],"correct":1,"accepted":[]},{"key":"ea088fa1dc393c4c3462ef886511ab9c","cat":"dasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"api\"?","ar":null,"explanation":"نَارٌ = api. نُورٌ = cahaya, مَاءٌ = air, رِيحٌ = angin.","time":20,"options":["نَارٌ","نُورٌ","مَاءٌ","رِيحٌ"],"correct":1,"accepted":[]},{"key":"ad0ea39c99f0496d72545782122a1811","cat":"dasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"merah\"?","ar":null,"explanation":"أَحْمَرُ = merah (muannats: حَمْرَاءُ). أَصْفَرُ = kuning, أَخْضَرُ = hijau, أَزْرَقُ = biru.","time":20,"options":["أَحْمَرُ","أَصْفَرُ","أَخْضَرُ","أَزْرَقُ"],"correct":1,"accepted":[]},{"key":"7013faf698589f431ea331c4232570e5","cat":"dasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa lawan kata (ضِدّ) dari kata berikut?","ar":"كَبِيرٌ","explanation":"كَبِيرٌ (besar) lawannya صَغِيرٌ (kecil). قَصِيرٌ = pendek (lawan طَوِيلٌ), قَلِيلٌ = sedikit (lawan كَثِيرٌ), ضَعِيفٌ = lemah (lawan قَوِيٌّ).","time":25,"options":["صَغِيرٌ","قَصِيرٌ","قَلِيلٌ","ضَعِيفٌ"],"correct":1,"accepted":[]},{"key":"4b676c3dd773ec5037bf109d1f019e26","cat":"dasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa lawan kata (ضِدّ) dari kata berikut?","ar":"جَدِيدٌ","explanation":"جَدِيدٌ (baru) lawannya قَدِيمٌ (lama/kuno). سَهْلٌ = mudah (lawan صَعْبٌ).","time":25,"options":["قَدِيمٌ","جَمِيلٌ","بَعِيدٌ","سَهْلٌ"],"correct":1,"accepted":[]},{"key":"43b29bcacd6a74fbd59353fbdd548b15","cat":"dasar","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa bentuk jamak dari kata berikut?","ar":"وَلَدٌ","explanation":"Jamak yang paling umum dari وَلَدٌ (anak) adalah أَوْلَادٌ. وِلَادَاتٌ = kelahiran-kelahiran, وَالِدُونَ jamak dari وَالِدٌ (orang tua laki-laki), مَوَالِيدُ jamak dari مَوْلُودٌ (bayi yang lahir).","time":25,"options":["أَوْلَادٌ","وِلَادَاتٌ","وَالِدُونَ","مَوَالِيدُ"],"correct":1,"accepted":[]},{"key":"9659517ddcaa5615421eccda0c6f5fc8","cat":"dasar","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa bentuk jamak dari kata berikut?","ar":"يَوْمٌ","explanation":"Jamak يَوْمٌ adalah أَيَّامٌ (asalnya أَيْوَامٌ, lalu wawu diganti ya' dan di-idgham-kan). يَوْمِيَّاتٌ = catatan harian, يَوْمَانِ = dua hari (mutsanna), أَيْمَانٌ = sumpah-sumpah (jamak يَمِينٌ).","time":30,"options":["أَيَّامٌ","يَوْمِيَّاتٌ","يَوْمَانِ","أَيْمَانٌ"],"correct":1,"accepted":[]},{"key":"49f1ca967c4e2edf4f358be3a775cbb6","cat":"dasar","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? كَلْبٌ artinya \"kucing\".","ar":"كَلْبٌ","explanation":"Salah. كَلْبٌ = anjing. Kucing = قِطٌّ atau قِطَّةٌ.","time":20,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"eb8805ac61f80138dfda2aecb6ea587f","cat":"dasar","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama hewan pada gambar dalam bahasa Arab?","ar":"🐫","explanation":"جَمَلٌ = unta. حِصَانٌ = kuda, بَقَرَةٌ = sapi, حِمَارٌ = keledai.","time":20,"options":["جَمَلٌ","حِصَانٌ","بَقَرَةٌ","حِمَارٌ"],"correct":1,"accepted":[]},{"key":"caf016be33988633f7589262823dbb16","cat":"dasar","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama benda pada gambar dalam bahasa Arab?","ar":"🌙","explanation":"هِلَالٌ = bulan sabit. شَمْسٌ = matahari, سَحَابٌ = awan, مَطَرٌ = hujan.","time":20,"options":["هِلَالٌ","شَمْسٌ","سَحَابٌ","مَطَرٌ"],"correct":1,"accepted":[]},{"key":"cc01c31088a07f52c7486be57e05e34c","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"قَلَمٌ","explanation":"قَلَمٌ = pena (jamak: أَقْلَامٌ). Penggaris = مِسْطَرَةٌ, kertas = وَرَقٌ, meja = مَكْتَبٌ atau طَاوِلَةٌ.","time":20,"options":["Pena","Penggaris","Kertas","Meja"],"correct":1,"accepted":[]},{"key":"86e18e1fd7bbd5f35b2a0b80059afa8c","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"كُرْسِيٌّ","explanation":"كُرْسِيٌّ = kursi (jamak: كَرَاسِيُّ). Lemari = خِزَانَةٌ.","time":20,"options":["Kursi","Lemari","Pintu","Papan tulis"],"correct":1,"accepted":[]},{"key":"239bfb3269ce736ab08a6665ebe0a54f","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"حَقِيبَةٌ","explanation":"حَقِيبَةٌ = tas (jamak: حَقَائِبُ). Seragam = زِيٌّ مَدْرَسِيٌّ, sepatu = حِذَاءٌ.","time":20,"options":["Tas","Buku","Seragam","Sepatu"],"correct":1,"accepted":[]},{"key":"4f54ac443d13a76b74c289b3137478a3","cat":"sekolah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"murid / siswa\"?","ar":null,"explanation":"تِلْمِيذٌ = murid (jamak: تَلَامِيذُ). مُدِيرٌ = kepala/direktur, بَوَّابٌ = penjaga pintu, مُعَلِّمٌ = guru.","time":20,"options":["تِلْمِيذٌ","مُدِيرٌ","بَوَّابٌ","مُعَلِّمٌ"],"correct":1,"accepted":[]},{"key":"6cd5c387e4dff3a00a5a1f17acdf1e45","cat":"sekolah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"penghapus\"?","ar":null,"explanation":"مِمْحَاةٌ = penghapus (pensil). مِبْرَاةٌ = rautan, مِقَصٌّ = gunting, مِلَفٌّ = map/berkas. Semuanya berwazan isim alat (مِفْعَلٌ/مِفْعَلَةٌ).","time":20,"options":["مِمْحَاةٌ","مِبْرَاةٌ","مِقَصٌّ","مِلَفٌّ"],"correct":1,"accepted":[]},{"key":"ea04cf284dfa03b6b6ab37df4f5038d6","cat":"sekolah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"وَاجِبٌ مَنْزِلِيٌّ","explanation":"وَاجِبٌ = kewajiban/tugas, مَنْزِلِيٌّ = rumah. Jadi وَاجِبٌ مَنْزِلِيٌّ = PR. Jadwal pelajaran = جَدْوَلُ الدُّرُوسِ, libur = عُطْلَةٌ.","time":25,"options":["Pekerjaan rumah (PR)","Ujian akhir","Jadwal pelajaran","Libur sekolah"],"correct":1,"accepted":[]},{"key":"36f4fb078f442ad2fd88fcc94f48140b","cat":"sekolah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"جَرَسٌ","explanation":"جَرَسٌ = bel/lonceng. Di sekolah: دَقَّ الْجَرَسُ = bel berbunyi. Kapur = طَبَاشِيرُ.","time":25,"options":["Bel","Jam dinding","Lonceng masjid","Kapur"],"correct":1,"accepted":[]},{"key":"026b976d469dbdfd12f98302aff4fabf","cat":"sekolah","type":"context_challenge","level":"beginner","variety":"fusha","prompt":"Kamu ingin izin bertanya kepada ustadz. Kalimat yang tepat adalah …","ar":null,"explanation":"عِنْدِي سُؤَالٌ = saya punya pertanyaan. Pilihan lain: \"Di mana rumahmu?\", \"Saya lapar.\", \"Selamat tinggal.\"","time":20,"options":["يَا أُسْتَاذُ، عِنْدِي سُؤَالٌ.","يَا أُسْتَاذُ، أَيْنَ بَيْتُكَ؟","يَا أُسْتَاذُ، أَنَا جَائِعٌ.","يَا أُسْتَاذُ، مَعَ السَّلَامَةِ."],"correct":1,"accepted":[]},{"key":"9249617443bff6c073cdc0db607bbd25","cat":"sekolah","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu tidak mendengar penjelasan guru dengan jelas. Kalimat yang tepat adalah …","ar":null,"explanation":"أَعِدْ = ulangilah (fi'il amr dari أَعَادَ). Pilihan lain: \"tulislah\", \"duduklah\", \"diamlah\" — tidak sopan/tidak sesuai untuk guru.","time":25,"options":["أَعِدْ مِنْ فَضْلِكَ.","اُكْتُبْ مِنْ فَضْلِكَ.","اِجْلِسْ مِنْ فَضْلِكَ.","اُسْكُتْ مِنْ فَضْلِكَ."],"correct":1,"accepted":[]},{"key":"e330f453d2afedf608f7a80865c69cd1","cat":"sekolah","type":"sentence_builder","level":"beginner","variety":"fusha","prompt":"Susun menjadi kalimat: \"Buku itu di atas meja.\"","ar":null,"explanation":"الْكِتَابُ (mubtada') + عَلَى الْمَكْتَبِ (khabar berupa jar-majrur). عَلَى = di atas.","time":45,"options":["الْكِتَابُ","عَلَى","الْمَكْتَبِ"],"correct":null,"accepted":["الْكِتَابُ عَلَى الْمَكْتَبِ"]},{"key":"fb365ed96bfb12f299b30fb5319bb9ed","cat":"sekolah","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? فَصْلٌ di sekolah artinya \"kelas\".","ar":"فَصْلٌ","explanation":"Benar. فَصْلٌ = kelas (ruang kelas). Kata ini juga berarti \"musim\" atau \"bab\" tergantung konteks.","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"d46f55300fa70f8d2171c0ff70bb377f","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"غُرْفَةٌ","explanation":"غُرْفَةٌ = kamar/ruangan (jamak: غُرَفٌ). Atap = سَقْفٌ, halaman = فِنَاءٌ atau حَدِيقَةٌ, tangga = سُلَّمٌ.","time":20,"options":["Kamar","Atap","Halaman","Tangga"],"correct":1,"accepted":[]},{"key":"2d29a84410271e96b193a5dc22ffa353","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سَرِيرٌ","explanation":"سَرِيرٌ = tempat tidur/ranjang. Bantal = وِسَادَةٌ, selimut = بَطَّانِيَّةٌ.","time":20,"options":["Tempat tidur","Bantal","Selimut","Kasur lantai"],"correct":1,"accepted":[]},{"key":"4668eacc3f27a0746d8f7e99542cfb00","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"أُمٌّ","explanation":"أُمٌّ = ibu (jamak: أُمَّهَاتٌ). Nenek = جَدَّةٌ, saudari = أُخْتٌ.","time":20,"options":["Ibu","Nenek","Saudari","Bibi"],"correct":1,"accepted":[]},{"key":"4d45845e0a7148b22bd86041b8b7ece4","cat":"rumah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"kamar mandi\"?","ar":null,"explanation":"حَمَّامٌ = kamar mandi. مَطْبَخٌ = dapur, صَالَةٌ = ruang keluarga/aula, شُرْفَةٌ = balkon.","time":20,"options":["حَمَّامٌ","مَطْبَخٌ","صَالَةٌ","شُرْفَةٌ"],"correct":1,"accepted":[]},{"key":"eda42812defb11245dc1b627e2b00817","cat":"rumah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"anak perempuan\"?","ar":null,"explanation":"بِنْتٌ = anak perempuan (jamak: بَنَاتٌ). اِبْنٌ = anak laki-laki, أُخْتٌ = saudari, زَوْجَةٌ = istri.","time":20,"options":["بِنْتٌ","اِبْنٌ","أُخْتٌ","زَوْجَةٌ"],"correct":1,"accepted":[]},{"key":"8a9070495de142f2916cb9759f9efe99","cat":"rumah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"خَالَةٌ","explanation":"خَالَةٌ = saudari ibu. Saudari ayah = عَمَّةٌ. Pasangannya: خَالٌ (saudara ibu) dan عَمٌّ (saudara ayah).","time":25,"options":["Bibi (saudari ibu)","Bibi (saudari ayah)","Nenek","Sepupu perempuan"],"correct":1,"accepted":[]},{"key":"0512347fc5c7f52d1c8ceaea633a5bfc","cat":"rumah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"جِيرَانٌ","explanation":"جِيرَانٌ adalah jamak dari جَارٌ (tetangga). Kerabat = أَقَارِبُ, tamu = ضُيُوفٌ, teman = أَصْدِقَاءُ.","time":25,"options":["Tetangga-tetangga","Kerabat","Tamu-tamu","Teman-teman"],"correct":1,"accepted":[]},{"key":"52071059d68d89e5333a11776fba3808","cat":"rumah","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa bentuk jamak dari kata berikut?","ar":"بَيْتٌ","explanation":"Jamak بَيْتٌ (rumah) adalah بُيُوتٌ. بِيئَاتٌ = lingkungan-lingkungan, بَيَانَاتٌ = data/keterangan, مَبِيتٌ = bermalam. (بَيْتٌ yang berarti bait syair dijamakkan أَبْيَاتٌ.)","time":30,"options":["بُيُوتٌ","بِيئَاتٌ","بَيَانَاتٌ","مَبِيتٌ"],"correct":1,"accepted":[]},{"key":"bfb1e50e2e1e62fd637a598cad8791f3","cat":"rumah","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? مِفْتَاحٌ artinya \"kunci\".","ar":"مِفْتَاحٌ","explanation":"Benar. مِفْتَاحٌ = kunci (jamak: مَفَاتِيحُ), isim alat dari فَتَحَ (membuka).","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"bd97319cb2635002b940c86923980aa0","cat":"rumah","type":"complete_expression","level":"intermediate","variety":"fusha","prompt":"Lengkapi kalimat \"Ayahku bekerja di kantor.\"","ar":"أَبِي ـــــ فِي الْمَكْتَبِ","explanation":"أَبِي (ayahku) adalah orang ketiga laki-laki, maka fi'il-nya يَعْمَلُ. تَعْمَلُ untuk dia (pr)/kamu, أَعْمَلُ = saya, نَعْمَلُ = kami.","time":25,"options":["يَعْمَلُ","تَعْمَلُ","أَعْمَلُ","نَعْمَلُ"],"correct":1,"accepted":[]},{"key":"97d63e92cf6874a1c76d1deb42588369","cat":"makanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"لَحْمٌ","explanation":"لَحْمٌ = daging (jamak: لُحُومٌ). Ikan = سَمَكٌ, telur = بَيْضٌ, sayur = خُضَارٌ.","time":20,"options":["Daging","Ikan","Telur","Sayur"],"correct":1,"accepted":[]},{"key":"59b0987dbf132abf8a1b14718f6a2424","cat":"makanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سُكَّرٌ","explanation":"سُكَّرٌ = gula. Garam = مِلْحٌ, tepung = دَقِيقٌ, merica = فُلْفُلٌ.","time":20,"options":["Gula","Garam","Tepung","Merica"],"correct":1,"accepted":[]},{"key":"f600478f6037992180b2bfbf6705b2a3","cat":"makanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"فُطُورٌ","explanation":"فُطُورٌ = sarapan (juga makanan berbuka puasa). Makan siang = غَدَاءٌ, makan malam = عَشَاءٌ.","time":20,"options":["Sarapan","Makan siang","Makan malam","Camilan"],"correct":1,"accepted":[]},{"key":"da429690228c5f43b6bdb6b7f2dbc856","cat":"makanan","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"nasi\"?","ar":null,"explanation":"أَرُزٌّ = nasi/beras. خُبْزٌ = roti, فُولٌ = kacang fava (makanan khas Mesir), عَدَسٌ = kacang adas.","time":20,"options":["أَرُزٌّ","خُبْزٌ","فُولٌ","عَدَسٌ"],"correct":1,"accepted":[]},{"key":"e4316fcb2694b8fbda2fa586c2a8d521","cat":"makanan","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"ikan\"?","ar":null,"explanation":"سَمَكٌ = ikan. دَجَاجٌ = ayam, لَحْمٌ = daging, جُبْنٌ = keju.","time":20,"options":["سَمَكٌ","دَجَاجٌ","لَحْمٌ","جُبْنٌ"],"correct":1,"accepted":[]},{"key":"26d70b69f0ed0779edda996cff04868c","cat":"makanan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"جَائِعٌ","explanation":"جَائِعٌ = lapar. Haus = عَطْشَانُ, kenyang = شَبْعَانُ, lelah = تَعْبَانُ.","time":25,"options":["Lapar","Haus","Kenyang","Lelah"],"correct":1,"accepted":[]},{"key":"6308850a962d75df5b3edc2e2f9c6c02","cat":"makanan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مِلْعَقَةٌ","explanation":"مِلْعَقَةٌ = sendok. Garpu = شَوْكَةٌ, pisau = سِكِّينٌ, piring = صَحْنٌ.","time":25,"options":["Sendok","Garpu","Pisau","Piring"],"correct":1,"accepted":[]},{"key":"30abc65198a4ce8c9e334b8e12761518","cat":"makanan","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama buah pada gambar dalam bahasa Arab?","ar":"🍇","explanation":"عِنَبٌ = anggur. تِينٌ = buah tin, رُمَّانٌ = delima, بِطِّيخٌ = semangka.","time":20,"options":["عِنَبٌ","تِينٌ","رُمَّانٌ","بِطِّيخٌ"],"correct":1,"accepted":[]},{"key":"0024c478a2a9694f3f6e7ff920398279","cat":"makanan","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama minuman pada gambar dalam bahasa Arab?","ar":"☕","explanation":"قَهْوَةٌ = kopi. حَلِيبٌ = susu, عَصِيرٌ = jus, مَاءٌ = air.","time":20,"options":["قَهْوَةٌ","حَلِيبٌ","عَصِيرٌ","مَاءٌ"],"correct":1,"accepted":[]},{"key":"e11c81e780ebe2dcbc0ff200ff26fd12","cat":"makanan","type":"picture_vocabulary","level":"intermediate","variety":"fusha","prompt":"Apa nama buah pada gambar dalam bahasa Arab?","ar":"🍉","explanation":"بِطِّيخٌ = semangka. خَوْخٌ = persik, مِشْمِشٌ = aprikot, لَيْمُونٌ = lemon.","time":25,"options":["بِطِّيخٌ","خَوْخٌ","مِشْمِشٌ","لَيْمُونٌ"],"correct":1,"accepted":[]},{"key":"f0bb8dce2e32020d7a0762bcff93b5ff","cat":"makanan","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? مِلْحٌ artinya \"gula\".","ar":"مِلْحٌ","explanation":"Salah. مِلْحٌ = garam. Gula = سُكَّرٌ.","time":20,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"751de0bcd9b3bcf96b5f756cc9f48533","cat":"makanan","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi kalimat: \"Saya minum teh di pagi hari.\"","ar":null,"explanation":"أَشْرَبُ (saya minum) + الشَّايَ (maf'ul bih) + فِي الصَّبَاحِ (keterangan waktu, boleh di depan).","time":45,"options":["أَشْرَبُ","الشَّايَ","فِي","الصَّبَاحِ"],"correct":null,"accepted":["أَشْرَبُ الشَّايَ فِي الصَّبَاحِ","فِي الصَّبَاحِ أَشْرَبُ الشَّايَ"]},{"key":"38c04e14a26c25ff64fafd9cacbba4dc","cat":"aktivitas","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَأْكُلُ","explanation":"أَكَلَ – يَأْكُلُ = makan. Minum = يَشْرَبُ, memasak = يَطْبُخُ, mencuci = يَغْسِلُ.","time":20,"options":["Makan","Minum","Memasak","Mencuci"],"correct":1,"accepted":[]},{"key":"dbd900c1af3fd389146e6841cba51a48","cat":"aktivitas","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَكْتُبُ","explanation":"كَتَبَ – يَكْتُبُ = menulis. Membaca = يَقْرَأُ, menggambar = يَرْسُمُ, menghapus = يَمْسَحُ.","time":20,"options":["Menulis","Membaca","Menggambar","Menghapus"],"correct":1,"accepted":[]},{"key":"120cc6611648aba485d6c6e601e0a816","cat":"aktivitas","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَلْعَبُ","explanation":"لَعِبَ – يَلْعَبُ = bermain. Berlari = يَجْرِي, berenang = يَسْبَحُ, belajar = يَدْرُسُ.","time":20,"options":["Bermain","Berlari","Berenang","Belajar"],"correct":1,"accepted":[]},{"key":"6b6bddcdb3d98a356205838b59965d49","cat":"aktivitas","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"mandi\"?","ar":null,"explanation":"اِسْتَحَمَّ – يَسْتَحِمُّ = mandi. يَتَوَضَّأُ = berwudu, يَغْسِلُ = mencuci, يَلْبَسُ = memakai (pakaian).","time":20,"options":["يَسْتَحِمُّ","يَتَوَضَّأُ","يَغْسِلُ","يَلْبَسُ"],"correct":1,"accepted":[]},{"key":"5e87323aa8b8750891b24da58ba09ce5","cat":"aktivitas","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"salat\"?","ar":null,"explanation":"صَلَّى – يُصَلِّي = salat. يَصُومُ = berpuasa, يَقْرَأُ = membaca, يَدْعُو = berdoa.","time":20,"options":["يُصَلِّي","يَصُومُ","يَقْرَأُ","يَدْعُو"],"correct":1,"accepted":[]},{"key":"6ccb46b985e7d357ed9692da441ff201","cat":"aktivitas","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يُرَاجِعُ الدَّرْسَ","explanation":"رَاجَعَ – يُرَاجِعُ = mengulang/meninjau kembali. Menghafal = يَحْفَظُ, menjelaskan = يَشْرَحُ.","time":25,"options":["Mengulang pelajaran","Menulis pelajaran","Menghafal surat","Menjelaskan pelajaran"],"correct":1,"accepted":[]},{"key":"2a137ea7d5627406fc89ca54b2e23952","cat":"aktivitas","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَرْجِعُ","explanation":"رَجَعَ – يَرْجِعُ = kembali. Berangkat = يَذْهَبُ, masuk = يَدْخُلُ, keluar = يَخْرُجُ.","time":25,"options":["Kembali / pulang","Berangkat","Masuk","Keluar"],"correct":1,"accepted":[]},{"key":"19cc9e90b0be36525a979f79627e9b3f","cat":"aktivitas","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Lengkapi kalimat \"Saya bangun pukul lima pagi.\"","ar":"ـــــ فِي السَّاعَةِ الْخَامِسَةِ صَبَاحًا","explanation":"أَسْتَيْقِظُ = saya bangun (tidur). أَنَامُ = saya tidur, أَتَغَدَّى = saya makan siang, أَرْجِعُ = saya kembali.","time":20,"options":["أَسْتَيْقِظُ","أَنَامُ","أَتَغَدَّى","أَرْجِعُ"],"correct":1,"accepted":[]},{"key":"08393c2f168b97a0774a87d4a53d5899","cat":"aktivitas","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi kalimat: \"Kami salat Subuh di masjid.\"","ar":null,"explanation":"نُصَلِّي = kami salat, الصُّبْحَ = (salat) Subuh sebagai maf'ul bih, فِي الْمَسْجِدِ = di masjid.","time":45,"options":["نُصَلِّي","الصُّبْحَ","فِي","الْمَسْجِدِ"],"correct":null,"accepted":["نُصَلِّي الصُّبْحَ فِي الْمَسْجِدِ"]},{"key":"16f79cb91a80ce4df65e27e5196223ed","cat":"aktivitas","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? نَذْهَبُ artinya \"mereka pergi\".","ar":"نَذْهَبُ","explanation":"Salah. نَذْهَبُ = kami pergi (huruf نَ di awal mudhari' = kami). Mereka pergi = يَذْهَبُونَ.","time":25,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"822f02719b0a4cb6014a14a1366d18b6","cat":"perjalanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سَيَّارَةٌ","explanation":"سَيَّارَةٌ = mobil. Sepeda = دَرَّاجَةٌ, bus = حَافِلَةٌ, kapal = سَفِينَةٌ.","time":20,"options":["Mobil","Sepeda","Bus","Kapal"],"correct":1,"accepted":[]},{"key":"3ad20e854ef68c5adea1eaeb919b8c18","cat":"perjalanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"طَرِيقٌ","explanation":"طَرِيقٌ = jalan (jamak: طُرُقٌ). Jembatan = جِسْرٌ, lampu lalu lintas = إِشَارَةُ الْمُرُورِ.","time":20,"options":["Jalan","Jembatan","Lampu lalu lintas","Persimpangan"],"correct":1,"accepted":[]},{"key":"9d649c3e6e62f0219afc5d0caaf607aa","cat":"perjalanan","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"kereta api\"?","ar":null,"explanation":"قِطَارٌ = kereta api. طَائِرَةٌ = pesawat, حَافِلَةٌ = bus, سَفِينَةٌ = kapal.","time":20,"options":["قِطَارٌ","طَائِرَةٌ","حَافِلَةٌ","سَفِينَةٌ"],"correct":1,"accepted":[]},{"key":"9cb18c293e6472a1bf936fcd913896e3","cat":"perjalanan","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"paspor\"?","ar":null,"explanation":"جَوَازُ سَفَرٍ = paspor. تَأْشِيرَةٌ = visa, بِطَاقَةُ هُوِيَّةٍ = kartu identitas (KTP), تَذْكِرَةٌ = tiket.","time":25,"options":["جَوَازُ سَفَرٍ","تَأْشِيرَةٌ","بِطَاقَةُ هُوِيَّةٍ","تَذْكِرَةُ سَفَرٍ"],"correct":1,"accepted":[]},{"key":"acba631f558b4234fc51e8878e25931f","cat":"perjalanan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"فُنْدُقٌ","explanation":"فُنْدُقٌ = hotel (jamak: فَنَادِقُ). Rumah sakit = مُسْتَشْفًى, kantor pos = مَكْتَبُ الْبَرِيدِ, bank = بَنْكٌ / مَصْرِفٌ.","time":25,"options":["Hotel","Rumah sakit","Kantor pos","Bank"],"correct":1,"accepted":[]},{"key":"7ef305ca30f28faf3bfc892c5df5c401","cat":"perjalanan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَمِينٌ","explanation":"يَمِينٌ = kanan. Kiri = يَسَارٌ / شِمَالٌ, lurus = مُبَاشَرَةً / عَلَى طُولٍ, belakang = خَلْفٌ.","time":25,"options":["Kanan","Kiri","Lurus","Belakang"],"correct":1,"accepted":[]},{"key":"802659663817a646519ab0e4323ab826","cat":"perjalanan","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu ingin tahu kapan pesawat berangkat. Kalimat yang tepat adalah …","ar":null,"explanation":"مَتَى = kapan, تُقْلِعُ = lepas landas/berangkat. Pilihan lain menanyakan tempat, harga, dan ukuran.","time":25,"options":["مَتَى تُقْلِعُ الطَّائِرَةُ؟","أَيْنَ الطَّائِرَةُ؟","كَمْ ثَمَنُ الطَّائِرَةِ؟","هَلِ الطَّائِرَةُ كَبِيرَةٌ؟"],"correct":1,"accepted":[]},{"key":"bb6010c9dd77df04eae26c41d07df32a","cat":"perjalanan","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Petugas hotel bertanya: كَمْ لَيْلَةً تُرِيدُ أَنْ تَبْقَى؟ Pilih respons yang paling tepat.","ar":"كَمْ لَيْلَةً تُرِيدُ أَنْ تَبْقَى؟","explanation":"Pertanyaan: \"Berapa malam Anda ingin menginap?\" Jawabannya menyebut jumlah malam: ثَلَاثَ لَيَالٍ (tiga malam).","time":25,"options":["ثَلَاثَ لَيَالٍ مِنْ فَضْلِكَ.","غُرْفَةً لِشَخْصَيْنِ.","أَنَا مِنْ إِنْدُونِيسِيَا.","الْغُرْفَةُ نَظِيفَةٌ."],"correct":1,"accepted":[]},{"key":"7d651d0e134919769d3314c7bd23d474","cat":"perjalanan","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? مَطَارٌ adalah tempat pesawat mendarat dan lepas landas.","ar":"مَطَارٌ","explanation":"Benar. مَطَارٌ = bandara, isim makan dari طَارَ (terbang).","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"ff4f2d0813a46e6b8073e7cff480d3f6","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"اِمْتِحَانٌ","explanation":"اِمْتِحَانٌ = ujian (jamak: اِمْتِحَانَاتٌ). Wisuda = تَخَرُّجٌ, pendaftaran = تَسْجِيلٌ, beasiswa = مِنْحَةٌ دِرَاسِيَّةٌ.","time":25,"options":["Ujian","Wisuda","Pendaftaran","Beasiswa"],"correct":1,"accepted":[]},{"key":"721e788a09606389344390aa16b3f5a3","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مِنْحَةٌ دِرَاسِيَّةٌ","explanation":"مِنْحَةٌ = pemberian/hibah; مِنْحَةٌ دِرَاسِيَّةٌ = beasiswa. Uang kuliah = رُسُومٌ دِرَاسِيَّةٌ, ijazah = شَهَادَةٌ, asrama = سَكَنٌ طُلَّابِيٌّ.","time":25,"options":["Beasiswa","Uang kuliah","Ijazah","Asrama"],"correct":1,"accepted":[]},{"key":"0b14398061ff8f3f256534abee8d044c","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سَكَنٌ طُلَّابِيٌّ","explanation":"سَكَنٌ = tempat tinggal, طُلَّابِيٌّ = (untuk) mahasiswa. Kantin = مَقْصَفٌ, aula = قَاعَةٌ.","time":25,"options":["Asrama mahasiswa","Kantin kampus","Aula kampus","Masjid kampus"],"correct":1,"accepted":[]},{"key":"30694f9b290b9b8d5218422cf869001c","cat":"kampus","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"dosen\"?","ar":null,"explanation":"مُحَاضِرٌ = dosen/pengajar kuliah (isim fa'il dari حَاضَرَ). مُوَظَّفٌ = pegawai, عَمِيدٌ = dekan.","time":25,"options":["مُحَاضِرٌ","مُوَظَّفٌ","مُشْرِفٌ رِيَاضِيٌّ","عَمِيدٌ"],"correct":1,"accepted":[]},{"key":"31a13b6ddab893bded9aef19c0fb20f2","cat":"kampus","type":"arabic_translation","level":"advanced","variety":"fusha","prompt":"Apa bahasa Arabnya \"skripsi / tesis\"?","ar":null,"explanation":"رِسَالَةٌ عِلْمِيَّةٌ = karya ilmiah (skripsi/tesis/disertasi). مَقَالَةٌ صَحَفِيَّةٌ = artikel koran, مُذَكِّرَةٌ يَوْمِيَّةٌ = buku harian, قِصَّةٌ قَصِيرَةٌ = cerpen.","time":30,"options":["رِسَالَةٌ عِلْمِيَّةٌ","مَقَالَةٌ صَحَفِيَّةٌ","مُذَكِّرَةٌ يَوْمِيَّةٌ","قِصَّةٌ قَصِيرَةٌ"],"correct":1,"accepted":[]},{"key":"e78c18109d343355ca3c5e215786d217","cat":"kampus","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"تَخَصُّصٌ","explanation":"تَخَصُّصٌ = spesialisasi/bidang keahlian. Kelulusan = نَجَاحٌ/تَخَرُّجٌ, kehadiran = حُضُورٌ, nilai = دَرَجَةٌ.","time":30,"options":["Spesialisasi / jurusan keahlian","Kelulusan","Kehadiran","Nilai ujian"],"correct":1,"accepted":[]},{"key":"4f54f339fa25ef6fafcd5b3e17c50c3e","cat":"kampus","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"جَدْوَلُ الْمُحَاضَرَاتِ","explanation":"جَدْوَلٌ = tabel/jadwal; جَدْوَلُ الْمُحَاضَرَاتِ = jadwal perkuliahan. Daftar hadir = كَشْفُ الْحُضُورِ.","time":30,"options":["Jadwal kuliah","Daftar hadir","Kalender akademik","Hasil ujian"],"correct":1,"accepted":[]},{"key":"709d969cdfa55aca53580328401bca91","cat":"kampus","type":"context_challenge","level":"advanced","variety":"fusha","prompt":"Kamu ingin menanyakan di mana gedung Fakultas Syariah. Kalimat yang tepat adalah …","ar":null,"explanation":"مَبْنَى = gedung, أَيْنَ = di mana. Pilihan lain menanyakan waktu mulai, nama dekan, dan jumlah mahasiswa.","time":30,"options":["أَيْنَ مَبْنَى كُلِّيَّةِ الشَّرِيعَةِ؟","مَتَى تَبْدَأُ كُلِّيَّةُ الشَّرِيعَةِ؟","مَنْ عَمِيدُ كُلِّيَّةِ الشَّرِيعَةِ؟","كَمْ طَالِبًا فِي كُلِّيَّةِ الشَّرِيعَةِ؟"],"correct":1,"accepted":[]},{"key":"65cf832c0457367ad52659fe6068dce6","cat":"kampus","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? مَكْتَبَةٌ artinya \"perpustakaan\".","ar":"مَكْتَبَةٌ","explanation":"Benar. مَكْتَبَةٌ = perpustakaan atau toko buku. Adapun مَكْتَبٌ = meja kerja/kantor.","time":25,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"6fae9990fc15584dd40eacb7382be7ad","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Temanmu bertanya: كَيْفَ حَالُكَ؟ Pilih respons yang paling tepat.","ar":"كَيْفَ حَالُكَ؟","explanation":"كَيْفَ حَالُكَ؟ = Apa kabarmu? Jawaban lazim: بِخَيْرٍ، الْحَمْدُ لِلّٰهِ (baik, alhamdulillah).","time":20,"options":["بِخَيْرٍ، الْحَمْدُ لِلّٰهِ.","اِسْمِي عَلِيٌّ.","أَنَا مِنْ جَاكَرْتَا.","إِلَى اللِّقَاءِ."],"correct":1,"accepted":[]},{"key":"cd1fbcf4dadb6a718767f6227b88480e","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Seseorang berkata: مَسَاءَ الْخَيْرِ. Pilih respons yang paling tepat.","ar":"مَسَاءَ الْخَيْرِ","explanation":"مَسَاءَ الْخَيْرِ (selamat sore/malam) dijawab مَسَاءَ النُّورِ.","time":20,"options":["مَسَاءَ النُّورِ","صَبَاحَ النُّورِ","وَأَنْتَ كَذَلِكَ","تَفَضَّلْ"],"correct":1,"accepted":[]},{"key":"db003617cde7378aabb8e2a51f3dfa62","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Teman baru berkata: تَشَرَّفْنَا. Pilih respons yang paling tepat.","ar":"تَشَرَّفْنَا","explanation":"تَشَرَّفْنَا = senang berkenalan (kami merasa terhormat). Jawabannya: الشَّرَفُ لِي = kehormatan bagiku.","time":20,"options":["الشَّرَفُ لِي.","عَلَيْكُمُ السَّلَامُ.","لَا شُكْرَ عَلَى وَاجِبٍ.","مَعَ السَّلَامَةِ."],"correct":1,"accepted":[]},{"key":"195fbe2e79671908f0a8d7c41a6f7986","cat":"salam","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Seseorang bertanya: كَمْ عُمْرُكَ؟ Pilih respons yang paling tepat.","ar":"كَمْ عُمْرُكَ؟","explanation":"كَمْ عُمْرُكَ؟ = Berapa umurmu? Jawabannya عُمْرِي ... سَنَةً (umurku ... tahun).","time":25,"options":["عُمْرِي خَمْسَ عَشْرَةَ سَنَةً.","أَسْكُنُ فِي بَانْدُونْغ.","أَنَا فِي الْفَصْلِ الثَّالِثِ.","عِنْدِي أَخَوَانِ."],"correct":1,"accepted":[]},{"key":"33b146cfa6299f169d3065ed24d2979a","cat":"salam","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Seseorang bertanya: أَيْنَ تَسْكُنُ؟ Pilih respons yang paling tepat.","ar":"أَيْنَ تَسْكُنُ؟","explanation":"أَيْنَ تَسْكُنُ؟ = Di mana kamu tinggal? Jawabannya أَسْكُنُ فِي ... (saya tinggal di ...). مَدِينَةُ نَصْرٍ (Nasr City) adalah kawasan di Kairo.","time":25,"options":["أَسْكُنُ فِي مَدِينَةِ نَصْرٍ.","أَدْرُسُ فِي الْأَزْهَرِ.","أَنَا طَالِبٌ جَدِيدٌ.","جِئْتُ أَمْسِ."],"correct":1,"accepted":[]},{"key":"ab3b740138bfe9c3bbfe76c43f3e410f","cat":"salam","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Lengkapi ungkapan perpisahan \"Sampai jumpa\".","ar":"إِلَى ـــــ","explanation":"إِلَى اللِّقَاءِ = sampai jumpa. Ungkapan perpisahan lain: مَعَ السَّلَامَةِ.","time":20,"options":["اللِّقَاءِ","السَّلَامِ","الْخَيْرِ","الْمَسَاءِ"],"correct":1,"accepted":[]},{"key":"467fc57efd0ff045eee06e7b2f2e1f7f","cat":"salam","type":"sentence_builder","level":"beginner","variety":"fusha","prompt":"Susun menjadi kalimat: \"Saya pelajar dari Indonesia.\"","ar":null,"explanation":"أَنَا (mubtada') + طَالِبٌ (khabar) + مِنْ إِنْدُونِيسِيَا (keterangan asal).","time":45,"options":["أَنَا","طَالِبٌ","مِنْ","إِنْدُونِيسِيَا"],"correct":null,"accepted":["أَنَا طَالِبٌ مِنْ إِنْدُونِيسِيَا"]},{"key":"961bf92ced8acf2e3b96223f8573d8ab","cat":"salam","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? مَعَ السَّلَامَةِ diucapkan ketika bertemu seseorang.","ar":"مَعَ السَّلَامَةِ","explanation":"Salah. مَعَ السَّلَامَةِ diucapkan ketika berpisah (semoga selamat). Ketika bertemu diucapkan السَّلَامُ عَلَيْكُمْ atau أَهْلًا.","time":20,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"9cff7341ed1a35f58819fa4e93fb6d40","cat":"pasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"رَخِيصٌ","explanation":"رَخِيصٌ = murah. Mahal = غَالٍ (الْغَالِي), baru = جَدِيدٌ, rusak = مَكْسُورٌ / تَالِفٌ.","time":20,"options":["Murah","Mahal","Baru","Rusak"],"correct":1,"accepted":[]},{"key":"e3034f6d70a7a6e2ea637b780ca20464","cat":"pasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"بَائِعٌ","explanation":"بَائِعٌ = penjual (isim fa'il dari بَاعَ). Pembeli = مُشْتَرٍ, kasir = أَمِينُ الصُّنْدُوقِ, pelayan = نَادِلٌ.","time":20,"options":["Penjual","Pembeli","Kasir","Pelayan"],"correct":1,"accepted":[]},{"key":"43d8b3602f8df02d6f4c92a383f9b896","cat":"pasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"uang\"?","ar":null,"explanation":"نُقُودٌ = uang. ثِيَابٌ = pakaian, أَسْعَارٌ = harga-harga, بِضَاعَةٌ = barang dagangan.","time":20,"options":["نُقُودٌ","ثِيَابٌ","أَسْعَارٌ","بِضَاعَةٌ"],"correct":1,"accepted":[]},{"key":"7296574ffa75036e95586f18031b30d4","cat":"pasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"tagihan / bon\"?","ar":null,"explanation":"الْحِسَابُ = tagihan. الْبَاقِي = kembalian, الْخَصْمُ = diskon, الطَّلَبُ = pesanan.","time":25,"options":["الْحِسَابُ","الْبَاقِي","الْخَصْمُ","الطَّلَبُ"],"correct":1,"accepted":[]},{"key":"5e9f11f5b3bf9daba182d6287e46a9ef","cat":"pasar","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Pelayan restoran bertanya: مَاذَا تُرِيدُ أَنْ تَأْكُلَ؟ Pilih respons yang paling tepat.","ar":"مَاذَا تُرِيدُ أَنْ تَأْكُلَ؟","explanation":"Pertanyaan: \"Apa yang ingin kamu makan?\" Jawaban yang tepat menyebut makanan: أُرِيدُ أَرُزًّا وَدَجَاجًا (saya mau nasi dan ayam).","time":20,"options":["أُرِيدُ أَرُزًّا وَدَجَاجًا.","أُرِيدُ أَنْ أَنَامَ.","الْمَطْعَمُ بَعِيدٌ.","أَنَا لَا أَعْرِفُ الطَّرِيقَ."],"correct":1,"accepted":[]},{"key":"be06a539f41947921abe87be5f1318d3","cat":"pasar","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Harga barang terlalu mahal dan kamu ingin menawar. Kalimat yang tepat adalah …","ar":null,"explanation":"تُخَفِّضَ السِّعْرَ = menurunkan harga. غَالٍ = mahal. Pilihan lain tidak berisi tawaran.","time":25,"options":["هَذَا غَالٍ، هَلْ يُمْكِنُ أَنْ تُخَفِّضَ السِّعْرَ؟","هَذَا رَخِيصٌ جِدًّا، شُكْرًا.","أَيْنَ السُّوقُ؟","أُرِيدُ أَنْ أَبِيعَ هَذَا."],"correct":1,"accepted":[]},{"key":"bee3ac90e4590047606abdbfa1e26d5f","cat":"pasar","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu ingin bertanya apakah ada ukuran yang lebih besar. Kalimat yang tepat adalah …","ar":null,"explanation":"مَقَاسٌ = ukuran, أَكْبَرُ = lebih besar (isim tafdhil). Pilihan lain: warna lain, apakah baru, apakah menerima kartu.","time":25,"options":["هَلْ عِنْدَكَ مَقَاسٌ أَكْبَرُ؟","هَلْ عِنْدَكَ لَوْنٌ آخَرُ؟","هَلْ هَذَا جَدِيدٌ؟","هَلْ تَقْبَلُ الْبِطَاقَةَ؟"],"correct":1,"accepted":[]},{"key":"cf1eaac0d8a5f71d8c7a0deca0071999","cat":"pasar","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Lengkapi kalimat \"Berapa harga kilo apel?\"","ar":"ـــــ كِيلُو التُّفَّاحِ؟","explanation":"بِكَمْ = dengan berapa (menanyakan harga). أَيْنَ = di mana, مَتَى = kapan, مَنْ = siapa.","time":20,"options":["بِكَمْ","أَيْنَ","مَتَى","مَنْ"],"correct":1,"accepted":[]},{"key":"fef3da7c47ab47416988d47e16f7a93c","cat":"pasar","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? Dalam percakapan jual beli, الْبَاقِي berarti \"uang kembalian\".","ar":"الْبَاقِي","explanation":"Benar. الْبَاقِي = sisa/kembalian. Contoh: خُذِ الْبَاقِيَ = ambillah kembaliannya.","time":25,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"887f59a7cd1c23a0503231a6b19739f1","cat":"ungkapan","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Sebelum makan, kita mengucapkan …","ar":"ـــــ اللّٰهِ","explanation":"Sebelum makan diucapkan بِسْمِ اللّٰهِ. Setelah makan: الْحَمْدُ لِلّٰهِ.","time":20,"options":["بِسْمِ","الْحَمْدُ","سُبْحَانَ","أَسْتَغْفِرُ"],"correct":1,"accepted":[]},{"key":"a2bf365d6183b8cfea3f2a4d65e470ea","cat":"ungkapan","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Ketika mendengar kabar duka (musibah), kita mengucapkan …","ar":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ ـــــ","explanation":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ = sesungguhnya kami milik Allah dan kepada-Nya kami kembali (QS. Al-Baqarah: 156).","time":20,"options":["رَاجِعُونَ","صَابِرُونَ","شَاكِرُونَ","ذَاهِبُونَ"],"correct":1,"accepted":[]},{"key":"3a996a6a3960deef2d98d7e2eef4cc86","cat":"ungkapan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Kapan ungkapan berikut diucapkan?","ar":"مَا شَاءَ اللّٰهُ","explanation":"مَا شَاءَ اللّٰهُ diucapkan ketika kagum atas nikmat/kebaikan. Untuk rencana yang akan datang: إِنْ شَاءَ اللّٰهُ.","time":20,"options":["Ketika kagum melihat sesuatu yang baik","Ketika berjanji untuk besok","Ketika bersin","Ketika meminta maaf"],"correct":1,"accepted":[]},{"key":"3b7dd200b018eeebb1ffb608c812a7f5","cat":"ungkapan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti ungkapan berikut?","ar":"جَزَاكَ اللّٰهُ خَيْرًا","explanation":"جَزَاكَ اللّٰهُ خَيْرًا = semoga Allah membalasmu dengan kebaikan, ungkapan terima kasih. Jawabannya: وَإِيَّاكَ (dan juga kamu).","time":20,"options":["Semoga Allah membalasmu dengan kebaikan","Semoga Allah merahmatimu","Semoga Allah memberimu petunjuk","Semoga Allah mengampunimu"],"correct":1,"accepted":[]},{"key":"ca53ffc9dacbfe8dc8d8b9ee2d9800a6","cat":"ungkapan","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Temanmu berkata: شُكْرًا جَزِيلًا. Pilih respons yang paling tepat.","ar":"شُكْرًا جَزِيلًا","explanation":"شُكْرًا جَزِيلًا = terima kasih banyak; dijawab عَفْوًا (sama-sama). بِالْهَنَاءِ وَالشِّفَاءِ diucapkan kepada orang yang makan.","time":20,"options":["عَفْوًا.","مَعَ السَّلَامَةِ.","صَبَاحَ الْخَيْرِ.","بِالْهَنَاءِ وَالشِّفَاءِ."],"correct":1,"accepted":[]},{"key":"47aea40fce06c617afc1714f766a1b42","cat":"ungkapan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti ungkapan berikut?","ar":"تَفَضَّلْ","explanation":"تَفَضَّلْ = silakan (masuk/duduk/ambil). Untuk perempuan: تَفَضَّلِي. Tunggu sebentar = لَحْظَةً / اِنْتَظِرْ قَلِيلًا.","time":25,"options":["Silakan","Tunggu sebentar","Hati-hati","Cepatlah"],"correct":1,"accepted":[]},{"key":"c315c0f08febdefab755e7a858709a88","cat":"ungkapan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti ungkapan berikut?","ar":"لَا بَأْسَ","explanation":"لَا بَأْسَ = tidak apa-apa. Kepada orang sakit diucapkan: لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللّٰهُ.","time":25,"options":["Tidak apa-apa","Tidak boleh","Tidak tahu","Tidak ada"],"correct":1,"accepted":[]},{"key":"d0eeb1c537cd9bd221990aceb5aa072a","cat":"ungkapan","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? سُبْحَانَ اللّٰهِ diucapkan ketika melihat sesuatu yang menakjubkan.","ar":"سُبْحَانَ اللّٰهِ","explanation":"Benar. سُبْحَانَ اللّٰهِ (Maha Suci Allah) diucapkan saat takjub atau melihat sesuatu yang mengherankan; juga sebagai zikir.","time":25,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"ae102f3e604cbb498b262d36f5a7c92a","cat":"ungkapan","type":"complete_expression","level":"intermediate","variety":"fusha","prompt":"Ketika melakukan kesalahan, kita beristighfar dengan mengucapkan …","ar":"ـــــ اللّٰهَ","explanation":"أَسْتَغْفِرُ اللّٰهَ = aku memohon ampun kepada Allah. أَعُوذُ بِاللّٰهِ = aku berlindung kepada Allah.","time":25,"options":["أَسْتَغْفِرُ","أَعُوذُ بِ","أَشْهَدُ أَنَّ","سُبْحَانَ"],"correct":1,"accepted":[]},{"key":"ab21b48ac994161bdf1dfbe71269b07d","cat":"fusha","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"مَتَى تَبْدَأُ الدِّرَاسَةُ؟","explanation":"Pertanyaan: \"Kapan pelajaran dimulai?\" (مَتَى = kapan). Jawaban yang tepat menyebut waktu: pukul tujuh.","time":25,"options":["تَبْدَأُ الدِّرَاسَةُ فِي السَّاعَةِ السَّابِعَةِ.","الدِّرَاسَةُ مُمْتِعَةٌ.","أَدْرُسُ فِي الْمَعْهَدِ.","بَدَأْتُ الدِّرَاسَةَ أَمْسِ مَعَ أَخِي."],"correct":1,"accepted":[]},{"key":"45bb84a46b06c273c3f96b08b7e024d4","cat":"fusha","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"لِمَاذَا تَأَخَّرْتَ عَنِ الدَّرْسِ؟","explanation":"لِمَاذَا = mengapa; jawabannya diawali لِأَنَّ (karena): \"karena jalan macet\". جِئْتُ بِالسَّيَّارَةِ menjawab \"dengan apa\", bukan \"mengapa\".","time":25,"options":["لِأَنَّ الطَّرِيقَ كَانَ مُزْدَحِمًا.","سَأَحْضُرُ غَدًا.","الدَّرْسُ صَعْبٌ.","جِئْتُ بِالسَّيَّارَةِ."],"correct":1,"accepted":[]},{"key":"e22abf5d9ff980101c2d4c531170c91c","cat":"fusha","type":"daily_conversation","level":"advanced","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"مَا هِوَايَتُكَ الْمُفَضَّلَةُ؟","explanation":"هِوَايَةٌ = hobi. Pertanyaan: \"Apa hobi favoritmu?\" Jawaban: \"Hobiku membaca buku.\"","time":30,"options":["هِوَايَتِي قِرَاءَةُ الْكُتُبِ.","أُفَضِّلُ الشَّايَ عَلَى الْقَهْوَةِ.","أَنَا لَاعِبٌ فِي الْفَرِيقِ.","أُحِبُّ أُسْرَتِي كَثِيرًا."],"correct":1,"accepted":[]},{"key":"68b239c32bc1cc3e3488c189425d579d","cat":"fusha","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Temanmu sakit. Kalimat doa yang tepat untuknya adalah …","ar":null,"explanation":"شَفَاكَ اللّٰهُ = semoga Allah menyembuhkanmu. رَحِمَكَ اللّٰهُ = semoga Allah merahmatimu (mis. setelah bersin).","time":25,"options":["شَفَاكَ اللّٰهُ.","رَحِمَكَ اللّٰهُ.","بَارَكَ اللّٰهُ فِيكَ.","هَدَاكَ اللّٰهُ."],"correct":1,"accepted":[]},{"key":"ce47ebb35e1d37e207309fe119ce4b10","cat":"fusha","type":"context_challenge","level":"advanced","variety":"fusha","prompt":"Kamu ingin menyampaikan pendapat dengan sopan dalam diskusi. Kalimat pembuka yang tepat adalah …","ar":null,"explanation":"فِي رَأْيِي = menurut pendapatku. Ungkapan lain: أَظُنُّ أَنَّ ... (saya kira ...). Pilihan lain tidak sopan atau menolak berbicara.","time":30,"options":["فِي رَأْيِي، ...","لَا أُرِيدُ أَنْ أَتَكَلَّمَ.","أَنْتَ مُخْطِئٌ دَائِمًا.","اُسْكُتْ مِنْ فَضْلِكَ."],"correct":1,"accepted":[]},{"key":"4882d5adf518d5ada93c74ae70f08640","cat":"fusha","type":"sentence_builder","level":"advanced","variety":"fusha","prompt":"Susun menjadi kalimat: \"Saya belajar bahasa Arab agar memahami Al-Qur'an.\"","ar":null,"explanation":"أَتَعَلَّمُ (saya belajar) + اللُّغَةَ الْعَرَبِيَّةَ (maf'ul bih + na'at) + لِأَفْهَمَ (lam ta'lil + mudhari' manshub) + الْقُرْآنَ (maf'ul bih).","time":45,"options":["أَتَعَلَّمُ","اللُّغَةَ","الْعَرَبِيَّةَ","لِأَفْهَمَ","الْقُرْآنَ"],"correct":null,"accepted":["أَتَعَلَّمُ اللُّغَةَ الْعَرَبِيَّةَ لِأَفْهَمَ الْقُرْآنَ"]},{"key":"7a6eb0ed4144ec08cbbe5f987cd73565","cat":"fusha","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? Pertanyaan مَاذَا تَفْعَلُ الْآنَ؟ artinya \"Apa yang sedang kamu lakukan sekarang?\"","ar":"مَاذَا تَفْعَلُ الْآنَ؟","explanation":"Benar. مَاذَا = apa, تَفْعَلُ = kamu lakukan, الْآنَ = sekarang.","time":25,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"a319b9d3b741bef9468f39c78a87b200","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"أَيْوَه","explanation":"أَيْوَه = ya (Fusha: نَعَمْ). Tidak = لَأْ.","time":20,"options":["Ya","Tidak","Mungkin","Nanti"],"correct":1,"accepted":[]},{"key":"794a932d196a681fc5452491903c8184","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"كِدَه","explanation":"كِدَه = begini/seperti ini (Fusha: هَكَذَا). Contoh: مِشْ كِدَه = bukan begitu.","time":20,"options":["Begini / seperti ini","Di sana","Sekarang","Sedikit"],"correct":1,"accepted":[]},{"key":"dd35cdb28b67b6c24a2da36cb731f84f","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"بِكَام دَه؟","explanation":"بِكَام = berapa (harga), دَه = ini (laki-laki). Fusha: بِكَمْ هَذَا؟","time":20,"options":["Berapa harga ini?","Apa ini?","Di mana ini?","Punya siapa ini?"],"correct":1,"accepted":[]},{"key":"7ea3b0461bab8c7c03255209ad316c96","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"كُوَيِّس","explanation":"كُوَيِّس = baik/bagus (Fusha: جَيِّدٌ). Contoh: أَنَا كُوَيِّس = saya baik-baik saja.","time":20,"options":["Baik / bagus","Buruk","Mahal","Jauh"],"correct":1,"accepted":[]},{"key":"7559af0a3943f2efe86d743515b3b209","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa padanan Fusha dari kata Amiyah ini?","ar":"عَشَان","explanation":"عَشَان (atau عَلَشَان) = karena / supaya, padanan Fusha لِأَنَّ atau مِنْ أَجْلِ.","time":25,"options":["لِأَنَّ / مِنْ أَجْلِ","لَكِنَّ","ثُمَّ","إِذَا"],"correct":1,"accepted":[]},{"key":"97fed272dd792088168a6a7366e6a737","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"بُكْرَه","explanation":"بُكْرَه = besok (Fusha: غَدًا). Kemarin = إِمْبَارِح, hari ini = النَّهَارْدَه.","time":25,"options":["Besok","Kemarin","Hari ini","Lusa"],"correct":1,"accepted":[]},{"key":"b088928c6019f7fa5b14621c839f5176","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"فِين الْحَمَّام؟","explanation":"فِين = di mana (Fusha: أَيْنَ). Jadi فِين الْحَمَّام = أَيْنَ الْحَمَّامُ؟","time":25,"options":["Di mana kamar mandi?","Kamar mandinya kotor?","Kapan mandi?","Siapa di kamar mandi?"],"correct":1,"accepted":[]},{"key":"0e8d7cf3c182dfbb0c767f15fabd2542","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa padanan Fusha dari kata Amiyah ini?","ar":"إِيه","explanation":"إِيه = apa (Fusha: مَا / مَاذَا). Contoh: إِنْتَ عَايِز إِيه؟ = مَاذَا تُرِيدُ؟","time":25,"options":["مَا / مَاذَا","مَنْ","أَيْنَ","كَيْفَ"],"correct":1,"accepted":[]},{"key":"a365d687166a5c6069fe90b8a8a158b3","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Pedagang di pasar Kairo berkata kepadamu. Maksudnya …","ar":"آخِر كَلَام","explanation":"آخِر كَلَام = kata terakhir. Dalam tawar-menawar artinya harga sudah final dan tidak bisa turun lagi.","time":30,"options":["Harga final, tidak bisa ditawar lagi","Pembicaraan dimulai","Silakan pilih dulu","Barangnya habis"],"correct":1,"accepted":[]},{"key":"2afc596b01d62e04b41d38fe6f0fd9d1","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"يَا رِيت","explanation":"يَا رِيت = andai saja/semoga (Fusha: لَيْتَ). Contoh: يَا رِيت تِيجِي بُكْرَه = semoga kamu datang besok.","time":30,"options":["Seandainya saja / semoga","Tentu saja","Hati-hati","Ayo cepat"],"correct":1,"accepted":[]},{"key":"3673bb20da8301bad0f755aeac52b82d","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Apa padanan Fusha dari kalimat Amiyah ini?","ar":"أَنَا مِشْ فَاهِم","explanation":"مِشْ = tidak, فَاهِم = paham (isim fa'il). Fusha: أَنَا لَا أَفْهَمُ.","time":30,"options":["أَنَا لَا أَفْهَمُ","أَنَا لَا أَعْرِفُ","أَنَا لَا أُرِيدُ","أَنَا لَمْ أَسْمَعْ"],"correct":1,"accepted":[]},{"key":"cb5fff0fb5249e5cda3696cb87d91d7a","cat":"mubtada-khabar","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"[[اللّٰهُ]] رَحِيمٌ","explanation":"Lafzhul jalalah اللّٰهُ di awal jumlah ismiyyah adalah mubtada', marfu' dengan dhammah. رَحِيمٌ adalah khabarnya.","time":20,"options":["Mubtada' marfu' dengan dhammah","Khabar marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Badal marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"27961ea33698307f15b68d818a40929b","cat":"mubtada-khabar","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"الطَّالِبَانِ [[حَاضِرَانِ]]","explanation":"حَاضِرَانِ adalah khabar bagi الطَّالِبَانِ. Isim mutsanna di-rafa'-kan dengan alif sebagai pengganti dhammah.","time":20,"options":["Khabar marfu' dengan alif karena mutsanna","Mubtada' marfu' dengan alif","Na'at marfu' dengan alif","Khabar marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"42e021dc95239640c6f9ab63f07a6324","cat":"mubtada-khabar","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"[[الْمُسْلِمُونَ]] إِخْوَةٌ","explanation":"الْمُسْلِمُونَ adalah mubtada'. Jamak mudzakkar salim di-rafa'-kan dengan wawu. إِخْوَةٌ adalah khabarnya.","time":25,"options":["Mubtada' marfu' dengan wawu karena jamak mudzakkar salim","Mubtada' marfu' dengan dhammah","Fa'il marfu' dengan wawu","Khabar marfu' dengan wawu"],"correct":1,"accepted":[]},{"key":"e3879a146b805aa73db12ce09f577556","cat":"mubtada-khabar","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Khabar pada kalimat berikut berbentuk …","ar":"الْكِتَابُ عَلَى الْمَكْتَبِ","explanation":"Khabarnya عَلَى الْمَكْتَبِ: huruf jar + isim majrur, disebut syibhu jumlah. Ia berkaitan dengan khabar yang dibuang (مَوْجُودٌ/كَائِنٌ).","time":25,"options":["Syibhu jumlah (jar-majrur)","Mufrad","Jumlah fi'liyyah","Jumlah ismiyyah"],"correct":1,"accepted":[]},{"key":"ce6af401573e746b2325685e7345ffc1","cat":"mubtada-khabar","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Khabar pada kalimat berikut berbentuk …","ar":"زَيْدٌ أَبُوهُ كَرِيمٌ","explanation":"Khabar dari زَيْدٌ adalah jumlah أَبُوهُ كَرِيمٌ (mubtada' kedua + khabarnya), yaitu jumlah ismiyyah yang menempati posisi rafa'. Dhamir هُ menghubungkannya dengan mubtada'.","time":30,"options":["Jumlah ismiyyah","Mufrad","Jumlah fi'liyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"85486b55f9889e2be2ae47889f3ac11e","cat":"mubtada-khabar","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH? (Perhatikan kesesuaian mubtada' dan khabar.)","ar":null,"explanation":"Khabar mufrad harus sesuai dengan mubtada' dalam jenis. الْبِنْتُ muannats, maka khabarnya مُجْتَهِدَةٌ. Jadi الْبِنْتُ مُجْتَهِدٌ salah.","time":25,"options":["الْبِنْتُ مُجْتَهِدٌ","الْبِنْتُ مُجْتَهِدَةٌ","الْوَلَدُ مُجْتَهِدٌ","الْبَنَاتُ مُجْتَهِدَاتٌ"],"correct":1,"accepted":[]},{"key":"0d7c36ef9d7ce6b771579704398da292","cat":"fail","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"قَرَأَ [[الطَّالِبُ]] الْقُرْآنَ","explanation":"الطَّالِبُ adalah pelaku perbuatan قَرَأَ, maka fa'il, marfu' dengan dhammah.","time":20,"options":["Fa'il marfu' dengan dhammah","Maf'ul bih manshub dengan fathah","Mubtada' marfu' dengan dhammah","Na'at marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"0c6598694f108f4f4b5f974d690bb5da","cat":"fail","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"حَضَرَ [[الْمُعَلِّمَانِ]]","explanation":"الْمُعَلِّمَانِ adalah fa'il dari حَضَرَ. Mutsanna di-rafa'-kan dengan alif.","time":25,"options":["Fa'il marfu' dengan alif karena mutsanna","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan alif","Maf'ul bih manshub dengan ya'"],"correct":1,"accepted":[]},{"key":"73a9bba4b1c8dd6c76073b8cd1c9ca69","cat":"fail","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ [[أَبُوكَ]]","explanation":"أَبُوكَ termasuk al-asma' al-khamsah (أَبٌ، أَخٌ، حَمٌ، فُو، ذُو) yang di-rafa'-kan dengan wawu jika di-idhafah-kan selain kepada ya' mutakallim. Kedudukannya fa'il.","time":30,"options":["Fa'il marfu' dengan wawu karena asmaul khamsah","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan wawu","Fa'il marfu' dengan wawu karena jamak"],"correct":1,"accepted":[]},{"key":"15b4dfec2a83251ff0f7a599bd5cecb9","cat":"fail","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih fi'il yang tepat untuk melengkapi kalimat.","ar":"ـــــ الطَّالِبَاتُ الدَّرْسَ","explanation":"Jika fa'il berupa isim zhahir, fi'il tetap mufrad meskipun fa'il-nya jamak. Fa'il-nya muannats, maka fi'il diberi ta' ta'nits: كَتَبَتِ الطَّالِبَاتُ (ta' dikasrah karena bertemu sukun).","time":25,"options":["كَتَبَتِ","كَتَبْنَ","كَتَبُوا","كَتَبَا"],"correct":1,"accepted":[]},{"key":"c12e18431f969abe4dea1908a595ea27","cat":"fail","type":"grammar_detective","level":"advanced","variety":"fusha","prompt":"Kalimat manakah yang SALAH? (Perhatikan bentuk fi'il sebelum fa'il jamak.)","ar":null,"explanation":"Dalam bahasa Arab fusha, fi'il yang fa'il-nya isim zhahir tetap mufrad: ذَهَبَ الطُّلَّابُ. Bentuk ذَهَبُوا الطُّلَّابُ (lughah akaluni al-baraghits) tidak dipakai dalam bahasa standar. Jika fa'il disebut lebih dulu, fi'il mengikuti: الطُّلَّابُ ذَهَبُوا.","time":30,"options":["ذَهَبُوا الطُّلَّابُ","ذَهَبَ الطُّلَّابُ","الطُّلَّابُ ذَهَبُوا","ذَهَبَتِ الطَّالِبَاتُ"],"correct":1,"accepted":[]},{"key":"260354b45c588974335cd41b5ed71877","cat":"maful-bih","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"شَرِبَ الْوَلَدُ [[الْحَلِيبَ]]","explanation":"الْحَلِيبَ adalah yang dikenai perbuatan شَرِبَ, maka maf'ul bih, manshub dengan fathah.","time":20,"options":["Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan dhammah","Khabar marfu' dengan dhammah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"3dd8b695c1634842258a04acfe4c3769","cat":"maful-bih","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"زُرْتُ [[أَخَاكَ]]","explanation":"أَخَاكَ adalah maf'ul bih. أَخٌ termasuk al-asma' al-khamsah yang di-nashab-kan dengan alif.","time":25,"options":["Maf'ul bih manshub dengan alif karena asmaul khamsah","Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan alif","Maf'ul bih manshub dengan alif karena mutsanna"],"correct":1,"accepted":[]},{"key":"5b93e706dbb4ec91145b40af92a87fe3","cat":"maful-bih","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"قَرَأْتُ [[كِتَابَيْنِ]]","explanation":"كِتَابَيْنِ adalah maf'ul bih berbentuk mutsanna, di-nashab-kan dengan ya' (sebelumnya fathah: ـَيْنِ). Jamak mudzakkar salim diakhiri ـِينَ (kasrah sebelum ya').","time":25,"options":["Maf'ul bih manshub dengan ya' karena mutsanna","Maf'ul bih manshub dengan ya' karena jamak mudzakkar salim","Isim majrur dengan ya'","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"731c219a678f72640366e2e0dd1ed92c","cat":"maful-bih","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"[[إِيَّاكَ]] نَعْبُدُ","explanation":"إِيَّاكَ adalah dhamir munfashil untuk nashab. Ia maf'ul bih bagi نَعْبُدُ yang didahulukan untuk pengkhususan (hashr): hanya kepada-Mu kami menyembah. Dhamir itu mabni, jadi i'rabnya mahalli.","time":30,"options":["Maf'ul bih muqaddam, dhamir munfashil mabni fi mahalli nashb","Mubtada' mabni fi mahalli raf'","Fa'il mabni fi mahalli raf'","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"2554a817fe2c89c2fdb23945f96dd54f","cat":"maful-bih","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH? (Perhatikan tanda nashab maf'ul bih.)","ar":null,"explanation":"Maf'ul bih jamak mudzakkar salim harus manshub dengan ya': الْمُعَلِّمِينَ. Bentuk الْمُعَلِّمُونَ (dengan wawu) adalah bentuk rafa'.","time":25,"options":["رَأَيْتُ الْمُعَلِّمُونَ","رَأَيْتُ الْمُعَلِّمِينَ","رَأَيْتُ الْمُعَلِّمَ","رَأَيْتُ الْمُعَلِّمَاتِ"],"correct":1,"accepted":[]},{"key":"adfbf7043e5bd7b1618dd3ddc47403b3","cat":"naat","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"هَذِهِ سَيَّارَةٌ [[جَدِيدَةٌ]]","explanation":"جَدِيدَةٌ adalah na'at bagi سَيَّارَةٌ (khabar yang marfu'), maka ikut marfu', muannats, dan nakirah.","time":20,"options":["Na'at marfu' dengan dhammah","Khabar marfu' dengan dhammah","Hal manshub dengan fathah","Mubtada' marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"3e4d7bcb90333ea95d926c449c76c0f6","cat":"naat","type":"nahwu_battle","level":"beginner","variety":"fusha","prompt":"Pilih na'at yang tepat untuk melengkapi kalimat.","ar":"جَاءَ الطَّالِبُ ـــــ","explanation":"Man'ut الطَّالِبُ ma'rifah, marfu', mudzakkar. Na'at harus sama dalam ketiganya: الْمُجْتَهِدُ. مُجْتَهِدٌ (nakirah) di sini menjadi hal jika manshub (مُجْتَهِدًا).","time":20,"options":["الْمُجْتَهِدُ","مُجْتَهِدٌ","الْمُجْتَهِدَ","الْمُجْتَهِدَةُ"],"correct":1,"accepted":[]},{"key":"5a44fd0ba06a082a63ba0000ac7f5105","cat":"naat","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih na'at yang tepat untuk melengkapi kalimat.","ar":"سَلَّمْتُ عَلَى الْمُدَرِّسَاتِ ـــــ","explanation":"الْمُدَرِّسَاتِ majrur (setelah عَلَى), ma'rifah, jamak muannats. Na'at-nya mengikuti: الْفَاضِلَاتِ (majrur dengan kasrah).","time":25,"options":["الْفَاضِلَاتِ","الْفَاضِلَاتُ","فَاضِلَاتٍ","الْفَاضِلِينَ"],"correct":1,"accepted":[]},{"key":"96ac4b2e42f2d77efa9ec646a8cc7e73","cat":"naat","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"رَأَيْتُ رَجُلًا [[يَقْرَأُ]] الْقُرْآنَ","explanation":"Jumlah setelah isim nakirah (رَجُلًا) menjadi na'at baginya. Jumlah يَقْرَأُ الْقُرْآنَ menempati posisi nashab mengikuti رَجُلًا. Kaidah: الْجُمَلُ بَعْدَ النَّكِرَاتِ صِفَاتٌ.","time":30,"options":["Jumlah fi'liyyah sebagai na'at fi mahalli nashb","Fi'il mudhari' sebagai hal manshub","Maf'ul bih kedua manshub","Khabar fi mahalli raf'"],"correct":1,"accepted":[]},{"key":"8c4711019a39e2f9ee4edbfc301b91fa","cat":"idhafah","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"هَذَا بَابُ [[الْبَيْتِ]]","explanation":"الْبَيْتِ adalah mudhaf ilaih dari بَابُ. Mudhaf ilaih selalu majrur, tandanya kasrah.","time":20,"options":["Mudhaf ilaih majrur dengan kasrah","Isim majrur dengan huruf jar","Na'at majrur dengan kasrah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"3e5263632f1a87531bddf8ac4a58970f","cat":"idhafah","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"هَذَا [[كِتَابُ]] الطَّالِبِ","explanation":"هَذَا mubtada', كِتَابُ khabar marfu'. Ia juga mudhaf, karena itu tanpa tanwin dan tanpa ال. الطَّالِبِ mudhaf ilaih.","time":25,"options":["Khabar marfu' dengan dhammah dan sebagai mudhaf","Mubtada' marfu' dengan dhammah","Mudhaf ilaih majrur","Badal marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"56ad0f81093743b8fed614f71a3747e3","cat":"idhafah","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"سَافَرْتُ مَعَ [[أَبِي]]","explanation":"مَعَ bukan huruf jar, melainkan zharaf yang menjadi mudhaf; maka أَبِي adalah mudhaf ilaih (majrur). Karena di-idhafah-kan ke ya' mutakallim, أَبٌ tidak di-i'rab dengan huruf seperti asmaul khamsah. Tanda jarr-nya kasrah muqaddarah: huruf akhirnya sudah ditempati kasrah yang menyesuaikan ya'.","time":30,"options":["Mudhaf ilaih majrur dengan kasrah muqaddarah","Isim majrur dengan ya' karena asmaul khamsah","Isim majrur oleh huruf jar مَعَ","Maf'ul ma'ah manshub"],"correct":1,"accepted":[]},{"key":"e909368b5ce81dcb7453b55de9a65516","cat":"idhafah","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH? (Perhatikan bentuk mudhaf.)","ar":null,"explanation":"Mudhaf tidak boleh bertanwin. Yang benar قَلَمُ مُحَمَّدٍ. Pada قَلَمٌ مُحَمَّدٍ, tanwin pada قَلَمٌ memutus idhafah.","time":25,"options":["هَذَا قَلَمٌ مُحَمَّدٍ","هَذَا قَلَمُ مُحَمَّدٍ","هَذَا قَلَمٌ جَمِيلٌ","هَذَا قَلَمُ الْأُسْتَاذِ"],"correct":1,"accepted":[]},{"key":"d19ff7b49e95de4efc42bf695d6ec268","cat":"idhafah","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"جَاءَ ـــــ الْمَدْرَسَةِ","explanation":"Kata yang kosong adalah fa'il (marfu') sekaligus mudhaf, maka tanpa ال dan tanpa tanwin: مُدِيرُ الْمَدْرَسَةِ.","time":25,"options":["مُدِيرُ","الْمُدِيرُ","مُدِيرٌ","مُدِيرَ"],"correct":1,"accepted":[]},{"key":"598bef36ff08ff98a2731478ff399837","cat":"hal","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ الطَّالِبُ [[مُسْرِعًا]]","explanation":"مُسْرِعًا menjelaskan keadaan fa'il ketika datang (dengan tergesa-gesa). Hal adalah isim nakirah manshub.","time":20,"options":["Hal manshub dengan fathah","Maf'ul bih manshub dengan fathah","Na'at manshub dengan fathah","Tamyiz manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"26cfae88b2ebdd2de5f54436c9110fec","cat":"hal","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"رَجَعَتِ الْبِنْتُ مِنَ الْمَدْرَسَةِ [[فَرِحَةً]]","explanation":"فَرِحَةً menerangkan keadaan الْبِنْتُ (shahibul hal) saat kembali: dalam keadaan gembira. Hal sesuai dengan shahibul hal dalam jenis (muannats).","time":25,"options":["Hal manshub dengan fathah","Na'at manshub dengan fathah","Khabar manshub dengan fathah","Maf'ul li ajlih manshub"],"correct":1,"accepted":[]},{"key":"39f7f977a2fb99179e8ee4317a8d7ade","cat":"hal","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih hal yang tepat untuk melengkapi kalimat.","ar":"دَخَلَ الطُّلَّابُ الْفَصْلَ ـــــ","explanation":"Hal harus nakirah, manshub, dan sesuai shahibul hal (الطُّلَّابُ, jamak mudzakkar): مُبْتَسِمِينَ (manshub dengan ya').","time":25,"options":["مُبْتَسِمِينَ","مُبْتَسِمُونَ","الْمُبْتَسِمِينَ","مُبْتَسِمٌ"],"correct":1,"accepted":[]},{"key":"4bc799abf003b093adb8751dbe297e83","cat":"hal","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Kata yang ditandai pada kalimat berikut berkedudukan sebagai …","ar":"جَاءَ زَيْدٌ [[وَالشَّمْسُ طَالِعَةٌ]]","explanation":"وَالشَّمْسُ طَالِعَةٌ adalah jumlah ismiyyah yang menjelaskan keadaan saat Zaid datang (ketika matahari terbit). Wawu-nya disebut wawu haliyah. Jumlah ini fi mahalli nashb sebagai hal.","time":30,"options":["Hal berupa jumlah ismiyyah","Na'at berupa jumlah","Khabar kedua","Ma'thuf dengan wawu"],"correct":1,"accepted":[]},{"key":"656157a78d0026b0433f4cf4f8f5aacc","cat":"tamyiz","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"اِشْتَرَيْتُ كِيلُو [[سُكَّرًا]]","explanation":"سُكَّرًا menjelaskan jenis takaran كِيلُو yang samar (satu kilo apa?), maka tamyiz, manshub. Boleh juga dibaca majrur sebagai mudhaf ilaih: كِيلُو سُكَّرٍ.","time":20,"options":["Tamyiz manshub dengan fathah","Maf'ul bih manshub dengan fathah","Hal manshub dengan fathah","Na'at manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"c01e84e0107e1c39cbe3fad2b025b59d","cat":"tamyiz","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"فِي الْفَصْلِ عِشْرُونَ [[طَالِبًا]]","explanation":"Tamyiz bilangan 11–99 adalah isim mufrad yang manshub: عِشْرُونَ طَالِبًا.","time":25,"options":["Tamyiz manshub dengan fathah","Mudhaf ilaih majrur","Hal manshub dengan fathah","Badal marfu'"],"correct":1,"accepted":[]},{"key":"87f81fa80d7b353cff935eae01daaab5","cat":"tamyiz","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"مُحَمَّدٌ أَكْثَرُ مِنْكَ [[عِلْمًا]]","explanation":"عِلْمًا menjelaskan sisi kelebihan yang samar pada isim tafdhil أَكْثَرُ (lebih banyak dalam hal apa?). Ini tamyiz nisbah, manshub.","time":30,"options":["Tamyiz manshub dengan fathah","Hal manshub dengan fathah","Maf'ul bih manshub","Maf'ul muthlaq manshub"],"correct":1,"accepted":[]},{"key":"69001012eead66220f80c4b9683ed13b","cat":"tamyiz","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih tamyiz yang tepat untuk melengkapi kalimat.","ar":"قَرَأْتُ أَحَدَ عَشَرَ ـــــ","explanation":"Tamyiz bilangan 11–99 berupa isim mufrad manshub: أَحَدَ عَشَرَ كِتَابًا.","time":25,"options":["كِتَابًا","كُتُبًا","كِتَابٍ","كُتُبٍ"],"correct":1,"accepted":[]},{"key":"a1895db7d45c3b328bd405afd95446f9","cat":"nawasikh","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"كَانَ [[الْجَوُّ]] حَارًّا","explanation":"كَانَ me-rafa'-kan isimnya dan me-nashab-kan khabarnya. الْجَوُّ adalah isim kana (marfu'), حَارًّا khabar kana (manshub).","time":20,"options":["Isim kana marfu' dengan dhammah","Khabar kana manshub","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"48980216d77c3c9061572f4521013631","cat":"nawasikh","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"إِنَّ [[الصَّلَاةَ]] عِمَادُ الدِّينِ","explanation":"إِنَّ me-nashab-kan isimnya dan me-rafa'-kan khabarnya. الصَّلَاةَ isim inna (manshub), عِمَادُ khabar inna (marfu').","time":20,"options":["Isim inna manshub dengan fathah","Khabar inna marfu'","Maf'ul bih manshub","Mubtada' marfu'"],"correct":1,"accepted":[]},{"key":"b82142bb2953c516391ebb90ae77b82b","cat":"nawasikh","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"أَصْبَحَ الطُّلَّابُ [[نَشِيطِينَ]]","explanation":"أَصْبَحَ termasuk saudara kana. نَشِيطِينَ adalah khabarnya, manshub dengan ya' karena jamak mudzakkar salim.","time":25,"options":["Khabar ashbaha manshub dengan ya' karena jamak mudzakkar salim","Hal manshub dengan ya'","Isim ashbaha marfu' dengan wawu","Na'at manshub dengan ya'"],"correct":1,"accepted":[]},{"key":"3efe66a02ea9c6d075ba3561b879e316","cat":"nawasikh","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَيْسَ الطَّالِبُ [[كَسْلَانَ]]","explanation":"لَيْسَ beramal seperti kana. كَسْلَانَ khabarnya, manshub dengan fathah tanpa tanwin karena mamnu' min ash-sharf (wazan فَعْلَانُ yang muannatsnya فَعْلَى).","time":25,"options":["Khabar laisa manshub dengan fathah","Isim laisa marfu'","Hal manshub dengan fathah","Khabar laisa majrur"],"correct":1,"accepted":[]},{"key":"8eef363ced3728c2dbbca0113751a8e3","cat":"nawasikh","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"كَانَ الطَّالِبَانِ ـــــ","explanation":"Yang kosong adalah khabar kana, maka manshub. Khabarnya mutsanna (sesuai الطَّالِبَانِ), di-nashab-kan dengan ya': مُجْتَهِدَيْنِ.","time":25,"options":["مُجْتَهِدَيْنِ","مُجْتَهِدَانِ","مُجْتَهِدِينَ","مُجْتَهِدًا"],"correct":1,"accepted":[]},{"key":"d96b3d50aa704f71186f08730ca94a9b","cat":"nawasikh","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"لَعَلَّ ـــــ قَرِيبٌ","explanation":"لَعَلَّ termasuk saudara inna (berarti harapan/semoga). Isimnya manshub: لَعَلَّ الْفَرَجَ قَرِيبٌ.","time":30,"options":["الْفَرَجَ","الْفَرَجُ","الْفَرَجِ","فَرَجٌ"],"correct":1,"accepted":[]},{"key":"2fef49d2025bef37efff52fb19280994","cat":"nawasikh","type":"grammar_detective","level":"advanced","variety":"fusha","prompt":"Kalimat manakah yang SALAH? (Perhatikan i'rab isim inna.)","ar":null,"explanation":"Isim inna harus manshub: إِنَّ الطَّالِبَ مُجْتَهِدٌ. Maka إِنَّ الطَّالِبُ salah.","time":30,"options":["إِنَّ الطَّالِبُ مُجْتَهِدٌ","إِنَّ الطَّالِبَ مُجْتَهِدٌ","كَانَ الطَّالِبُ مُجْتَهِدًا","لَيْتَ الطَّالِبَ مُجْتَهِدٌ"],"correct":1,"accepted":[]},{"key":"b1453bc6d2ef967c5e3571a983c3ae9f","cat":"majrurat","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَلَسْتُ فِي [[الْحَدِيقَةِ]]","explanation":"فِي adalah huruf jar, maka الْحَدِيقَةِ isim majrur dengan kasrah.","time":20,"options":["Isim majrur dengan kasrah karena huruf jar","Mudhaf ilaih majrur","Maf'ul fih manshub","Na'at majrur"],"correct":1,"accepted":[]},{"key":"bcc7593e304c9c5224693e8a00d4c844","cat":"majrurat","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"سَلَّمْتُ عَلَى [[إِبْرَاهِيمَ]]","explanation":"إِبْرَاهِيمَ majrur oleh عَلَى. Nama non-Arab ('ajam) termasuk mamnu' min ash-sharf, sehingga di-jarr-kan dengan fathah sebagai pengganti kasrah.","time":25,"options":["Isim majrur dengan fathah karena mamnu' min ash-sharf","Isim majrur dengan kasrah","Maf'ul bih manshub dengan fathah","Badal manshub"],"correct":1,"accepted":[]},{"key":"c0239c92c3f10190c6c1bb0bb66911d7","cat":"majrurat","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"مَرَرْتُ بِـ[[الْمُسْلِمِينَ]]","explanation":"الْمُسْلِمِينَ majrur oleh huruf jar بِـ. Jamak mudzakkar salim di-jarr-kan dengan ya'.","time":25,"options":["Isim majrur dengan ya' karena jamak mudzakkar salim","Maf'ul bih manshub dengan ya'","Isim majrur dengan kasrah","Mudhaf ilaih majrur dengan ya'"],"correct":1,"accepted":[]},{"key":"2aa86d374517a1c922d0c7d7285b52fe","cat":"majrurat","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"صَلَّيْتُ فِي ـــــ كَثِيرَةٍ","explanation":"مَسَاجِدُ berwazan shighah muntahal jumu' (مَفَاعِلُ), termasuk mamnu' min ash-sharf. Saat nakirah dan majrur, tandanya fathah tanpa tanwin: فِي مَسَاجِدَ كَثِيرَةٍ.","time":30,"options":["مَسَاجِدَ","مَسَاجِدِ","مَسَاجِدٍ","مَسَاجِدُ"],"correct":1,"accepted":[]},{"key":"00cdfdda3bf29fc5f03e7ba4ba52d539","cat":"tawabi","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ مُحَمَّدٌ [[وَعَلِيٌّ]]","explanation":"عَلِيٌّ di-'athaf-kan dengan wawu kepada مُحَمَّدٌ (fa'il), maka ikut marfu'. Ini 'athaf, salah satu tawabi'.","time":25,"options":["Ma'thuf marfu' dengan dhammah (mengikuti fa'il)","Mubtada' marfu'","Na'at marfu'","Maf'ul ma'ah manshub"],"correct":1,"accepted":[]},{"key":"8334e5c57b3afe6ac613f617be5b893f","cat":"tawabi","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"حَضَرَ الضُّيُوفُ [[جَمِيعُهُمْ]]","explanation":"جَمِيعُهُمْ menguatkan الضُّيُوفُ agar dipahami semuanya hadir. Ini taukid ma'nawi, mengikuti yang dikuatkan (marfu').","time":25,"options":["Taukid marfu' dengan dhammah","Badal marfu'","Na'at marfu'","Mubtada' marfu'"],"correct":1,"accepted":[]},{"key":"a7e8f333ccd488a83d542798ac68ff45","cat":"tawabi","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"قَرَأْتُ الْكِتَابَ [[نِصْفَهُ]]","explanation":"نِصْفَهُ (separuhnya) adalah sebagian dari الْكِتَابَ, maka badal ba'dh min kull. Ia mengikuti mubdal minhu yang manshub dan wajib memuat dhamir yang kembali kepadanya.","time":30,"options":["Badal ba'dh min kull manshub dengan fathah","Taukid manshub","Na'at manshub","Hal manshub"],"correct":1,"accepted":[]},{"key":"cd7ac23704c6d3730b39cce3d363ea5d","cat":"tawabi","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih ma'thuf yang tepat untuk melengkapi kalimat.","ar":"رَأَيْتُ زَيْدًا ثُمَّ ـــــ","explanation":"ثُمَّ adalah huruf 'athaf (berurutan dengan jeda). Ma'thuf mengikuti ma'thuf 'alaih زَيْدًا yang manshub: عَمْرًا.","time":25,"options":["عَمْرًا","عَمْرٌو","عَمْرٍو","لِعَمْرٍو"],"correct":1,"accepted":[]},{"key":"585d9c9c35099403e91a6c9006d0222c","cat":"anwa-jumal","type":"sentence_analysis","level":"beginner","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"الْمَسْجِدُ نَظِيفٌ","explanation":"Diawali isim (الْمَسْجِدُ, mubtada') dan diikuti khabar (نَظِيفٌ), maka jumlah ismiyyah.","time":20,"options":["Jumlah ismiyyah","Jumlah fi'liyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"00bd34d248df7768cff924c7035706f5","cat":"anwa-jumal","type":"sentence_analysis","level":"beginner","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"نَزَلَ الْمَطَرُ","explanation":"Diawali fi'il (نَزَلَ) lalu fa'il (الْمَطَرُ), maka jumlah fi'liyyah.","time":20,"options":["Jumlah fi'liyyah","Jumlah ismiyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"ebf76aee4eecaaa47aa589b37a80cdb0","cat":"anwa-jumal","type":"sentence_analysis","level":"intermediate","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"الطَّالِبُ يَكْتُبُ الدَّرْسَ","explanation":"Jenis jumlah ditentukan oleh kata pertama. Diawali isim (الطَّالِبُ) sebagai mubtada', maka jumlah ismiyyah. يَكْتُبُ الدَّرْسَ adalah khabarnya yang berbentuk jumlah fi'liyyah.","time":25,"options":["Jumlah ismiyyah","Jumlah fi'liyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"5d476448b9a3980e456771f482b60314","cat":"anwa-jumal","type":"sentence_analysis","level":"intermediate","variety":"fusha","prompt":"Termasuk apakah susunan berikut?","ar":"فِي الْفَصْلِ","explanation":"Susunan huruf jar + isim majrur (atau zharaf + mudhaf ilaih) disebut syibhu jumlah (menyerupai kalimat). Ia belum menjadi kalimat sempurna.","time":25,"options":["Syibhu jumlah","Jumlah ismiyyah","Jumlah fi'liyyah"],"correct":1,"accepted":[]},{"key":"a771ac4d2d71171607bf03d536f9bb42","cat":"anwa-jumal","type":"identify_word","level":"beginner","variety":"fusha","prompt":"Kata yang ditandai termasuk jenis kalimah apa?","ar":"الطَّالِبُ [[يَدْرُسُ]]","explanation":"يَدْرُسُ adalah fi'il mudhari': menunjukkan perbuatan dan waktu, diawali huruf mudhara'ah يَـ.","time":20,"options":["Fi'il","Isim","Huruf"],"correct":1,"accepted":[]},{"key":"6b02750ae36e4c829cd29aa8e6ce9caf","cat":"anwa-jumal","type":"identify_word","level":"intermediate","variety":"fusha","prompt":"Kata yang ditandai termasuk jenis kalimah apa?","ar":"[[هُوَ]] طَالِبٌ","explanation":"هُوَ adalah dhamir (kata ganti), dan dhamir termasuk isim. Ia mabni dan di sini berkedudukan sebagai mubtada'.","time":25,"options":["Isim","Huruf","Fi'il"],"correct":1,"accepted":[]},{"key":"07173dbdf9ea47395c3e44a9bdc5807f","cat":"anwa-jumal","type":"identify_word","level":"advanced","variety":"fusha","prompt":"Kata yang ditandai termasuk jenis kalimah apa?","ar":"[[نِعْمَ]] الرَّجُلُ زَيْدٌ","explanation":"نِعْمَ adalah fi'il madhi jamid untuk memuji. Buktinya ia menerima ta' ta'nits sakinah: نِعْمَتِ الْمَرْأَةُ.","time":30,"options":["Fi'il","Isim","Huruf"],"correct":1,"accepted":[]},{"key":"932e7750872ca419eb4472b15f45cb6b","cat":"madhi","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk fi'il apa?","ar":"ذَهَبَ","explanation":"ذَهَبَ adalah fi'il madhi: menunjukkan perbuatan lampau dan diakhiri fathah.","time":20,"options":["Fi'il madhi","Fi'il mudhari'","Fi'il amr"],"correct":1,"accepted":[]},{"key":"0f585b89decd018dccd7e0428a673385","cat":"madhi","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Ubah ذَهَبَ untuk dhamir أَنَا.","ar":null,"explanation":"أَنَا → ta' fa'il berharakat dhammah: ذَهَبْتُ. ذَهَبْتَ untuk أَنْتَ, ذَهَبَتْ untuk هِيَ, ذَهَبْنَا untuk نَحْنُ.","time":20,"options":["ذَهَبْتُ","ذَهَبْتَ","ذَهَبَتْ","ذَهَبْنَا"],"correct":1,"accepted":[]},{"key":"910ae32149536927d4e98f826f2283bf","cat":"madhi","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Ubah جَلَسَ untuk dhamir نَحْنُ.","ar":null,"explanation":"نَحْنُ → nun-alif (نَا fa'il), huruf sebelumnya disukunkan: جَلَسْنَا. جَلَسُوا untuk هُمْ, جَلَسْتُمْ untuk أَنْتُمْ, جَلَسْنَ untuk هُنَّ.","time":25,"options":["جَلَسْنَا","جَلَسُوا","جَلَسْتُمْ","جَلَسْنَ"],"correct":1,"accepted":[]},{"key":"b25de704d5a42b60a8c90022168ff63c","cat":"madhi","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Ubah فَتَحَ untuk dhamir هُمَا (dua orang laki-laki).","ar":null,"explanation":"هُمَا (mudzakkar) → alif itsnain: فَتَحَا. فَتَحَتَا untuk هُمَا muannats, فَتَحْتُمَا untuk أَنْتُمَا, فَتَحُوا untuk هُمْ.","time":25,"options":["فَتَحَا","فَتَحَتَا","فَتَحْتُمَا","فَتَحُوا"],"correct":1,"accepted":[]},{"key":"109c51f18e091dbbf7e6cd0f66521506","cat":"madhi","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Ubah دَعَا untuk dhamir أَنَا.","ar":null,"explanation":"دَعَا fi'il naqish wawi (asal دَعَوَ). Saat bersambung dengan ta' fa'il, alifnya kembali ke asal wawu: دَعَوْتُ.","time":30,"options":["دَعَوْتُ","دَعَيْتُ","دَعْتُ","دَعَاتُ"],"correct":1,"accepted":[]},{"key":"7ea7170d9b5c0b03381c5f681550f819","cat":"madhi","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Ubah بَاعَ untuk dhamir أَنْتَ.","ar":null,"explanation":"بَاعَ ajwaf ya'i (asal بَيَعَ). Saat lam fi'il disukunkan karena ta' fa'il, alif dibuang dan fa' fi'il dikasrah sebagai tanda asal ya': بِعْتَ.","time":30,"options":["بِعْتَ","بُعْتَ","بَاعْتَ","بَيَعْتَ"],"correct":1,"accepted":[]},{"key":"f7a2460688efadd783ed9a573d09d0bb","cat":"mudhari","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk fi'il apa?","ar":"يَشْرَبُ","explanation":"يَشْرَبُ fi'il mudhari': diawali huruf mudhara'ah (أ، ن، ي، ت) dan menunjukkan waktu sekarang/akan datang.","time":20,"options":["Fi'il mudhari'","Fi'il madhi","Fi'il amr"],"correct":1,"accepted":[]},{"key":"7d4aac72efc7bef82d349ac3e797e258","cat":"mudhari","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa fi'il mudhari' dari جَلَسَ untuk dhamir أَنَا?","ar":null,"explanation":"أَنَا → huruf mudhara'ah أَ: أَجْلِسُ (bab ضَرَبَ – يَضْرِبُ, 'ain mudhari' dikasrah).","time":20,"options":["أَجْلِسُ","يَجْلِسُ","نَجْلِسُ","تَجْلِسُ"],"correct":1,"accepted":[]},{"key":"7884af05a02129012a847a62498785bc","cat":"mudhari","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il mudhari' dari كَتَبَ untuk dhamir أَنْتُمْ?","ar":null,"explanation":"أَنْتُمْ → تَـ + wawu jama'ah + nun: تَكْتُبُونَ. يَكْتُبُونَ untuk هُمْ, تَكْتُبْنَ untuk أَنْتُنَّ, تَكْتُبَانِ untuk أَنْتُمَا.","time":25,"options":["تَكْتُبُونَ","يَكْتُبُونَ","تَكْتُبْنَ","تَكْتُبَانِ"],"correct":1,"accepted":[]},{"key":"c6015772a91d90d5d2ba701d688fc4c9","cat":"mudhari","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il mudhari' dari دَرَسَ untuk dhamir أَنْتِ?","ar":null,"explanation":"أَنْتِ → تَـ + ya' mukhathabah + nun: تَدْرُسِينَ. تَدْرُسُ untuk أَنْتَ/هِيَ, تَدْرُسْنَ untuk أَنْتُنَّ.","time":25,"options":["تَدْرُسِينَ","تَدْرُسُ","يَدْرُسْنَ","تَدْرُسْنَ"],"correct":1,"accepted":[]},{"key":"b286367c60e0316bc1d299d37a2e8ad5","cat":"mudhari","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il mudhari' dari قَالَ untuk dhamir هُوَ?","ar":null,"explanation":"قَالَ ajwaf wawi (asal قَوَلَ), mudhari'-nya يَقُولُ (asal يَقْوُلُ, harakat wawu dipindahkan ke qaf).","time":30,"options":["يَقُولُ","يَقِيلُ","يَقَالُ","يَقْوُلُ"],"correct":1,"accepted":[]},{"key":"f1dc00a8b6756eb43a32d4da877f4673","cat":"mudhari","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il mudhari' dari عَلَّمَ untuk dhamir هُوَ?","ar":null,"explanation":"عَلَّمَ berwazan فَعَّلَ, mudhari'-nya يُفَعِّلُ: يُعَلِّمُ (huruf mudhara'ah didhammah). يَعْلَمُ dari عَلِمَ, يَتَعَلَّمُ dari تَعَلَّمَ, يُعْلِمُ dari أَعْلَمَ.","time":30,"options":["يُعَلِّمُ","يَعْلَمُ","يَتَعَلَّمُ","يُعْلِمُ"],"correct":1,"accepted":[]},{"key":"f6d5e70dc8dfbc15e6ac7049b23b85af","cat":"amr","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk fi'il apa?","ar":"اِجْلِسْ","explanation":"اِجْلِسْ adalah fi'il amr (perintah): duduklah! Akhirnya sukun dan diawali hamzah washl.","time":20,"options":["Fi'il amr","Fi'il madhi","Fi'il mudhari'"],"correct":1,"accepted":[]},{"key":"67130fd5e5a4cf83b47c43c7888dbc6e","cat":"amr","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa fi'il amr dari يَفْتَحُ (untuk أَنْتَ)?","ar":null,"explanation":"Buang huruf mudhara'ah → فْتَحُ, sukunkan akhirnya, tambah hamzah washl berharakat kasrah (karena 'ain fi'il fathah): اِفْتَحْ.","time":20,"options":["اِفْتَحْ","اُفْتُحْ","فْتَحْ","تَفْتَحْ"],"correct":1,"accepted":[]},{"key":"e88f6258fcf53734deda6a6afa3f62c6","cat":"amr","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il amr dari تَكْتُبِينَ (untuk أَنْتِ)?","ar":null,"explanation":"Amr untuk أَنْتِ: buang huruf mudhara'ah dan nun (seperti majzum), tambah hamzah washl berdhammah: اُكْتُبِي.","time":25,"options":["اُكْتُبِي","اُكْتُبْ","اُكْتُبِينَ","اِكْتِبِي"],"correct":1,"accepted":[]},{"key":"7aec3ee3be61464137c83035ece4164f","cat":"amr","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il amr dari يُرْسِلُ (untuk أَنْتَ)?","ar":null,"explanation":"يُرْسِلُ dari أَرْسَلَ (wazan أَفْعَلَ). Amr-nya memakai hamzah qath' berharakat fathah: أَرْسِلْ.","time":25,"options":["أَرْسِلْ","اِرْسِلْ","رْسِلْ","أُرْسِلْ"],"correct":1,"accepted":[]},{"key":"a58748723dbb80beec12e3690657b30f","cat":"amr","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il amr dari يَدْعُو (untuk أَنْتَ)?","ar":null,"explanation":"Fi'il naqish: amr dibentuk dengan membuang huruf illat di akhir: اُدْعُ (hamzah washl berdhammah karena 'ain fi'il dhammah).","time":30,"options":["اُدْعُ","اُدْعُو","دْعُ","اِدْعُ"],"correct":1,"accepted":[]},{"key":"d0320dec445499ffd3933aa5971038c1","cat":"amr","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il amr dari يَبِيعُ (untuk أَنْتَ)?","ar":null,"explanation":"بِيعُ → disukunkan بِيعْ → iltiqa' sakinain (ya' dan 'ain) sehingga ya' dibuang: بِعْ.","time":30,"options":["بِعْ","بِيعْ","اِبِعْ","بَعْ"],"correct":1,"accepted":[]},{"key":"e4b2ad04df7157c536a8a4036d1ceefe","cat":"mashdar","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa mashdar dari دَرَسَ?","ar":null,"explanation":"Mashdar دَرَسَ yang umum dipakai adalah دِرَاسَةٌ (juga دَرْسٌ). مَدْرَسَةٌ isim makan, دَارِسٌ isim fa'il, مَدْرُوسٌ isim maf'ul.","time":20,"options":["دِرَاسَةٌ","مَدْرَسَةٌ","دَارِسٌ","مَدْرُوسٌ"],"correct":1,"accepted":[]},{"key":"687084757b9bdb06b041d8291d485fc8","cat":"mashdar","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa mashdar dari أَكْرَمَ?","ar":null,"explanation":"أَكْرَمَ berwazan أَفْعَلَ, mashdarnya إِفْعَالٌ: إِكْرَامٌ. تَكْرِيمٌ mashdar كَرَّمَ, مُكْرِمٌ isim fa'il.","time":25,"options":["إِكْرَامٌ","تَكْرِيمٌ","كَرَمٌ","مُكْرِمٌ"],"correct":1,"accepted":[]},{"key":"d91f85738cbe0e51b216e17f8cae3632","cat":"mashdar","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa mashdar dari قَاتَلَ?","ar":null,"explanation":"قَاتَلَ berwazan فَاعَلَ, mashdarnya مُفَاعَلَةٌ atau فِعَالٌ: مُقَاتَلَةٌ / قِتَالٌ. قَتْلٌ mashdar قَتَلَ, اِقْتِتَالٌ mashdar اِقْتَتَلَ.","time":25,"options":["مُقَاتَلَةٌ / قِتَالٌ","قَتْلٌ","تَقْتِيلٌ","اِقْتِتَالٌ"],"correct":1,"accepted":[]},{"key":"fb61046b5370b00c6c834c64fea07b84","cat":"mashdar","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa mashdar dari اِجْتَمَعَ?","ar":null,"explanation":"اِجْتَمَعَ berwazan اِفْتَعَلَ, mashdarnya اِفْتِعَالٌ: اِجْتِمَاعٌ. تَجَمُّعٌ mashdar تَجَمَّعَ, مُجْتَمَعٌ = masyarakat (isim maf'ul/makan).","time":30,"options":["اِجْتِمَاعٌ","تَجَمُّعٌ","جَمْعٌ","مُجْتَمَعٌ"],"correct":1,"accepted":[]},{"key":"1c0032c1e50a7d711b528c285e3250dc","cat":"mashdar","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa mashdar dari تَعَاوَنَ?","ar":null,"explanation":"تَعَاوَنَ berwazan تَفَاعَلَ, mashdarnya تَفَاعُلٌ: تَعَاوُنٌ (huruf sebelum akhir didhammah). مُعَاوَنَةٌ mashdar عَاوَنَ, إِعَانَةٌ mashdar أَعَانَ.","time":30,"options":["تَعَاوُنٌ","مُعَاوَنَةٌ","إِعَانَةٌ","عَوْنٌ"],"correct":1,"accepted":[]},{"key":"55fcd73057475f6b99ff4f20fb43deb0","cat":"isim-fail","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim fa'il dari عَلِمَ?","ar":null,"explanation":"Isim fa'il tsulatsi berwazan فَاعِلٌ: عَالِمٌ (orang yang mengetahui). مَعْلُومٌ isim maf'ul, عِلْمٌ mashdar, مُعَلِّمٌ isim fa'il dari عَلَّمَ.","time":20,"options":["عَالِمٌ","مَعْلُومٌ","عِلْمٌ","مُعَلِّمٌ"],"correct":1,"accepted":[]},{"key":"11802ff896f6859201e14bb72b332a5b","cat":"isim-fail","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa isim fa'il dari اِسْتَمَعَ?","ar":null,"explanation":"Dari يَسْتَمِعُ: ganti huruf mudhara'ah dengan مُـ dan kasrahkan huruf sebelum akhir: مُسْتَمِعٌ (pendengar).","time":25,"options":["مُسْتَمِعٌ","مُسْتَمَعٌ","سَامِعٌ","اِسْتِمَاعٌ"],"correct":1,"accepted":[]},{"key":"eb1896a439c7fc907eee57c8e8a75426","cat":"isim-fail","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa isim fa'il dari قَالَ?","ar":null,"explanation":"Wazan فَاعِلٌ dari قَوَلَ menjadi قَاوِلٌ; wawu setelah alif tambahan diganti hamzah: قَائِلٌ. مَقُولٌ isim maf'ul, قَوْلٌ mashdar.","time":30,"options":["قَائِلٌ","قَاوِلٌ","مَقُولٌ","قَوْلٌ"],"correct":1,"accepted":[]},{"key":"83374369d32b7015ea6c7be062b80f11","cat":"isim-maful","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim maf'ul dari شَرِبَ?","ar":null,"explanation":"Isim maf'ul tsulatsi berwazan مَفْعُولٌ: مَشْرُوبٌ (yang diminum). شَارِبٌ isim fa'il, مَشْرَبٌ isim makan.","time":20,"options":["مَشْرُوبٌ","شَارِبٌ","شَرَابٌ","مَشْرَبٌ"],"correct":1,"accepted":[]},{"key":"eda5e740a9267593a7422a3bcf312b8d","cat":"isim-maful","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa isim maf'ul dari اِسْتَخْدَمَ?","ar":null,"explanation":"Dari يَسْتَخْدِمُ: ganti huruf mudhara'ah dengan مُـ dan fathahkan huruf sebelum akhir: مُسْتَخْدَمٌ (yang digunakan). مُسْتَخْدِمٌ (kasrah) isim fa'il = pengguna.","time":25,"options":["مُسْتَخْدَمٌ","مُسْتَخْدِمٌ","خَادِمٌ","اِسْتِخْدَامٌ"],"correct":1,"accepted":[]},{"key":"d364173ff867ef256777b324d2ae843f","cat":"isim-maful","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa isim maf'ul dari بَاعَ?","ar":null,"explanation":"Wazan مَفْعُولٌ dari بَيَعَ asalnya مَبْيُوعٌ, lalu diringkas (i'lal) menjadi مَبِيعٌ (barang yang dijual).","time":30,"options":["مَبِيعٌ","مَبْيُوعٌ","بَائِعٌ","مُبَاعٌ"],"correct":1,"accepted":[]},{"key":"20562feb60410dbaf740267c6ff2ee7c","cat":"tashrif","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Lengkapi tashrif ishthilahi: نَصَرَ – يَنْصُرُ – نَصْرًا – … (isim fa'il)","ar":null,"explanation":"Urutan tashrif ishthilahi: madhi – mudhari' – mashdar – isim fa'il – isim maf'ul – amr – nahi – isim zaman/makan – isim alat. Setelah mashdar: isim fa'il نَاصِرٌ.","time":25,"options":["نَاصِرٌ","مَنْصُورٌ","اُنْصُرْ","مَنْصَرٌ"],"correct":1,"accepted":[]},{"key":"c0e8744d13a54f413d99718362a55552","cat":"tashrif","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Lengkapi tashrif ishthilahi: ضَرَبَ – يَضْرِبُ – ضَرْبًا – ضَارِبٌ – مَضْرُوبٌ – … (amr)","ar":null,"explanation":"Setelah isim maf'ul datang fi'il amr: اِضْرِبْ (hamzah washl berkasrah karena 'ain mudhari'-nya kasrah). لَا تَضْرِبْ adalah fi'il nahi, sesudahnya.","time":30,"options":["اِضْرِبْ","اُضْرُبْ","ضْرِبْ","لَا تَضْرِبْ"],"correct":1,"accepted":[]},{"key":"ffb8654814b928b070f3e3837c81b299","cat":"tashrif","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Fi'il كَرُمَ – يَكْرُمُ termasuk bab apa?","ar":null,"explanation":"كَرُمَ – يَكْرُمُ: 'ain madhi dhammah dan 'ain mudhari' dhammah, yaitu bab ke-5 (فَعُلَ – يَفْعُلُ). Bab ini untuk sifat yang melekat.","time":30,"options":["فَعُلَ – يَفْعُلُ","فَعَلَ – يَفْعُلُ","فَعِلَ – يَفْعَلُ","فَعَلَ – يَفْعِلُ"],"correct":1,"accepted":[]},{"key":"4cef0ac826ef7f1fccd32be002a7fb40","cat":"mizan","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"مَكْتُوبٌ","explanation":"Huruf asli ك–ت–ب ditimbang ف–ع–ل; mim dan wawu tambahan tetap ditulis: مَفْعُولٌ.","time":20,"options":["مَفْعُولٌ","فَاعِلٌ","مَفْعَلٌ","فُعُولٌ"],"correct":1,"accepted":[]},{"key":"0b9521840dc755cbf54ca5c4335193f5","cat":"mizan","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"تَعَلَّمَ","explanation":"Huruf asli ع–ل–م; tambahan ta' di depan dan tasydid pada 'ain: تَفَعَّلَ.","time":25,"options":["تَفَعَّلَ","تَفَاعَلَ","فَعَّلَ","اِفْتَعَلَ"],"correct":1,"accepted":[]},{"key":"7b2b38f58e7ec5c5f95a040ad1d0e140","cat":"mizan","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"مَسَاجِدُ","explanation":"Huruf asli س–ج–د; mim di depan dan alif setelah huruf pertama adalah tambahan: مَفَاعِلُ (shighah muntahal jumu').","time":25,"options":["مَفَاعِلُ","فَعَالِلُ","مَفَاعِيلُ","فَوَاعِلُ"],"correct":1,"accepted":[]},{"key":"f295e016aba75e868b36b956a36d7e2b","cat":"mizan","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"وَعَدَ","explanation":"Semua huruf وَعَدَ asli (و–ع–د), maka mizan-nya فَعَلَ. Huruf asli selalu diganti ف–ع–ل, termasuk huruf illat.","time":30,"options":["فَعَلَ","وَعَلَ","فَاعَلَ","عَدَلَ"],"correct":1,"accepted":[]},{"key":"62337fb4425ebf66ae546e369c91989b","cat":"mizan","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"اِسْتِقْبَالٌ","explanation":"Huruf asli ق–ب–ل; tambahan اِسْتِـ dan alif sebelum huruf akhir: اِسْتِفْعَالٌ (mashdar اِسْتَفْعَلَ).","time":30,"options":["اِسْتِفْعَالٌ","اِفْتِعَالٌ","اِنْفِعَالٌ","تَفْعِيلٌ"],"correct":1,"accepted":[]},{"key":"0bab11c658d423502a84a6957bdd2026","cat":"mujarrad-mazid","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Fi'il berikut termasuk mujarrad atau mazid?","ar":"كَتَبَ","explanation":"كَتَبَ terdiri dari tiga huruf asli tanpa tambahan, maka tsulatsi mujarrad.","time":20,"options":["Tsulatsi mujarrad","Tsulatsi mazid satu huruf","Tsulatsi mazid dua huruf","Ruba'i mujarrad"],"correct":1,"accepted":[]},{"key":"a37b42c494e01ee38c65a486bb498b56","cat":"mujarrad-mazid","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk mujarrad atau mazid?","ar":"اِنْكَسَرَ","explanation":"Huruf asli ك–س–ر; tambahannya hamzah washl dan nun (اِنْـ): dua huruf, wazan اِنْفَعَلَ.","time":25,"options":["Tsulatsi mazid dua huruf","Tsulatsi mazid satu huruf","Tsulatsi mazid tiga huruf","Ruba'i mujarrad"],"correct":1,"accepted":[]},{"key":"74820a3f693ef01e832262ac525e1558","cat":"mujarrad-mazid","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Fi'il berikut termasuk mujarrad atau mazid?","ar":"زَلْزَلَ","explanation":"زَلْزَلَ terdiri dari empat huruf asli (ز–ل–ز–ل) tanpa tambahan, berwazan فَعْلَلَ: ruba'i mujarrad.","time":30,"options":["Ruba'i mujarrad","Tsulatsi mazid satu huruf","Ruba'i mazid","Tsulatsi mujarrad"],"correct":1,"accepted":[]},{"key":"076b863e07879b14d2bad1b14caf844f","cat":"mujarrad-mazid","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Faedah (makna) wazan فَاعَلَ pada kata berikut adalah …","ar":"شَارَكَ","explanation":"Wazan فَاعَلَ umumnya bermakna musyarakah: perbuatan yang melibatkan dua pihak, misalnya شَارَكَ = berserikat/ikut serta bersama.","time":25,"options":["Musyarakah (saling/bersama)","Ta'diyah (menjadikan transitif)","Thalab (meminta)","Muthawa'ah (menerima akibat)"],"correct":1,"accepted":[]},{"key":"552d946432cabe84b0f8c283129f9696","cat":"mujarrad-mazid","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Faedah (makna) wazan اِسْتَفْعَلَ pada kata berikut adalah …","ar":"اِسْتَغْفَرَ","explanation":"Wazan اِسْتَفْعَلَ sering bermakna thalab (meminta): اِسْتَغْفَرَ = meminta ampunan (غُفْرَانٌ).","time":30,"options":["Thalab (meminta)","Musyarakah (saling)","Ta'diyah","Muthawa'ah"],"correct":1,"accepted":[]},{"key":"64907fcefdef1c08a902e7b2d8484627","cat":"shahih-mutal","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Fi'il berikut termasuk jenis apa?","ar":"وَصَلَ","explanation":"Fa' fi'il-nya huruf illat (wawu), maka disebut mu'tal mitsal (mitsal wawi).","time":20,"options":["Mitsal","Ajwaf","Naqish","Shahih salim"],"correct":1,"accepted":[]},{"key":"70cb2a07e8bb3903ab27928f4eccb5ae","cat":"shahih-mutal","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk jenis apa?","ar":"رَمَى","explanation":"Lam fi'il-nya huruf illat (asal ya': رَمَيَ), maka disebut naqish (naqish ya'i).","time":25,"options":["Naqish","Ajwaf","Mitsal","Mudha'af"],"correct":1,"accepted":[]},{"key":"f0b1531b751765d920d7fcef4b26d22b","cat":"shahih-mutal","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk jenis apa?","ar":"مَدَّ","explanation":"مَدَّ asalnya مَدَدَ: 'ain dan lam fi'il-nya huruf yang sama, maka disebut mudha'af (termasuk fi'il shahih).","time":25,"options":["Shahih mudha'af","Shahih mahmuz","Shahih salim","Ajwaf"],"correct":1,"accepted":[]},{"key":"727351b35d1a4ca0310b5c64b0e0c5d5","cat":"shahih-mutal","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Fi'il berikut termasuk jenis apa?","ar":"وَقَى","explanation":"وَقَى memiliki dua huruf illat yang terpisah: fa' fi'il (و) dan lam fi'il (ي). Ini disebut lafif mafruq. Jika keduanya berdampingan (seperti طَوَى) disebut lafif maqrun.","time":30,"options":["Lafif mafruq","Lafif maqrun","Mitsal","Naqish"],"correct":1,"accepted":[]},{"key":"4a3050688ac484272fa94dbc89889367","cat":"rafa","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"[[يَكْتُبُ]] الطَّالِبُ","explanation":"Fi'il mudhari' yang tidak didahului 'amil nashab atau jazm adalah marfu', tandanya dhammah.","time":20,"options":["Fi'il mudhari' marfu' dengan dhammah","Fi'il madhi mabni 'ala al-fath","Fi'il mudhari' manshub","Fi'il mudhari' majzum"],"correct":1,"accepted":[]},{"key":"3600383f5db48a3fa59ca322a2687ef8","cat":"rafa","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"الطُّلَّابُ [[يَدْرُسُونَ]]","explanation":"يَدْرُسُونَ termasuk al-af'al al-khamsah; tanda rafa'-nya tetapnya nun (tsubut an-nun).","time":25,"options":["Fi'il mudhari' marfu' dengan tsubut an-nun","Fi'il mudhari' marfu' dengan dhammah","Fi'il mudhari' manshub dengan hadzf an-nun","Isim marfu' dengan wawu"],"correct":1,"accepted":[]},{"key":"049d65514662b1847b71a66a979d0c8d","cat":"nashab","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"أُرِيدُ أَنْ [[أَذْهَبَ]]","explanation":"أَنْ adalah huruf nashab, maka أَذْهَبَ manshub dengan fathah.","time":20,"options":["Fi'il mudhari' manshub dengan fathah karena أَنْ","Fi'il mudhari' marfu' dengan dhammah","Fi'il mudhari' majzum","Fi'il madhi mabni"],"correct":1,"accepted":[]},{"key":"85285fe23ba5eadc7b8bce79d013f59b","cat":"nashab","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَنْ [[يَنْجَحُوا]] بِدُونِ اجْتِهَادٍ","explanation":"لَنْ huruf nashab. يَنْجَحُوا dari al-af'al al-khamsah, tanda nashab-nya dibuangnya nun (hadzf an-nun). Alif setelah wawu adalah alif fariqah.","time":25,"options":["Fi'il mudhari' manshub dengan hadzf an-nun","Fi'il mudhari' majzum dengan hadzf an-nun","Fi'il mudhari' marfu' dengan tsubut an-nun","Fi'il madhi mabni 'ala adh-dhamm"],"correct":1,"accepted":[]},{"key":"f36ab15941d4f3e4c7851885c4713746","cat":"nashab","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"جِئْتُ لِـ ـــــ الْعِلْمَ","explanation":"Lam ta'lil (لِـ) me-nashab-kan fi'il mudhari' dengan أَنْ yang tersembunyi: لِأَطْلُبَ الْعِلْمَ (agar aku menuntut ilmu).","time":25,"options":["أَطْلُبَ","أَطْلُبُ","أَطْلُبْ","طَلَبْتُ"],"correct":1,"accepted":[]},{"key":"fccd3c3ad2116153218bc1422d1668cc","cat":"jarr","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"كَتَبْتُ بِـ[[الْقَلَمِ]]","explanation":"بِـ adalah huruf jar, maka الْقَلَمِ majrur dengan kasrah.","time":20,"options":["Isim majrur dengan kasrah karena huruf jar بِـ","Mudhaf ilaih majrur","Maf'ul bih manshub","Na'at majrur"],"correct":1,"accepted":[]},{"key":"ece9b44c2045923f20a59742dcaa7071","cat":"jarr","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"سَلَّمْتُ عَلَى [[الطَّالِبَيْنِ]]","explanation":"الطَّالِبَيْنِ mutsanna (ـَيْنِ, fathah sebelum ya'), majrur oleh عَلَى dengan ya'.","time":25,"options":["Isim majrur dengan ya' karena mutsanna","Isim majrur dengan ya' karena jamak mudzakkar salim","Maf'ul bih manshub dengan ya'","Isim majrur dengan kasrah"],"correct":1,"accepted":[]},{"key":"56a75a0bcef03a6852556bbd1e445c9b","cat":"jazm","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَمْ [[يَذْهَبْ]] الطَّالِبُ","explanation":"لَمْ adalah huruf jazm, maka يَذْهَبْ majzum dengan sukun.","time":20,"options":["Fi'il mudhari' majzum dengan sukun karena لَمْ","Fi'il mudhari' manshub dengan fathah","Fi'il mudhari' marfu' dengan dhammah","Fi'il amr mabni 'ala as-sukun"],"correct":1,"accepted":[]},{"key":"ad81b5ca04a2ba28bdd9ce21194c38ee","cat":"jazm","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَا [[تَكْذِبُوا]]","explanation":"لَا di sini adalah lam nahiyah (larangan) yang men-jazm-kan. تَكْذِبُوا (al-af'al al-khamsah) majzum dengan dibuangnya nun.","time":25,"options":["Fi'il mudhari' majzum dengan hadzf an-nun karena لَا nahiyah","Fi'il mudhari' manshub dengan hadzf an-nun","Fi'il mudhari' marfu'","Fi'il amr mabni"],"correct":1,"accepted":[]},{"key":"608c3999bc2e92b4f2cb1d59fd2f7a67","cat":"jazm","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَمْ [[يَدْعُ]] اللّٰهَ","explanation":"يَدْعُو adalah fi'il mudhari' naqish (berakhir wawu). Saat majzum oleh لَمْ, tandanya dibuangnya huruf illat: لَمْ يَدْعُ.","time":30,"options":["Fi'il mudhari' majzum dengan hadzf harf al-'illah","Fi'il mudhari' majzum dengan sukun","Fi'il amr mabni","Fi'il mudhari' manshub dengan fathah muqaddarah"],"correct":1,"accepted":[]},{"key":"236d66d546f831f5144e9dce11714355","cat":"jazm","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat syarat.","ar":"إِنْ تَدْرُسْ ـــــ","explanation":"إِنْ syarthiyyah men-jazm-kan dua fi'il: fi'il syarat (تَدْرُسْ) dan jawab syarat (تَنْجَحْ).","time":30,"options":["تَنْجَحْ","تَنْجَحُ","تَنْجَحَ","نَجَحْتَ"],"correct":1,"accepted":[]},{"key":"f0cf38f547d2a07b3d1c830ce8d41c8e","cat":"alamat-irab","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Apa tanda i'rab asli untuk rafa'?","ar":null,"explanation":"Tanda asli: rafa' dengan dhammah, nashab dengan fathah, jarr dengan kasrah, jazm dengan sukun.","time":20,"options":["Dhammah","Fathah","Kasrah","Sukun"],"correct":1,"accepted":[]},{"key":"6aa4f67bac0eba882430e73dc67c5eaf","cat":"alamat-irab","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Isim mutsanna ketika rafa' ditandai dengan …","ar":null,"explanation":"Mutsanna di-rafa'-kan dengan alif (الطَّالِبَانِ), di-nashab dan di-jarr-kan dengan ya' (الطَّالِبَيْنِ).","time":25,"options":["Alif","Wawu","Dhammah","Ya'"],"correct":1,"accepted":[]},{"key":"ab19472f157d4cfa92297fe50be7a9ba","cat":"alamat-irab","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Isim mamnu' min ash-sharf ketika majrur (tanpa ال dan tidak di-idhafah-kan) ditandai dengan …","ar":null,"explanation":"Mamnu' min ash-sharf di-jarr-kan dengan fathah sebagai pengganti kasrah, kecuali jika diberi ال atau di-idhafah-kan. Contoh: مَرَرْتُ بِأَحْمَدَ.","time":25,"options":["Fathah","Kasrah","Ya'","Sukun"],"correct":1,"accepted":[]},{"key":"0ab8bd7cd671b2d8c981dad3c47e9e03","cat":"alamat-irab","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Al-af'al al-khamsah ketika manshub dan majzum ditandai dengan …","ar":null,"explanation":"Al-af'al al-khamsah (يَفْعَلَانِ، تَفْعَلَانِ، يَفْعَلُونَ، تَفْعَلُونَ، تَفْعَلِينَ) di-rafa'-kan dengan tetapnya nun, sedangkan di-nashab dan di-jazm-kan dengan dibuangnya nun.","time":30,"options":["Dibuangnya nun","Tetapnya nun","Fathah dan sukun","Dibuangnya huruf illat"],"correct":1,"accepted":[]},{"key":"c37dfcb585fc76a7223dfae7d6f28625","cat":"irab-jumlah","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"إِنَّ فِي ذَلِكَ [[لَآيَاتٍ]]","explanation":"Khabar inna (فِي ذَلِكَ) didahulukan, dan آيَاتٍ adalah isim inna yang diakhirkan, diawali lam ibtida' (lam muzahlaqah). Jamak muannats salim manshub dengan kasrah.","time":25,"options":["Isim inna muakhkhar manshub dengan kasrah karena jamak muannats salim","Khabar inna marfu'","Isim majrur dengan kasrah","Tamyiz manshub"],"correct":1,"accepted":[]},{"key":"7ae586ee2438867d41cfade77d7c73e7","cat":"irab-jumlah","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"وَاتَّقُوا اللّٰهَ [[لَعَلَّكُمْ]] تُفْلِحُونَ","explanation":"لَعَلَّ adalah saudara inna yang bermakna harapan (tarajji). كُمْ isimnya (mabni, fi mahalli nashb), dan jumlah تُفْلِحُونَ adalah khabarnya (fi mahalli raf').","time":30,"options":["Huruf nashab (saudara inna) dan dhamir كُمْ sebagai isimnya fi mahalli nashb","Fi'il madhi dan fa'il","Huruf jar dan majrur","Isim marfu' sebagai mubtada'"],"correct":1,"accepted":[]},{"key":"95ba3669a9fa101de29e954a186ad0d0","cat":"irab-jumlah","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"الْحَمْدُ [[لِلّٰهِ]] رَبِّ الْعَالَمِينَ","explanation":"لِلّٰهِ adalah huruf jar lam + lafzhul jalalah yang majrur. Syibhu jumlah ini berkaitan dengan khabar mubtada' الْحَمْدُ yang dibuang (تَقْدِيرُهُ: كَائِنٌ / ثَابِتٌ). رَبِّ adalah na'at/badal bagi lafzhul jalalah.","time":30,"options":["Jar-majrur yang berkaitan dengan khabar yang dibuang","Mudhaf ilaih","Na'at majrur","Maf'ul bih ghairu sharih"],"correct":1,"accepted":[]},{"key":"d660110660c4c483d45032dac9e77944","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَدٌ","explanation":"يَدٌ = tangan (jamak: أَيْدٍ). Kaki = رِجْلٌ, kepala = رَأْسٌ, mata = عَيْنٌ.","time":20,"options":["Tangan","Kaki","Kepala","Mata"],"correct":1,"accepted":[]},{"key":"4428bf8e4475c163228cdb131b7689f7","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"عَيْنٌ","explanation":"عَيْنٌ = mata (juga berarti mata air). Telinga = أُذُنٌ, hidung = أَنْفٌ, mulut = فَمٌ.","time":20,"options":["Mata","Telinga","Hidung","Mulut"],"correct":1,"accepted":[]},{"key":"476c1640f6f254986e855d5997cf9968","cat":"dasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"kepala\"?","ar":null,"explanation":"رَأْسٌ = kepala. وَجْهٌ = wajah, شَعْرٌ = rambut, قَلْبٌ = hati/jantung.","time":20,"options":["رَأْسٌ","وَجْهٌ","شَعْرٌ","قَلْبٌ"],"correct":1,"accepted":[]},{"key":"367c10c8857ca722aabc1604ad5dc246","cat":"dasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"lima\"?","ar":null,"explanation":"خَمْسَةٌ = lima. ثَلَاثَةٌ = tiga, سَبْعَةٌ = tujuh, تِسْعَةٌ = sembilan.","time":20,"options":["خَمْسَةٌ","ثَلَاثَةٌ","سَبْعَةٌ","تِسْعَةٌ"],"correct":1,"accepted":[]},{"key":"d54ea06a79ae9e191c5b0e81e8f1aefc","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"عَشَرَةٌ","explanation":"عَشَرَةٌ = sepuluh. Dua puluh = عِشْرُونَ, delapan = ثَمَانِيَةٌ, seratus = مِائَةٌ.","time":20,"options":["Sepuluh","Dua puluh","Delapan","Seratus"],"correct":1,"accepted":[]},{"key":"0cb8f75201da94ce7ffb065fdb6d0886","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"أَبْيَضُ","explanation":"أَبْيَضُ = putih (muannats: بَيْضَاءُ). Hitam = أَسْوَدُ, cokelat = بُنِّيٌّ.","time":20,"options":["Putih","Hitam","Abu-abu","Cokelat"],"correct":1,"accepted":[]},{"key":"d05117f31d9184b8e02d9f8fb0d759a6","cat":"dasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"hari Jumat\"?","ar":null,"explanation":"يَوْمُ الْجُمُعَةِ = hari Jumat. الْخَمِيسُ = Kamis, السَّبْتُ = Sabtu, الْأَحَدُ = Ahad/Minggu.","time":20,"options":["يَوْمُ الْجُمُعَةِ","يَوْمُ الْخَمِيسِ","يَوْمُ السَّبْتِ","يَوْمُ الْأَحَدِ"],"correct":1,"accepted":[]},{"key":"411dc0bff01de1dc3c5987573e6e53dc","cat":"dasar","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَوْمُ الِاثْنَيْنِ","explanation":"الِاثْنَيْنِ = Senin (hari kedua). Selasa = الثُّلَاثَاءُ, Rabu = الْأَرْبِعَاءُ, Kamis = الْخَمِيسُ.","time":25,"options":["Hari Senin","Hari Selasa","Hari Rabu","Hari Kamis"],"correct":1,"accepted":[]},{"key":"2dc2bf1f99b788a452aa0d0f7d7481ec","cat":"dasar","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"لَيْلٌ","explanation":"لَيْلٌ = malam. Siang = نَهَارٌ, pagi = صَبَاحٌ, sore = مَسَاءٌ.","time":25,"options":["Malam","Siang","Pagi","Sore"],"correct":1,"accepted":[]},{"key":"91ff4805eb1cb0740bf64db0a2e3cb7e","cat":"dasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa lawan kata (ضِدّ) dari kata berikut?","ar":"حَارٌّ","explanation":"حَارٌّ (panas) lawannya بَارِدٌ (dingin). جَافٌّ = kering, نَظِيفٌ = bersih, مُظْلِمٌ = gelap.","time":25,"options":["بَارِدٌ","جَافٌّ","نَظِيفٌ","مُظْلِمٌ"],"correct":1,"accepted":[]},{"key":"c39c7114b70c8fa342866598bbcabe09","cat":"dasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa lawan kata (ضِدّ) dari kata berikut?","ar":"طَوِيلٌ","explanation":"طَوِيلٌ (panjang/tinggi) lawannya قَصِيرٌ (pendek). خَفِيفٌ = ringan (lawan ثَقِيلٌ), ضَيِّقٌ = sempit (lawan وَاسِعٌ).","time":25,"options":["قَصِيرٌ","صَغِيرٌ","خَفِيفٌ","ضَيِّقٌ"],"correct":1,"accepted":[]},{"key":"488976907b4509e8f24c74823f581edc","cat":"dasar","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa bentuk jamak dari kata berikut?","ar":"رَجُلٌ","explanation":"Jamak رَجُلٌ (laki-laki) adalah رِجَالٌ. أَرْجُلٌ adalah jamak رِجْلٌ (kaki), dan رِجْلَانِ = dua kaki.","time":30,"options":["رِجَالٌ","رِجْلَانِ","أَرْجُلٌ","رَاجِلُونَ"],"correct":1,"accepted":[]},{"key":"a0b20805b2e677797f37e8bdbeaba7c2","cat":"dasar","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama benda pada gambar dalam bahasa Arab?","ar":"⭐","explanation":"نَجْمٌ = bintang (jamak: نُجُومٌ). قَمَرٌ = bulan, شَمْسٌ = matahari, سَحَابٌ = awan.","time":20,"options":["نَجْمٌ","قَمَرٌ","شَمْسٌ","سَحَابٌ"],"correct":1,"accepted":[]},{"key":"d1bbd227d6db6f5d294b7c00f9169145","cat":"dasar","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? أَسْوَدُ artinya \"hitam\".","ar":"أَسْوَدُ","explanation":"Benar. أَسْوَدُ = hitam (muannats: سَوْدَاءُ).","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"ffeed9c470c679997ef860c77fd3ff29","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مِسْطَرَةٌ","explanation":"مِسْطَرَةٌ = penggaris (isim alat dari سَطَرَ = menggaris). Pensil = قَلَمُ رَصَاصٍ, rautan = مِبْرَاةٌ, gunting = مِقَصٌّ.","time":20,"options":["Penggaris","Pensil","Rautan","Gunting"],"correct":1,"accepted":[]},{"key":"050bdecf306b029030f37eadbbcaac5a","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"دَرْسٌ","explanation":"دَرْسٌ = pelajaran (jamak: دُرُوسٌ). Sekolah = مَدْرَسَةٌ, guru = مُدَرِّسٌ, ujian = اِمْتِحَانٌ.","time":20,"options":["Pelajaran","Sekolah","Guru","Ujian"],"correct":1,"accepted":[]},{"key":"3a49c22929d985c2caf3e3a9ed2dcbab","cat":"sekolah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"pertanyaan\"?","ar":null,"explanation":"سُؤَالٌ = pertanyaan (jamak: أَسْئِلَةٌ). جَوَابٌ = jawaban, دَرَجَةٌ = nilai/derajat, كَلِمَةٌ = kata.","time":20,"options":["سُؤَالٌ","جَوَابٌ","دَرَجَةٌ","كَلِمَةٌ"],"correct":1,"accepted":[]},{"key":"5dcc6bde93cde53745581d10e99b22d7","cat":"sekolah","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"perpustakaan sekolah\"?","ar":null,"explanation":"مَكْتَبَةُ الْمَدْرَسَةِ = perpustakaan sekolah. مَلْعَبٌ = lapangan, مَقْصَفٌ = kantin, مُدِيرٌ = kepala sekolah.","time":25,"options":["مَكْتَبَةُ الْمَدْرَسَةِ","مَلْعَبُ الْمَدْرَسَةِ","مَقْصَفُ الْمَدْرَسَةِ","مُدِيرُ الْمَدْرَسَةِ"],"correct":1,"accepted":[]},{"key":"064b700b6ab2cd486c708c52c53285b3","cat":"sekolah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"نَاجِحٌ","explanation":"نَاجِحٌ = lulus/berhasil (isim fa'il dari نَجَحَ). Gagal = رَاسِبٌ, hadir = حَاضِرٌ, terlambat = مُتَأَخِّرٌ.","time":25,"options":["Lulus / berhasil","Gagal","Hadir","Terlambat"],"correct":1,"accepted":[]},{"key":"bf40a9487c4b43cd5c557f5f8238f706","cat":"sekolah","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Guru bertanya: هَلْ فَهِمْتُمُ الدَّرْسَ؟ Pilih respons yang paling tepat.","ar":"هَلْ فَهِمْتُمُ الدَّرْسَ؟","explanation":"Pertanyaan: \"Apakah kalian sudah memahami pelajaran?\" Jawaban: نَعَمْ، فَهِمْنَا (ya, kami paham).","time":20,"options":["نَعَمْ، فَهِمْنَا يَا أُسْتَاذُ.","نَعَمْ، أَكَلْنَا يَا أُسْتَاذُ.","لَا، نَحْنُ فِي الْبَيْتِ.","الدَّرْسُ فِي الْكِتَابِ."],"correct":1,"accepted":[]},{"key":"cb8dbff954d49fb177606690646a5f1f","cat":"sekolah","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi kalimat: \"Murid itu membaca buku di kelas.\"","ar":null,"explanation":"Jumlah fi'liyyah: يَقْرَأُ + التِّلْمِيذُ (fa'il) + الْكِتَابَ (maf'ul bih) + فِي الْفَصْلِ. Boleh juga jumlah ismiyyah: التِّلْمِيذُ يَقْرَأُ ....","time":45,"options":["يَقْرَأُ","التِّلْمِيذُ","الْكِتَابَ","فِي","الْفَصْلِ"],"correct":null,"accepted":["يَقْرَأُ التِّلْمِيذُ الْكِتَابَ فِي الْفَصْلِ","التِّلْمِيذُ يَقْرَأُ الْكِتَابَ فِي الْفَصْلِ"]},{"key":"ff27a93b9df91958dc26e5253a9952ac","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"أَبٌ","explanation":"أَبٌ = ayah (jamak: آبَاءٌ). Kakek = جَدٌّ, paman = عَمٌّ/خَالٌ, saudara = أَخٌ.","time":20,"options":["Ayah","Kakek","Paman","Saudara"],"correct":1,"accepted":[]},{"key":"6682def49d7476de7418e5d8abe4fe8a","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"بَابُ الْبَيْتِ","explanation":"بَابٌ = pintu, الْبَيْتِ = rumah; susunan idhafah: pintu rumah.","time":20,"options":["Pintu rumah","Jendela rumah","Atap rumah","Kunci rumah"],"correct":1,"accepted":[]},{"key":"762ae6fad55642735d3480b43bbe65c8","cat":"rumah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"lemari\"?","ar":null,"explanation":"خِزَانَةٌ = lemari. مِرْآةٌ = cermin, سَجَّادَةٌ = karpet/sajadah, سِتَارَةٌ = gorden.","time":20,"options":["خِزَانَةٌ","مِرْآةٌ","سَجَّادَةٌ","سِتَارَةٌ"],"correct":1,"accepted":[]},{"key":"1f5d2d1b6c4e0d5f0b0fb2f3e9e5f4c8","cat":"rumah","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"keluarga\"?","ar":null,"explanation":"أُسْرَةٌ = keluarga (inti). قَبِيلَةٌ = suku, جَمَاعَةٌ = kelompok, شَعْبٌ = bangsa/rakyat.","time":25,"options":["أُسْرَةٌ","قَبِيلَةٌ","جَمَاعَةٌ","شَعْبٌ"],"correct":1,"accepted":[]},{"key":"f7ee85dc7e05399ea2296c599ad5cf56","cat":"rumah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يُنَظِّفُ الْغُرْفَةَ","explanation":"نَظَّفَ – يُنَظِّفُ = membersihkan. Mengunci = يُغْلِقُ/يَقْفِلُ, menghias = يُزَيِّنُ, membuka = يَفْتَحُ.","time":25,"options":["Membersihkan kamar","Mengunci kamar","Menghias kamar","Membuka kamar"],"correct":1,"accepted":[]},{"key":"f8514fd25cfac2a87ced90850ae7e05c","cat":"rumah","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Lengkapi kalimat \"Ibuku memasak di dapur.\"","ar":"أُمِّي تَطْبُخُ فِي ـــــ","explanation":"Memasak (تَطْبُخُ) dilakukan di dapur: الْمَطْبَخِ. الْحَمَّامُ = kamar mandi, غُرْفَةُ النَّوْمِ = kamar tidur, الْحَدِيقَةُ = taman.","time":20,"options":["الْمَطْبَخِ","الْحَمَّامِ","غُرْفَةِ النَّوْمِ","الْحَدِيقَةِ"],"correct":1,"accepted":[]},{"key":"db96d4b378728c91d6c7e1ccfc8b32a6","cat":"rumah","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? جَدٌّ artinya \"nenek\".","ar":"جَدٌّ","explanation":"Salah. جَدٌّ = kakek, sedangkan nenek = جَدَّةٌ.","time":25,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"d9f235583eeb5343e613c583e2a2a6ee","cat":"makanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"بَيْضٌ","explanation":"بَيْضٌ = telur (satu butir: بَيْضَةٌ). Keju = جُبْنٌ, mentega = زُبْدَةٌ, madu = عَسَلٌ.","time":20,"options":["Telur","Keju","Mentega","Madu"],"correct":1,"accepted":[]},{"key":"082b28b996f543258148a9fa7e837a15","cat":"makanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"عَسَلٌ","explanation":"عَسَلٌ = madu. Gula = سُكَّرٌ, susu = حَلِيبٌ, minyak = زَيْتٌ.","time":20,"options":["Madu","Gula","Susu","Minyak"],"correct":1,"accepted":[]},{"key":"a314b430ea28e649f33356397e390331","cat":"makanan","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"ayam\"?","ar":null,"explanation":"دَجَاجٌ = ayam. بَطٌّ = bebek, سَمَكٌ = ikan, غَنَمٌ = kambing/domba.","time":20,"options":["دَجَاجٌ","بَطٌّ","سَمَكٌ","غَنَمٌ"],"correct":1,"accepted":[]},{"key":"2364b6c92be0d4c0c77a61e3d477c833","cat":"makanan","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"haus\"?","ar":null,"explanation":"عَطْشَانُ = haus. جَوْعَانُ = lapar, شَبْعَانُ = kenyang, نَعْسَانُ = mengantuk. Semuanya berwazan فَعْلَانُ.","time":25,"options":["عَطْشَانُ","جَوْعَانُ","شَبْعَانُ","نَعْسَانُ"],"correct":1,"accepted":[]},{"key":"d79046ee6e77bd3c440c69399764feae","cat":"makanan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"لَذِيذٌ","explanation":"لَذِيذٌ = lezat/enak. Pahit = مُرٌّ, asin = مَالِحٌ, basi = فَاسِدٌ.","time":25,"options":["Lezat","Pahit","Asin","Basi"],"correct":1,"accepted":[]},{"key":"7e242d4db1d76aa9bb96cd068eea4cf7","cat":"makanan","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama makanan pada gambar dalam bahasa Arab?","ar":"🍞","explanation":"خُبْزٌ = roti. أَرُزٌّ = nasi, كَعْكٌ = kue, لَحْمٌ = daging.","time":20,"options":["خُبْزٌ","أَرُزٌّ","كَعْكٌ","لَحْمٌ"],"correct":1,"accepted":[]},{"key":"3788762c431271674195601f9f65719c","cat":"makanan","type":"picture_vocabulary","level":"intermediate","variety":"fusha","prompt":"Apa nama buah pada gambar dalam bahasa Arab?","ar":"🍊","explanation":"بُرْتُقَالٌ = jeruk. لَيْمُونٌ = lemon, مَوْزٌ = pisang, كُمَّثْرَى = pir.","time":25,"options":["بُرْتُقَالٌ","لَيْمُونٌ","مَوْزٌ","كُمَّثْرَى"],"correct":1,"accepted":[]},{"key":"21457cb4c7491b9b13a3e8508869dd22","cat":"makanan","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Temanmu baru saja makan. Ucapan yang tepat untuknya adalah …","ar":null,"explanation":"بِالْهَنَاءِ وَالشِّفَاءِ = semoga nikmat dan menyehatkan (kepada yang makan). عَظَّمَ اللّٰهُ أَجْرَكَ untuk takziah, كُلُّ عَامٍ وَأَنْتَ بِخَيْرٍ untuk hari raya, حَمْدًا لِلّٰهِ عَلَى السَّلَامَةِ untuk yang baru tiba dengan selamat.","time":25,"options":["بِالْهَنَاءِ وَالشِّفَاءِ.","عَظَّمَ اللّٰهُ أَجْرَكَ.","كُلُّ عَامٍ وَأَنْتَ بِخَيْرٍ.","حَمْدًا لِلّٰهِ عَلَى السَّلَامَةِ."],"correct":1,"accepted":[]},{"key":"7aeb4fc81713788cef88d773eac6e557","cat":"aktivitas","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَشْرَبُ","explanation":"شَرِبَ – يَشْرَبُ = minum.","time":20,"options":["Minum","Makan","Mencuci","Tidur"],"correct":1,"accepted":[]},{"key":"579952d7f544c47980a3802832d860ec","cat":"aktivitas","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَقْرَأُ","explanation":"قَرَأَ – يَقْرَأُ = membaca. Menulis = يَكْتُبُ, mendengar = يَسْمَعُ, melihat = يَرَى.","time":20,"options":["Membaca","Menulis","Mendengar","Melihat"],"correct":1,"accepted":[]},{"key":"e21303d246a780e162bd014e300e4ea6","cat":"aktivitas","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"duduk\"?","ar":null,"explanation":"جَلَسَ – يَجْلِسُ = duduk. يَقُومُ = berdiri, يَمْشِي = berjalan, يَنَامُ = tidur.","time":20,"options":["يَجْلِسُ","يَقُومُ","يَمْشِي","يَنَامُ"],"correct":1,"accepted":[]},{"key":"db7e54cd0b0b7c44f2846f2982ae7112","cat":"aktivitas","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"menghafal\"?","ar":null,"explanation":"حَفِظَ – يَحْفَظُ = menghafal/menjaga. يَنْسَى = lupa, يَفْهَمُ = memahami, يَشْرَحُ = menjelaskan.","time":25,"options":["يَحْفَظُ","يَنْسَى","يَفْهَمُ","يَشْرَحُ"],"correct":1,"accepted":[]},{"key":"74dbe6e5ff8aae110450ec1770f3657a","cat":"aktivitas","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَسْتَمِعُ","explanation":"اِسْتَمَعَ – يَسْتَمِعُ = mendengarkan dengan sengaja/saksama. يَسْمَعُ = mendengar (tanpa sengaja).","time":25,"options":["Mendengarkan (dengan saksama)","Berbicara","Bertanya","Bernyanyi"],"correct":1,"accepted":[]},{"key":"81edb3870efc5b9d7971bc640d2edc6e","cat":"aktivitas","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَتَدَرَّبُ","explanation":"تَدَرَّبَ – يَتَدَرَّبُ = berlatih. Beristirahat = يَسْتَرِيحُ, bertanding = يَتَبَارَى, menonton = يُشَاهِدُ.","time":30,"options":["Berlatih","Beristirahat","Bertanding","Menonton"],"correct":1,"accepted":[]},{"key":"2a1487ac521f94a21e1cb464d0a8e311","cat":"aktivitas","type":"complete_expression","level":"intermediate","variety":"fusha","prompt":"Lengkapi kalimat \"Setelah salat Isya, aku tidur.\"","ar":"بَعْدَ صَلَاةِ الْعِشَاءِ ـــــ","explanation":"Setelah Isya biasanya tidur: أَنَامُ. أَسْتَيْقِظُ = bangun, أَتَسَحَّرُ = makan sahur, أُفْطِرُ = berbuka/sarapan.","time":25,"options":["أَنَامُ","أَسْتَيْقِظُ","أَتَسَحَّرُ","أُفْطِرُ"],"correct":1,"accepted":[]},{"key":"f02c2960d2d15756c78d92a366f6dceb","cat":"aktivitas","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? يَمْشِي artinya \"berjalan\".","ar":"يَمْشِي","explanation":"Benar. مَشَى – يَمْشِي = berjalan.","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"203e66d74206367b1a1e15a6ad4c48ea","cat":"perjalanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سَفِينَةٌ","explanation":"سَفِينَةٌ = kapal (jamak: سُفُنٌ). Pesawat = طَائِرَةٌ, perahu kecil = قَارِبٌ, kereta = قِطَارٌ.","time":20,"options":["Kapal","Pesawat","Perahu kecil","Kereta"],"correct":1,"accepted":[]},{"key":"a0365377af23a2cefca6460493b9f69e","cat":"perjalanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَدِينَةٌ","explanation":"مَدِينَةٌ = kota (jamak: مُدُنٌ). Desa = قَرْيَةٌ, negara = دَوْلَةٌ / بَلَدٌ, provinsi = مُحَافَظَةٌ.","time":20,"options":["Kota","Desa","Negara","Provinsi"],"correct":1,"accepted":[]},{"key":"06c9f20ac49352f2830509574fb4cb83","cat":"perjalanan","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"koper / tas perjalanan\"?","ar":null,"explanation":"حَقِيبَةُ سَفَرٍ = koper. تَذْكِرَةٌ = tiket, خَرِيطَةٌ = peta, بُوصَلَةٌ = kompas.","time":20,"options":["حَقِيبَةُ سَفَرٍ","تَذْكِرَةُ قِطَارٍ","خَرِيطَةٌ","بُوصَلَةٌ"],"correct":1,"accepted":[]},{"key":"0423be2da4d20d82616ebbd0b5a149a6","cat":"perjalanan","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"kiri\"?","ar":null,"explanation":"يَسَارٌ = kiri. يَمِينٌ = kanan, أَمَامٌ = depan, خَلْفٌ = belakang.","time":25,"options":["يَسَارٌ","يَمِينٌ","أَمَامٌ","خَلْفٌ"],"correct":1,"accepted":[]},{"key":"63c7c1f967512f0eb9174e0cb07c71bc","cat":"perjalanan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَحَطَّةٌ","explanation":"مَحَطَّةٌ = stasiun/halte. Bandara = مَطَارٌ, pelabuhan = مِينَاءٌ.","time":25,"options":["Stasiun / halte","Bandara","Pelabuhan","Jalan tol"],"correct":1,"accepted":[]},{"key":"c8cd48c9765755e86d970471cdaf5df2","cat":"perjalanan","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu tersesat dan ingin minta tolong ditunjukkan jalan. Kalimat yang tepat adalah …","ar":null,"explanation":"دُلَّنِي عَلَى الطَّرِيقِ = tunjukkan aku jalan. أَعْطِنِي الْحِسَابَ = berikan tagihannya.","time":25,"options":["مِنْ فَضْلِكَ، دُلَّنِي عَلَى الطَّرِيقِ.","مِنْ فَضْلِكَ، أَعْطِنِي الْحِسَابَ.","أَنَا لَا أُحِبُّ السَّفَرَ.","الطَّرِيقُ جَمِيلٌ جِدًّا."],"correct":1,"accepted":[]},{"key":"25a01ceb71ebf332593cda419da5bbae","cat":"perjalanan","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Petugas bandara bertanya: هَلْ مَعَكَ أَمْتِعَةٌ؟ Pilih respons yang paling tepat.","ar":"هَلْ مَعَكَ أَمْتِعَةٌ؟","explanation":"أَمْتِعَةٌ = barang bawaan/bagasi. Jawaban yang tepat menyebut barang: مَعِي حَقِيبَتَانِ (saya membawa dua tas).","time":25,"options":["نَعَمْ، مَعِي حَقِيبَتَانِ.","نَعَمْ، أَنَا مُسَافِرٌ وَحْدِي.","لَا، أَنَا مِنْ مِصْرَ.","الطَّائِرَةُ مُتَأَخِّرَةٌ."],"correct":1,"accepted":[]},{"key":"9b8b3d71af133cc59078354c840cf5a8","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"جَامِعَةٌ","explanation":"جَامِعَةٌ = universitas. Fakultas = كُلِّيَّةٌ, sekolah = مَدْرَسَةٌ, pesantren = مَعْهَدٌ.","time":25,"options":["Universitas","Fakultas","Sekolah","Pesantren"],"correct":1,"accepted":[]},{"key":"e3dfb2765057e89472e8bcef4cbd7248","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"شَهَادَةٌ","explanation":"شَهَادَةٌ = ijazah/sertifikat (juga berarti kesaksian). Kartu mahasiswa = بِطَاقَةُ الطَّالِبِ.","time":25,"options":["Ijazah / sertifikat","Kartu mahasiswa","Nilai","Kehadiran"],"correct":1,"accepted":[]},{"key":"b944bf8c247a1837afc828e2c98cfa77","cat":"kampus","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"jurusan\"?","ar":null,"explanation":"قِسْمٌ = jurusan/bagian. كُلِّيَّةٌ = fakultas, مَادَّةٌ = mata kuliah, فَصْلٌ دِرَاسِيٌّ = semester.","time":25,"options":["قِسْمٌ","كُلِّيَّةٌ","مَادَّةٌ","فَصْلٌ دِرَاسِيٌّ"],"correct":1,"accepted":[]},{"key":"03ec5fd2ce9e6e18115c545e0141b47f","cat":"kampus","type":"arabic_translation","level":"advanced","variety":"fusha","prompt":"Apa bahasa Arabnya \"penelitian\"?","ar":null,"explanation":"بَحْثٌ = penelitian/kajian (jamak: بُحُوثٌ / أَبْحَاثٌ). نَقْدٌ = kritik.","time":30,"options":["بَحْثٌ","دَرْسٌ","قِرَاءَةٌ","نَقْدٌ"],"correct":1,"accepted":[]},{"key":"0f26187c8ad28008d0575f5f893ab1f2","cat":"kampus","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مُشْرِفٌ","explanation":"مُشْرِفٌ = pembimbing/pengawas (isim fa'il dari أَشْرَفَ). Penguji = مُمْتَحِنٌ, rektor = رَئِيسُ الْجَامِعَةِ.","time":30,"options":["Pembimbing / supervisor","Penguji","Mahasiswa baru","Rektor"],"correct":1,"accepted":[]},{"key":"30cd9613ea3a52fbbcefa68cdd6930a9","cat":"kampus","type":"daily_conversation","level":"advanced","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"فِي أَيِّ سَنَةٍ دِرَاسِيَّةٍ أَنْتَ؟","explanation":"Pertanyaan: \"Kamu di tahun (tingkat) berapa?\" Jawabannya: أَنَا فِي السَّنَةِ الثَّانِيَةِ (saya di tahun kedua).","time":30,"options":["أَنَا فِي السَّنَةِ الثَّانِيَةِ.","أَنَا فِي كُلِّيَّةِ اللُّغَةِ الْعَرَبِيَّةِ.","عُمْرِي عِشْرُونَ سَنَةً.","أَسْكُنُ فِي السَّكَنِ الطُّلَّابِيِّ."],"correct":1,"accepted":[]},{"key":"45dea3ae598e9acb9e3fc686ea77bd28","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Tamu berkata: أَهْلًا وَسَهْلًا. Pilih respons yang paling tepat.","ar":"أَهْلًا وَسَهْلًا","explanation":"أَهْلًا وَسَهْلًا = selamat datang; dijawab أَهْلًا بِكَ (selamat datang juga untukmu).","time":20,"options":["أَهْلًا بِكَ.","صَبَاحَ النُّورِ.","لَا بَأْسَ.","إِنْ شَاءَ اللّٰهُ."],"correct":1,"accepted":[]},{"key":"4c1830512e8beb6934030f364816bba9","cat":"salam","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Seseorang bertanya: مَا عَمَلُكَ؟ Pilih respons yang paling tepat.","ar":"مَا عَمَلُكَ؟","explanation":"مَا عَمَلُكَ؟ = Apa pekerjaanmu? Jawabannya menyebut profesi: أَنَا مُدَرِّسٌ (saya guru).","time":25,"options":["أَنَا مُدَرِّسٌ.","أَنَا بِخَيْرٍ.","أَنَا مِنْ سُورَابَايَا.","عِنْدِي أُخْتٌ."],"correct":1,"accepted":[]},{"key":"479cb6084fcbfce690b09e505ebcd243","cat":"salam","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Temanmu berkata: كُلُّ عَامٍ وَأَنْتَ بِخَيْرٍ. Pilih respons yang paling tepat.","ar":"كُلُّ عَامٍ وَأَنْتَ بِخَيْرٍ","explanation":"كُلُّ عَامٍ وَأَنْتَ بِخَيْرٍ = semoga engkau baik setiap tahun (ucapan hari raya/ulang tahun). Jawabannya: وَأَنْتَ بِخَيْرٍ.","time":25,"options":["وَأَنْتَ بِخَيْرٍ.","وَعَلَيْكُمُ السَّلَامُ.","شَفَاكَ اللّٰهُ.","صَبَاحَ النُّورِ."],"correct":1,"accepted":[]},{"key":"616b965bf6761f06664dbb6e7ebe1b33","cat":"salam","type":"complete_expression","level":"intermediate","variety":"fusha","prompt":"Lengkapi ucapan untuk orang yang baru tiba dari perjalanan dengan selamat.","ar":"حَمْدًا لِلّٰهِ عَلَى ـــــ","explanation":"حَمْدًا لِلّٰهِ عَلَى السَّلَامَةِ = alhamdulillah atas keselamatanmu. Jawabannya: اللّٰهُ يُسَلِّمُكَ.","time":25,"options":["السَّلَامَةِ","الطَّعَامِ","النَّوْمِ","الْعَمَلِ"],"correct":1,"accepted":[]},{"key":"ffac30eb08ca605ce1062754cea560f2","cat":"salam","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? أَهْلًا bisa dipakai untuk menyambut seseorang.","ar":"أَهْلًا","explanation":"Benar. أَهْلًا (atau أَهْلًا وَسَهْلًا) = selamat datang/halo.","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"b8250e0aa17d9946d41a05a3eca1fef5","cat":"pasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"غَالٍ","explanation":"غَالٍ (dengan ال: الْغَالِي) = mahal. Murah = رَخِيصٌ, gratis = مَجَّانِيٌّ, diskon = خَصْمٌ / تَخْفِيضٌ.","time":20,"options":["Mahal","Murah","Gratis","Diskon"],"correct":1,"accepted":[]},{"key":"4fd0fd72295d166194437956844eafbe","cat":"pasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَطْعَمٌ","explanation":"مَطْعَمٌ = restoran (isim makan dari طَعِمَ = makan). Toko roti = مَخْبَزٌ.","time":20,"options":["Restoran","Pasar","Dapur","Toko roti"],"correct":1,"accepted":[]},{"key":"43235bcd271d8bc34238cdb4aa1263b5","cat":"pasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"membeli\"?","ar":null,"explanation":"اِشْتَرَى – يَشْتَرِي = membeli. يَبِيعُ = menjual, يَدْفَعُ = membayar, يَأْخُذُ = mengambil.","time":20,"options":["يَشْتَرِي","يَبِيعُ","يَدْفَعُ","يَأْخُذُ"],"correct":1,"accepted":[]},{"key":"c77aad6b11ceae0517ba692c190e006a","cat":"pasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"pelayan restoran\"?","ar":null,"explanation":"نَادِلٌ = pelayan restoran. طَبَّاخٌ = juru masak, زَبُونٌ = pelanggan, بَائِعٌ = penjual.","time":25,"options":["نَادِلٌ","طَبَّاخٌ","زَبُونٌ","بَائِعٌ"],"correct":1,"accepted":[]},{"key":"a9f15ba6a90a1199b5b1f797427e4f18","cat":"pasar","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Penjual berkata: تَفَضَّلْ، مَاذَا تُرِيدُ؟ Pilih respons yang paling tepat.","ar":"تَفَضَّلْ، مَاذَا تُرِيدُ؟","explanation":"Penjual bertanya: \"Silakan, mau apa?\" Jawaban yang tepat menyebut barang: أُرِيدُ كِيلُو مِنَ الطَّمَاطِمِ (saya mau sekilo tomat).","time":25,"options":["أُرِيدُ كِيلُو مِنَ الطَّمَاطِمِ.","أُرِيدُ أَنْ أَنَامَ قَلِيلًا.","أَنَا لَسْتُ جَائِعًا.","شُكْرًا، مَعَ السَّلَامَةِ."],"correct":1,"accepted":[]},{"key":"b1cbb5eefde7dcf6a40390b2e00f5a2a","cat":"pasar","type":"context_challenge","level":"advanced","variety":"fusha","prompt":"Kamu ingin menanyakan apakah toko menerima pembayaran dengan kartu. Kalimat yang tepat adalah …","ar":null,"explanation":"الدَّفْعُ بِالْبِطَاقَةِ = pembayaran dengan kartu, تَقْبَلُونَ = kalian menerima.","time":30,"options":["هَلْ تَقْبَلُونَ الدَّفْعَ بِالْبِطَاقَةِ؟","هَلْ عِنْدَكُمْ بِطَاقَةُ هُوِيَّةٍ؟","أَيْنَ الْبَنْكُ؟","كَمِ السَّاعَةُ الْآنَ؟"],"correct":1,"accepted":[]},{"key":"7246fa1bb0d5d50b40c13c399ad63b8a","cat":"ungkapan","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Ketika berjanji akan melakukan sesuatu besok, kita mengucapkan …","ar":"ـــــ شَاءَ اللّٰهُ","explanation":"إِنْ شَاءَ اللّٰهُ = jika Allah menghendaki, diucapkan untuk rencana di masa depan.","time":20,"options":["إِنْ","مَا","لَوْ","قَدْ"],"correct":1,"accepted":[]},{"key":"b3ccba75e508d73e2f32a85a0b0baec9","cat":"ungkapan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti ungkapan berikut?","ar":"بَارَكَ اللّٰهُ فِيكَ","explanation":"بَارَكَ اللّٰهُ فِيكَ = semoga Allah memberkahimu; sering dipakai sebagai ungkapan terima kasih.","time":25,"options":["Semoga Allah memberkahimu","Semoga Allah menyembuhkanmu","Semoga Allah mengampunimu","Semoga Allah memudahkanmu"],"correct":1,"accepted":[]},{"key":"3cc276f3524126e566929e7936e6da36","cat":"ungkapan","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Kapan ungkapan berikut diucapkan?","ar":"أَعُوذُ بِاللّٰهِ","explanation":"أَعُوذُ بِاللّٰهِ = aku berlindung kepada Allah, diucapkan untuk berlindung dari keburukan atau godaan setan.","time":25,"options":["Ketika berlindung dari keburukan","Ketika bersyukur atas nikmat","Ketika memulai makan","Ketika menjawab salam"],"correct":1,"accepted":[]},{"key":"8e5cd8d54616d84f86ae3fb3e235fdd6","cat":"ungkapan","type":"context_challenge","level":"advanced","variety":"fusha","prompt":"Temanmu sedang bersedih karena keluarganya wafat. Ucapan takziah yang tepat adalah …","ar":null,"explanation":"عَظَّمَ اللّٰهُ أَجْرَكَ = semoga Allah membesarkan pahalamu (ucapan takziah). مَبْرُوكٌ = selamat (untuk kabar gembira).","time":30,"options":["عَظَّمَ اللّٰهُ أَجْرَكَ.","مَبْرُوكٌ عَلَيْكَ.","بِالْهَنَاءِ وَالشِّفَاءِ.","كُلُّ عَامٍ وَأَنْتَ بِخَيْرٍ."],"correct":1,"accepted":[]},{"key":"8fced93f419b72a78a717d31d09f2ffa","cat":"ungkapan","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? مَبْرُوكٌ diucapkan untuk memberi selamat atas kabar gembira.","ar":"مَبْرُوكٌ","explanation":"Benar. مَبْرُوكٌ = selamat/semoga diberkahi. Jawabannya: اللّٰهُ يُبَارِكُ فِيكَ.","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"9b426428c661c2b86884f7c949ef43e3","cat":"fusha","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"هَلْ تُرِيدُ أَنْ تَشْرَبَ شَيْئًا؟","explanation":"Pertanyaan: \"Apakah kamu ingin minum sesuatu?\" Jawaban: \"Ya, segelas teh, tolong.\"","time":25,"options":["نَعَمْ، كُوبًا مِنَ الشَّايِ مِنْ فَضْلِكَ.","نَعَمْ، أُرِيدُ أَنْ أَنَامَ.","لَا، أَنَا طَالِبٌ.","نَعَمْ، الْكُوبُ جَمِيلٌ."],"correct":1,"accepted":[]},{"key":"1cf186ff625b923d457994d8c906f0e9","cat":"fusha","type":"daily_conversation","level":"advanced","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"كَيْفَ تَقْضِي وَقْتَ فَرَاغِكَ؟","explanation":"Pertanyaan: \"Bagaimana kamu menghabiskan waktu luangmu?\" Jawaban: \"Aku menghabiskannya dengan membaca buku dan olahraga.\"","time":30,"options":["أَقْضِيهِ فِي قِرَاءَةِ الْكُتُبِ وَالرِّيَاضَةِ.","لَيْسَ عِنْدِي سَاعَةٌ.","الْوَقْتُ الْآنَ الْعَاشِرَةُ.","فَرَغْتُ مِنَ الطَّعَامِ."],"correct":1,"accepted":[]},{"key":"6d55cf7a606037403223e022d2e279d6","cat":"fusha","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu ingin menanyakan jam berapa sekarang. Kalimat yang tepat adalah …","ar":null,"explanation":"كَمِ السَّاعَةُ الْآنَ؟ = jam berapa sekarang? Pilihan lain: berapa umurmu, di mana jamnya, milik siapa jam ini.","time":25,"options":["كَمِ السَّاعَةُ الْآنَ؟","كَمْ عُمْرُكَ الْآنَ؟","أَيْنَ السَّاعَةُ؟","لِمَنْ هَذِهِ السَّاعَةُ؟"],"correct":1,"accepted":[]},{"key":"db625a53d7d4cf996588470d8d7ca394","cat":"fusha","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi kalimat: \"Aku pergi ke pasar bersama ayahku.\"","ar":null,"explanation":"ذَهَبْتُ (aku pergi) + إِلَى السُّوقِ (ke pasar) + مَعَ أَبِي (bersama ayahku). Dua keterangan boleh bertukar tempat.","time":45,"options":["ذَهَبْتُ","إِلَى","السُّوقِ","مَعَ","أَبِي"],"correct":null,"accepted":["ذَهَبْتُ إِلَى السُّوقِ مَعَ أَبِي","ذَهَبْتُ مَعَ أَبِي إِلَى السُّوقِ"]},{"key":"f7aaa3be74e7f0afa5d5862fa695fd51","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"لَأْ","explanation":"لَأْ = tidak (Fusha: لَا). Ya = أَيْوَه.","time":20,"options":["Tidak","Ya","Sudah","Belum"],"correct":1,"accepted":[]},{"key":"03852e5abcb01adc2555d455350d68e2","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"النَّهَارْدَه","explanation":"النَّهَارْدَه = hari ini (Fusha: الْيَوْمَ). Besok = بُكْرَه, kemarin = إِمْبَارِح.","time":20,"options":["Hari ini","Besok","Kemarin","Malam ini"],"correct":1,"accepted":[]},{"key":"c4334f750273ae2ebf9df94db19f9647","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa padanan Fusha dari kata Amiyah ini?","ar":"إِمْتَى","explanation":"إِمْتَى = kapan (Fusha: مَتَى). Contoh: هَتِيجِي إِمْتَى؟ = kapan kamu akan datang?","time":25,"options":["مَتَى","أَيْنَ","كَمْ","لِمَاذَا"],"correct":1,"accepted":[]},{"key":"ea235f6b6065383bda761828a91e67e2","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"شُوَيَّة","explanation":"شُوَيَّة = sedikit (Fusha: قَلِيلًا). Contoh: اِسْتَنَّى شُوَيَّة = tunggu sebentar.","time":25,"options":["Sedikit","Banyak","Cepat","Lambat"],"correct":1,"accepted":[]},{"key":"a210d18df6d69db8ec09ecba56b3b002","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"كِتِير","explanation":"كِتِير = banyak (Fusha: كَثِيرٌ / كَثِيرًا). Contoh: شُكْرًا كِتِير = terima kasih banyak.","time":25,"options":["Banyak","Sedikit","Mahal","Jauh"],"correct":1,"accepted":[]},{"key":"be3b37fb41051962d660bcd3336d015b","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Apa padanan Fusha dari kalimat Amiyah ini?","ar":"إِنْتَ رَايِح فِين؟","explanation":"رَايِح = pergi (Fusha: ذَاهِبٌ), فِين = ke mana. Jadi: إِلَى أَيْنَ أَنْتَ ذَاهِبٌ؟","time":30,"options":["إِلَى أَيْنَ أَنْتَ ذَاهِبٌ؟","مِنْ أَيْنَ أَنْتَ؟","أَيْنَ تَسْكُنُ؟","مَتَى تَذْهَبُ؟"],"correct":1,"accepted":[]},{"key":"52cd9716766c33b62b780fed42248227","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"وَلَا يِهِمَّك","explanation":"وَلَا يِهِمَّك = jangan khawatir/tidak usah dipikirkan. Sering dipakai untuk menenangkan atau menjawab ucapan maaf.","time":30,"options":["Jangan khawatir / tidak masalah","Jangan pergi","Jangan bicara","Hati-hati di jalan"],"correct":1,"accepted":[]},{"key":"2a62bad18e6b7f959424199c2796117e","cat":"mubtada-khabar","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"[[الصَّبْرُ]] جَمِيلٌ","explanation":"الصَّبْرُ di awal jumlah ismiyyah adalah mubtada', marfu' dengan dhammah. جَمِيلٌ adalah khabarnya.","time":20,"options":["Mubtada' marfu' dengan dhammah","Khabar marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"ba3ee77da8d01c82e137b78d95830aed","cat":"mubtada-khabar","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"الطَّالِبَاتُ [[مُجْتَهِدَاتٌ]]","explanation":"مُجْتَهِدَاتٌ adalah khabar bagi الطَّالِبَاتُ. Jamak muannats salim di-rafa'-kan dengan dhammah (tanda asli).","time":25,"options":["Khabar marfu' dengan dhammah (jamak muannats salim)","Mubtada' marfu' dengan dhammah","Na'at marfu' dengan dhammah","Khabar manshub dengan kasrah"],"correct":1,"accepted":[]},{"key":"2d619dc00d54bc600bc6889934562468","cat":"mubtada-khabar","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih khabar yang tepat untuk melengkapi kalimat.","ar":"الْمُسْلِمُونَ ـــــ","explanation":"Khabar marfu' dan sesuai mubtada' (jamak mudzakkar): صَادِقُونَ, dengan wawu sebagai tanda rafa'.","time":25,"options":["صَادِقُونَ","صَادِقِينَ","صَادِقٌ","الصَّادِقِينَ"],"correct":1,"accepted":[]},{"key":"0d51847cde696e90f05eff8214319d4c","cat":"fail","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"نَامَ [[الطِّفْلُ]]","explanation":"الطِّفْلُ adalah pelaku perbuatan نَامَ, maka fa'il, marfu' dengan dhammah.","time":20,"options":["Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Maf'ul bih manshub dengan fathah","Khabar marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"57f85342608886e1d0009c029e0c5336","cat":"fail","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"سَافَرَتْ [[الْمُعَلِّمَاتُ]]","explanation":"الْمُعَلِّمَاتُ adalah fa'il dari سَافَرَتْ. Jamak muannats salim di-rafa'-kan dengan dhammah.","time":25,"options":["Fa'il marfu' dengan dhammah (jamak muannats salim)","Mubtada' marfu' dengan dhammah","Maf'ul bih manshub dengan kasrah","Fa'il marfu' dengan wawu"],"correct":1,"accepted":[]},{"key":"a07d2877bcfed8c24d3c3ac381caf431","cat":"fail","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"كُتِبَ [[الدَّرْسُ]]","explanation":"كُتِبَ adalah fi'il majhul (pasif). Isim marfu' setelahnya disebut naibul fa'il (pengganti fa'il), asalnya maf'ul bih.","time":30,"options":["Naibul fa'il marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Maf'ul bih manshub","Mubtada' marfu'"],"correct":1,"accepted":[]},{"key":"bd5d66f17cbff1480988e09b91ad2d82","cat":"maful-bih","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"فَتَحَ الْوَلَدُ [[النَّافِذَةَ]]","explanation":"النَّافِذَةَ adalah yang dikenai perbuatan فَتَحَ, maka maf'ul bih, manshub dengan fathah.","time":20,"options":["Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan dhammah","Hal manshub dengan fathah","Mudhaf ilaih majrur"],"correct":1,"accepted":[]},{"key":"3c5342130fd7075c2364098e4e2613c7","cat":"maful-bih","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"أَعْطَيْتُ الْفَقِيرَ [[دِرْهَمًا]]","explanation":"أَعْطَى me-nashab-kan dua maf'ul bih: الْفَقِيرَ (pertama) dan دِرْهَمًا (kedua).","time":30,"options":["Maf'ul bih kedua manshub dengan fathah","Tamyiz manshub","Hal manshub","Maf'ul bih pertama manshub"],"correct":1,"accepted":[]},{"key":"de715d4fbfee0cf24f3576c86a11d244","cat":"naat","type":"nahwu_battle","level":"beginner","variety":"fusha","prompt":"Pilih na'at yang tepat untuk melengkapi kalimat.","ar":"هَذَا كِتَابٌ ـــــ","explanation":"Man'ut كِتَابٌ: marfu', nakirah, mudzakkar. Na'at-nya mengikuti: مُفِيدٌ.","time":20,"options":["مُفِيدٌ","مُفِيدًا","الْمُفِيدُ","مُفِيدَةٌ"],"correct":1,"accepted":[]},{"key":"8396fa9eb2c296cdee8d2c181c3b81b1","cat":"naat","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH? (Perhatikan kesesuaian na'at dan man'ut.)","ar":null,"explanation":"قِصَّةً muannats, maka na'at-nya juga muannats: قِصَّةً طَوِيلَةً. Jadi قِصَّةً طَوِيلًا salah.","time":25,"options":["قَرَأْتُ قِصَّةً طَوِيلًا","قَرَأْتُ قِصَّةً طَوِيلَةً","قَرَأْتُ كِتَابًا طَوِيلًا","قَرَأْتُ الْقِصَّةَ الطَّوِيلَةَ"],"correct":1,"accepted":[]},{"key":"f04dbf2f12c218f475cc9687947822ed","cat":"idhafah","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"قَرَأْتُ كِتَابَ [[اللّٰهِ]]","explanation":"Lafzhul jalalah di sini adalah mudhaf ilaih bagi كِتَابَ, maka majrur dengan kasrah.","time":20,"options":["Mudhaf ilaih majrur dengan kasrah","Isim majrur dengan huruf jar","Maf'ul bih manshub","Na'at majrur"],"correct":1,"accepted":[]},{"key":"539861d1be19edca6f7a7c9c824cf95e","cat":"idhafah","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"رَأَيْتُ ـــــ الْمَدْرَسَةِ","explanation":"Maf'ul bih jamak mudzakkar salim yang menjadi mudhaf: manshub dengan ya' dan nunnya dibuang karena idhafah: مُعَلِّمِي الْمَدْرَسَةِ.","time":30,"options":["مُعَلِّمِي","مُعَلِّمِينَ","الْمُعَلِّمِينَ","مُعَلِّمُو"],"correct":1,"accepted":[]},{"key":"2e652fe4dcc48601464af790a1cef6f3","cat":"hal","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"شَرِبْتُ الْمَاءَ [[بَارِدًا]]","explanation":"بَارِدًا menjelaskan keadaan الْمَاءَ saat diminum (dalam keadaan dingin). Hal nakirah dan manshub; shahibul hal-nya ma'rifah.","time":20,"options":["Hal manshub dengan fathah","Na'at manshub dengan fathah","Maf'ul bih kedua","Tamyiz manshub"],"correct":1,"accepted":[]},{"key":"21525835b68ab5908466eee44ddc336a","cat":"hal","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih hal yang tepat untuk melengkapi kalimat.","ar":"رَجَعَتِ الطَّالِبَتَانِ ـــــ","explanation":"Hal manshub, nakirah, dan sesuai shahibul hal (dua perempuan): مَسْرُورَتَيْنِ (mutsanna manshub dengan ya').","time":25,"options":["مَسْرُورَتَيْنِ","مَسْرُورَتَانِ","مَسْرُورَةً","الْمَسْرُورَتَيْنِ"],"correct":1,"accepted":[]},{"key":"1b26510ce861e7325ee3a1eccaeac07e","cat":"tamyiz","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"اِشْتَرَيْتُ عِشْرِينَ [[قَلَمًا]]","explanation":"Tamyiz bilangan 11–99 adalah isim mufrad manshub: عِشْرِينَ قَلَمًا.","time":25,"options":["Tamyiz manshub dengan fathah","Maf'ul bih manshub","Mudhaf ilaih majrur","Hal manshub"],"correct":1,"accepted":[]},{"key":"f64f86595a1b508b29010a5bd353bb7b","cat":"tamyiz","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih tamyiz yang tepat untuk melengkapi kalimat.","ar":"فِي الْمَكْتَبَةِ مِائَةُ ـــــ","explanation":"Tamyiz bilangan مِائَةٌ dan أَلْفٌ adalah isim mufrad majrur sebagai mudhaf ilaih: مِائَةُ كِتَابٍ.","time":30,"options":["كِتَابٍ","كِتَابًا","كُتُبٍ","كُتُبًا"],"correct":1,"accepted":[]},{"key":"72f2c1a82938b21d071b0c7704a3f368","cat":"nawasikh","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"ظَنَنْتُ الْجَوَّ [[حَارًّا]]","explanation":"ظَنَّ termasuk zhanna wa akhawatuha yang me-nashab-kan mubtada' dan khabar sebagai dua maf'ul bih. حَارًّا adalah maf'ul bih kedua.","time":25,"options":["Maf'ul bih kedua (asalnya khabar) manshub","Hal manshub","Na'at manshub","Khabar kana manshub"],"correct":1,"accepted":[]},{"key":"a5925867d29339bf7e3d904150f9d8bc","cat":"nawasikh","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"لَيْسَ الْمُؤْمِنُونَ ـــــ","explanation":"Khabar laisa manshub. Jamak mudzakkar salim di-nashab-kan dengan ya': كَاذِبِينَ.","time":25,"options":["كَاذِبِينَ","كَاذِبُونَ","كَاذِبًا","الْكَاذِبِينَ"],"correct":1,"accepted":[]},{"key":"75f209e853132d50af37d558487a91bc","cat":"majrurat","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"خَرَجْتُ مِنَ [[الْبَيْتِ]]","explanation":"مِنْ adalah huruf jar (nunnya berharakat fathah karena bertemu ال), maka الْبَيْتِ majrur dengan kasrah.","time":20,"options":["Isim majrur dengan kasrah karena huruf jar","Mudhaf ilaih majrur","Maf'ul bih manshub","Na'at majrur"],"correct":1,"accepted":[]},{"key":"0c4a9d92d11cb3ca20ba3502c418bf69","cat":"majrurat","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"مَرَرْتُ بِـ[[أَخِيكَ]]","explanation":"أَخِيكَ majrur oleh بِـ. أَخٌ termasuk al-asma' al-khamsah yang di-jarr-kan dengan ya'.","time":30,"options":["Isim majrur dengan ya' karena asmaul khamsah","Isim majrur dengan kasrah","Isim majrur dengan ya' karena mutsanna","Mudhaf ilaih majrur"],"correct":1,"accepted":[]},{"key":"93fe8832878d6655e6ab0d9839ccf0c0","cat":"tawabi","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ الْخَلِيفَةُ [[عُمَرُ]]","explanation":"عُمَرُ adalah orang yang sama dengan الْخَلِيفَةُ, maka badal kull min kull (badal muthabiq), mengikuti marfu'. Tanpa tanwin karena mamnu' min ash-sharf.","time":25,"options":["Badal kull min kull marfu' dengan dhammah","Na'at marfu'","Taukid marfu'","Khabar marfu'"],"correct":1,"accepted":[]},{"key":"57bead2f3eae792a228b41d00d6206a0","cat":"tawabi","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih taukid yang tepat untuk melengkapi kalimat.","ar":"رَأَيْتُ الطُّلَّابَ ـــــ","explanation":"Taukid mengikuti yang dikuatkan (الطُّلَّابَ manshub), maka كُلَّهُمْ (manshub dengan fathah).","time":30,"options":["كُلَّهُمْ","كُلُّهُمْ","كُلِّهِمْ","كُلًّا"],"correct":1,"accepted":[]},{"key":"d6a4e9802724fa2c23a7b739316cbc07","cat":"anwa-jumal","type":"sentence_analysis","level":"beginner","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"الْجَوُّ جَمِيلٌ","explanation":"Diawali isim (الْجَوُّ, mubtada') diikuti khabar (جَمِيلٌ), maka jumlah ismiyyah.","time":20,"options":["Jumlah ismiyyah","Jumlah fi'liyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"2d6eb2a5193f819e68738d81cd82d270","cat":"anwa-jumal","type":"sentence_analysis","level":"intermediate","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"يَحْفَظُ الطُّلَّابُ الْقُرْآنَ","explanation":"Diawali fi'il mudhari' (يَحْفَظُ), lalu fa'il dan maf'ul bih, maka jumlah fi'liyyah.","time":25,"options":["Jumlah fi'liyyah","Jumlah ismiyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"715025e09640950f8bd4a0660f88cb18","cat":"anwa-jumal","type":"identify_word","level":"beginner","variety":"fusha","prompt":"Kata yang ditandai termasuk jenis kalimah apa?","ar":"ذَهَبْتُ [[إِلَى]] الْمَسْجِدِ","explanation":"إِلَى adalah huruf jar. Ia tidak bermakna sempurna kecuali bersama kata lain.","time":20,"options":["Huruf","Isim","Fi'il"],"correct":1,"accepted":[]},{"key":"0e15eb537695a110dbce25362cc9f7e1","cat":"anwa-jumal","type":"identify_word","level":"intermediate","variety":"fusha","prompt":"Kata yang ditandai termasuk jenis kalimah apa?","ar":"جَاءَ [[الَّذِي]] نَجَحَ","explanation":"الَّذِي adalah isim maushul (kata sambung), termasuk isim mabni. Di sini berkedudukan sebagai fa'il.","time":25,"options":["Isim","Huruf","Fi'il"],"correct":1,"accepted":[]},{"key":"4614bfe594de91c5416e882e23a9f544","cat":"madhi","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk fi'il apa?","ar":"شَرِبَ","explanation":"شَرِبَ adalah fi'il madhi: perbuatan lampau, diakhiri fathah, tanpa huruf mudhara'ah.","time":20,"options":["Fi'il madhi","Fi'il mudhari'","Fi'il amr"],"correct":1,"accepted":[]},{"key":"e0b9610df2cd37187005dbf07122d9a7","cat":"madhi","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Ubah كَتَبَ untuk dhamir هُنَّ.","ar":null,"explanation":"هُنَّ → nun niswah, huruf sebelumnya disukunkan: كَتَبْنَ. كَتَبْتُنَّ untuk أَنْتُنَّ.","time":25,"options":["كَتَبْنَ","كَتَبُوا","كَتَبْتُنَّ","كَتَبَتْ"],"correct":1,"accepted":[]},{"key":"84e7dd0ca00c2f0724ae981d283c0cc9","cat":"madhi","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Ubah مَشَى untuk dhamir أَنَا.","ar":null,"explanation":"مَشَى naqish ya'i (asal مَشَيَ). Saat bersambung dengan ta' fa'il, alif kembali ke asal ya': مَشَيْتُ.","time":30,"options":["مَشَيْتُ","مَشَوْتُ","مَشْتُ","مَشَاتُ"],"correct":1,"accepted":[]},{"key":"9effab7b4499f2c02035a66bef708356","cat":"mudhari","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk fi'il apa?","ar":"نَكْتُبُ","explanation":"نَكْتُبُ diawali huruf mudhara'ah نَـ (kami), maka fi'il mudhari'.","time":20,"options":["Fi'il mudhari'","Fi'il madhi","Fi'il amr"],"correct":1,"accepted":[]},{"key":"7a0bed9076b01c7bc1fa96d5108adcf2","cat":"mudhari","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il mudhari' dari ذَهَبَ untuk dhamir هُمَا?","ar":null,"explanation":"هُمَا (mudzakkar) → يَـ + alif itsnain + nun: يَذْهَبَانِ. تَذْهَبَانِ untuk أَنْتُمَا atau هُمَا muannats.","time":25,"options":["يَذْهَبَانِ","تَذْهَبَانِ","يَذْهَبُونَ","يَذْهَبْنَ"],"correct":1,"accepted":[]},{"key":"bf2d8ff6cdcfaa29f666de5ecff3298e","cat":"mudhari","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il mudhari' dari اِسْتَغْفَرَ untuk dhamir أَنَا?","ar":null,"explanation":"اِسْتَغْفَرَ (wazan اِسْتَفْعَلَ) → mudhari' يَسْتَفْعِلُ. Untuk أَنَا: أَسْتَغْفِرُ (huruf mudhara'ah fathah karena fi'il-nya enam huruf).","time":30,"options":["أَسْتَغْفِرُ","أَسْتَغْفَرُ","أُسْتَغْفِرُ","اِسْتَغْفِرُ"],"correct":1,"accepted":[]},{"key":"068c60e99fc89c49476f779229a81fa2","cat":"amr","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa fi'il amr dari يَجْلِسُ (untuk أَنْتَ)?","ar":null,"explanation":"Buang huruf mudhara'ah, sukunkan akhir, tambah hamzah washl berkasrah (karena 'ain fi'il kasrah): اِجْلِسْ.","time":20,"options":["اِجْلِسْ","اُجْلُسْ","جْلِسْ","تَجْلِسْ"],"correct":1,"accepted":[]},{"key":"0138cd96f012e2ef22f899d020ccfbac","cat":"amr","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il amr dari يَقْرَأُ untuk dhamir أَنْتُمْ?","ar":null,"explanation":"Amr untuk أَنْتُمْ: buang huruf mudhara'ah dan nun, tambah hamzah washl berkasrah: اِقْرَءُوا (juga ditulis اِقْرَؤُوا).","time":25,"options":["اِقْرَءُوا","اُقْرُءُوا","اِقْرَأْ","تَقْرَءُونَ"],"correct":1,"accepted":[]},{"key":"bf6b2fa965e1a62c501e9de5b4828666","cat":"amr","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il amr dari يَقِفُ (untuk أَنْتَ)?","ar":null,"explanation":"يَقِفُ dari وَقَفَ (mitsal wawi, wawunya hilang pada mudhari'). Buang huruf mudhara'ah: قِفُ → قِفْ. Tidak perlu hamzah washl karena huruf pertama berharakat.","time":30,"options":["قِفْ","اِقِفْ","وَقِفْ","اِوْقِفْ"],"correct":1,"accepted":[]},{"key":"6622eaaa864183acc3abab869bf9883b","cat":"mashdar","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa mashdar dari فَتَحَ?","ar":null,"explanation":"Mashdar فَتَحَ adalah فَتْحٌ (pembukaan). مِفْتَاحٌ isim alat, فَاتِحٌ isim fa'il, مَفْتُوحٌ isim maf'ul.","time":20,"options":["فَتْحٌ","مِفْتَاحٌ","فَاتِحٌ","مَفْتُوحٌ"],"correct":1,"accepted":[]},{"key":"354ffb643ff2285cdfe88c4e827bec9a","cat":"mashdar","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa mashdar dari اِنْطَلَقَ?","ar":null,"explanation":"اِنْطَلَقَ berwazan اِنْفَعَلَ, mashdarnya اِنْفِعَالٌ: اِنْطِلَاقٌ. إِطْلَاقٌ mashdar أَطْلَقَ, تَطْلِيقٌ mashdar طَلَّقَ.","time":25,"options":["اِنْطِلَاقٌ","تَطْلِيقٌ","إِطْلَاقٌ","مُنْطَلَقٌ"],"correct":1,"accepted":[]},{"key":"c2d52e2c05b45f85c8ae01f0f6a15ded","cat":"mashdar","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa mashdar dari تَعَلَّمَ?","ar":null,"explanation":"تَعَلَّمَ berwazan تَفَعَّلَ, mashdarnya تَفَعُّلٌ: تَعَلُّمٌ (belajar). تَعْلِيمٌ mashdar عَلَّمَ (mengajar).","time":30,"options":["تَعَلُّمٌ","تَعْلِيمٌ","تَعَالُمٌ","عِلْمٌ"],"correct":1,"accepted":[]},{"key":"8ea822b5774436540685e942de2858b4","cat":"isim-fail","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim fa'il dari نَصَرَ?","ar":null,"explanation":"Isim fa'il tsulatsi berwazan فَاعِلٌ: نَاصِرٌ (penolong). مَنْصُورٌ isim maf'ul, نَصْرٌ mashdar.","time":20,"options":["نَاصِرٌ","مَنْصُورٌ","نَصْرٌ","نَصِيرٌ"],"correct":1,"accepted":[]},{"key":"d3fed55b44940d26bb012e4e4759267a","cat":"isim-fail","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa isim fa'il dari أَسْلَمَ?","ar":null,"explanation":"Dari يُسْلِمُ: ganti huruf mudhara'ah dengan مُـ, kasrahkan huruf sebelum akhir: مُسْلِمٌ. إِسْلَامٌ adalah mashdarnya.","time":25,"options":["مُسْلِمٌ","مُسْلَمٌ","سَالِمٌ","إِسْلَامٌ"],"correct":1,"accepted":[]},{"key":"c47a49305cc923ad48b315338035e3ad","cat":"isim-maful","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim maf'ul dari عَلِمَ?","ar":null,"explanation":"Isim maf'ul tsulatsi berwazan مَفْعُولٌ: مَعْلُومٌ (yang diketahui).","time":20,"options":["مَعْلُومٌ","عَالِمٌ","مُعَلَّمٌ","عِلْمٌ"],"correct":1,"accepted":[]},{"key":"421b79fcf2a9fafb81bf708ac9a34fde","cat":"isim-maful","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa isim maf'ul dari قَالَ?","ar":null,"explanation":"Wazan مَفْعُولٌ dari قَوَلَ asalnya مَقْوُولٌ, lalu diringkas (i'lal) menjadi مَقُولٌ (yang dikatakan).","time":30,"options":["مَقُولٌ","مَقْوُولٌ","قَائِلٌ","مُقَالٌ"],"correct":1,"accepted":[]},{"key":"32659dce308ecaa4f7dd2ab8a48100c3","cat":"tashrif","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Fi'il فَتَحَ – يَفْتَحُ termasuk bab apa?","ar":null,"explanation":"فَتَحَ – يَفْتَحُ: 'ain madhi fathah, 'ain mudhari' fathah, yaitu bab ke-3 (فَعَلَ – يَفْعَلُ). Bab ini umumnya 'ain atau lam fi'il-nya huruf halq (ح).","time":25,"options":["فَعَلَ – يَفْعَلُ","فَعَلَ – يَفْعُلُ","فَعَلَ – يَفْعِلُ","فَعِلَ – يَفْعَلُ"],"correct":1,"accepted":[]},{"key":"554178c97d73899b28c4f388a16207be","cat":"tashrif","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Fi'il عَلِمَ – يَعْلَمُ termasuk bab apa?","ar":null,"explanation":"عَلِمَ – يَعْلَمُ: 'ain madhi kasrah, 'ain mudhari' fathah, yaitu bab ke-4 (فَعِلَ – يَفْعَلُ).","time":30,"options":["فَعِلَ – يَفْعَلُ","فَعِلَ – يَفْعِلُ","فَعَلَ – يَفْعَلُ","فَعُلَ – يَفْعُلُ"],"correct":1,"accepted":[]},{"key":"5c72283e06ecd63d00f4cd19166adf35","cat":"mizan","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"جَلَسَ","explanation":"Huruf asli ج–ل–س semuanya berharakat fathah: فَعَلَ.","time":20,"options":["فَعَلَ","فَاعَلَ","فَعِلَ","فَعَّلَ"],"correct":1,"accepted":[]},{"key":"cfc1b1f33bea8b11749cf98c3f948ed7","cat":"mizan","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"مُجْتَهِدٌ","explanation":"Huruf asli ج–ه–د; tambahan mim di depan dan ta' setelah fa' fi'il: مُفْتَعِلٌ (isim fa'il dari اِجْتَهَدَ).","time":25,"options":["مُفْتَعِلٌ","مُفَاعِلٌ","مُفْعِلٌ","مُسْتَفْعِلٌ"],"correct":1,"accepted":[]},{"key":"9464c157a1c07f75ea3cd7940f7ce079","cat":"mizan","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"كُتُبٌ","explanation":"Huruf asli ك–ت–ب dengan dhammah pada fa' dan 'ain: فُعُلٌ (salah satu wazan jamak taksir).","time":30,"options":["فُعُلٌ","فُعُولٌ","فِعَالٌ","أَفْعَالٌ"],"correct":1,"accepted":[]},{"key":"0720f265c8808605fb0d6fe190a18d3e","cat":"mujarrad-mazid","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk mujarrad atau mazid?","ar":"أَكْرَمَ","explanation":"Huruf asli ك–ر–م; tambahannya hamzah di depan (wazan أَفْعَلَ): mazid satu huruf.","time":25,"options":["Tsulatsi mazid satu huruf","Tsulatsi mujarrad","Tsulatsi mazid dua huruf","Ruba'i mujarrad"],"correct":1,"accepted":[]},{"key":"c37629b21b799548413e386a47efc968","cat":"mujarrad-mazid","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Faedah (makna) wazan أَفْعَلَ pada kata berikut adalah …","ar":"أَجْلَسَ","explanation":"جَلَسَ (duduk) intransitif; أَجْلَسَ = mendudukkan (seseorang). Hamzah أَفْعَلَ di sini untuk ta'diyah.","time":30,"options":["Ta'diyah (menjadikan transitif)","Musyarakah (saling)","Thalab (meminta)","Muthawa'ah"],"correct":1,"accepted":[]},{"key":"1b7f2ab8c6d6f2a66a7a52e503af0f23","cat":"shahih-mutal","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Fi'il berikut termasuk jenis apa?","ar":"صَامَ","explanation":"'Ain fi'il-nya huruf illat (asal wawu: صَوَمَ, mudhari'-nya يَصُومُ), maka disebut ajwaf (ajwaf wawi).","time":20,"options":["Ajwaf","Mitsal","Naqish","Shahih salim"],"correct":1,"accepted":[]},{"key":"26079b1a8027670cdb6b603a90cb4716","cat":"shahih-mutal","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk jenis apa?","ar":"أَخَذَ","explanation":"Fa' fi'il-nya hamzah, maka disebut mahmuz (mahmuz al-fa'). Hamzah bukan huruf illat, jadi tetap fi'il shahih.","time":25,"options":["Shahih mahmuz","Shahih salim","Mitsal","Shahih mudha'af"],"correct":1,"accepted":[]},{"key":"645455bb566b9884bccc3c1229057fe2","cat":"rafa","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"أَحْمَدُ [[يَذْهَبُ]] إِلَى الْمَدْرَسَةِ","explanation":"يَذْهَبُ adalah fi'il mudhari' yang tidak didahului 'amil nashab atau jazm, maka marfu' dengan dhammah. Jumlah يَذْهَبُ ... menjadi khabar bagi أَحْمَدُ.","time":20,"options":["Fi'il mudhari' marfu' dengan dhammah","Fi'il mudhari' manshub dengan fathah","Fi'il mudhari' majzum dengan sukun","Isim marfu' sebagai khabar"],"correct":1,"accepted":[]},{"key":"75ee3008f599e997028c87091d7264f8","cat":"nashab","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جِئْتُ كَيْ [[أَتَعَلَّمَ]]","explanation":"كَيْ termasuk huruf nashab (أَنْ، لَنْ، كَيْ، إِذَنْ), maka أَتَعَلَّمَ manshub dengan fathah.","time":25,"options":["Fi'il mudhari' manshub dengan fathah karena كَيْ","Fi'il mudhari' marfu'","Fi'il mudhari' majzum","Fi'il madhi mabni"],"correct":1,"accepted":[]},{"key":"65501e9c00c65cbb110c88181cd051c9","cat":"jazm","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَمْ [[يَحْضُرُوا]] الدَّرْسَ","explanation":"لَمْ men-jazm-kan. يَحْضُرُوا (al-af'al al-khamsah) majzum dengan dibuangnya nun.","time":25,"options":["Fi'il mudhari' majzum dengan hadzf an-nun","Fi'il mudhari' manshub dengan hadzf an-nun","Fi'il mudhari' majzum dengan sukun","Fi'il madhi mabni"],"correct":1,"accepted":[]},{"key":"d8b723be69ae2b8f774861be61f76a9e","cat":"jazm","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"لَا ـــــ فِي الْفَصْلِ","explanation":"لَا nahiyah (larangan) men-jazm-kan fi'il mudhari': لَا تَلْعَبْ (jangan bermain).","time":25,"options":["تَلْعَبْ","تَلْعَبُ","تَلْعَبَ","لَعِبْتَ"],"correct":1,"accepted":[]},{"key":"692d91e308f7b59b8180181e20bddf45","cat":"alamat-irab","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Jamak mudzakkar salim ketika manshub dan majrur ditandai dengan …","ar":null,"explanation":"Jamak mudzakkar salim: rafa' dengan wawu (الْمُسْلِمُونَ), nashab dan jarr dengan ya' (الْمُسْلِمِينَ).","time":25,"options":["Ya'","Kasrah","Fathah","Alif"],"correct":1,"accepted":[]},{"key":"cf240a33518cbba084fd46f722bf2ad5","cat":"irab-jumlah","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"صُمْتُ [[يَوْمَ]] الْخَمِيسِ","explanation":"يَوْمَ menjelaskan waktu perbuatan (puasa pada hari Kamis), maka maf'ul fih/zharaf zaman, manshub dengan fathah, sekaligus mudhaf.","time":30,"options":["Maf'ul fih (zharaf zaman) manshub dengan fathah","Maf'ul bih manshub","Hal manshub","Mubtada' marfu'"],"correct":1,"accepted":[]}]$j$::jsonb) loop
    if not exists (select 1 from categories where slug = q->>'cat') then
      raise exception 'Kategori % tidak ada', q->>'cat';
    end if;
    v_q := null;
    insert into questions (seed_key, category_id, game_type, difficulty, variety, prompt, prompt_ar, explanation, time_limit_sec, is_published)
    select q->>'key', id, (q->>'type')::game_type, (q->>'level')::difficulty, (q->>'variety')::arabic_variety,
           q->>'prompt', q->>'ar', q->>'explanation', (q->>'time')::int, true
    from categories where slug = q->>'cat'
    on conflict (seed_key) do nothing
    returning id into v_q;
    continue when v_q is null;   -- sudah ada
    v_added := v_added + 1;

    for i in 0 .. jsonb_array_length(q->'options') - 1 loop
      insert into answer_options (question_id, label, is_arabic, position)
      values (v_q, q->'options'->>i, (q->'options'->>i) ~ '[\u0600-\u06FF]', i + 1);
    end loop;

    -- correct null = soal susun kalimat (dinilai lewat accepted_texts)
    v_correct := null;
    select id into v_correct from answer_options
    where question_id = v_q and position = (q->>'correct')::int;

    insert into answer_keys (question_id, correct_option_id, accepted_texts)
    values (v_q, v_correct, array(select jsonb_array_elements_text(q->'accepted')));
  end loop;
  raise notice 'Soal baru ditambahkan: %', v_added;
end
$seed$;
